interface EpisodeGroupProps {
  group: {
    episodeNumber: number;
    title: string | null;
    existingEpisodeId: number | null;
    fillerType: string | null;
    fillerNote: string | null;
    coveredEpisodes: Array<{
      episodeNumber: number;
      title: string | null;
      fillerType: string | null;
    }>;
    lastCoveredEpisodeNumber: number;
    rows: EpisodeImportMappingRow[];
  };
  hasVisualGap: boolean;
  onSetTargets: (mediaItemID: string, rawTargets: string) => void;
  onSetRelease: (
    mediaItemID: string,
    meta: { fansubGroupName?: string; releaseVersion?: string },
  ) => void;
  onSetSelectedFansubGroups: (
    mediaItemID: string,
    fansubGroups: EpisodeImportSelectedFansubGroup[],
  ) => void;
  onAddSelectedFansubGroup: (
    mediaItemID: string,
    fansubGroup: EpisodeImportSelectedFansubGroup,
  ) => void;
  onRemoveSelectedFansubGroup: (
    mediaItemID: string,
    fansubGroup: EpisodeImportSelectedFansubGroup,
  ) => void;
  onApplyFansubGroupToEpisode: (
    episodeNumber: number,
    fansubGroups: EpisodeImportSelectedFansubGroup[],
  ) => void;
  onApplyFansubGroupFromEpisode: (
    episodeNumber: number,
    fansubGroups: EpisodeImportSelectedFansubGroup[],
  ) => void;
  onSetEpisodeTitle: (episodeNumber: number, title: string) => void;
  onSkip: (mediaItemID: string) => void;
  onApplyRow: (mediaItemID: string) => void;
  applyingRowId: string | null;
  onConfirmEpisode: (episodeNumber: number) => void;
  onSkipEpisode: (episodeNumber: number) => void;
}

function EpisodeGroup({
  group,
  hasVisualGap,
  onSetTargets,
  onSetRelease,
  onSetSelectedFansubGroups,
  onAddSelectedFansubGroup,
  onRemoveSelectedFansubGroup,
  onApplyFansubGroupToEpisode,
  onApplyFansubGroupFromEpisode,
  onSetEpisodeTitle,
  onSkip,
  onApplyRow,
  applyingRowId,
  onConfirmEpisode,
  onSkipEpisode,
}: EpisodeGroupProps) {
  const hasActionable = group.rows.some(
    (row) => row.status === "suggested" || row.status === "conflict",
  );

  return (
    <div className={styles.episodeGroup}>
      <div
        className={`${styles.episodeGroupHeader} ${hasVisualGap ? styles.episodeGroupHeaderGap : ""}`}
      >
        <div className={styles.episodeGroupMeta}>
          <span
            className={`${styles.episodeGroupNumber} ${hasVisualGap ? styles.episodeGroupNumberGap : ""}`}
          >
            #{group.episodeNumber}
          </span>
          <div className={styles.episodeTitleBlock}>
            <label className={styles.episodeTitleEditor}>
              <span className={styles.episodeTitleLabel}>Titel (DE)</span>
              <textarea
                className={styles.episodeTitleInput}
                rows={2}
                value={group.title ?? ""}
                placeholder={`Episode ${group.episodeNumber}`}
                aria-label={`Deutscher Titel für Episode ${group.episodeNumber}`}
                onChange={(event) =>
                  onSetEpisodeTitle(group.episodeNumber, event.target.value)
                }
              />
            </label>
            <div className={styles.episodeGroupBadges}>
              {group.existingEpisodeId ? (
                <span className={styles.existingBadge}>lokal vorhanden</span>
              ) : null}
              {fillerLabel(group.fillerType) ? (
                <span
                  className={`${styles.fillerBadge} ${styles[`filler_${group.fillerType ?? ""}`] ?? ""}`}
                  title={group.fillerNote ?? undefined}
                >
                  {fillerLabel(group.fillerType)}
                </span>
              ) : null}
            </div>
            {group.coveredEpisodes.length > 0 ? (
              <div className={styles.coveredEpisodeList}>
                {group.coveredEpisodes.map((coveredEpisode) => (
                  <div
                    key={coveredEpisode.episodeNumber}
                    className={styles.coveredEpisodeItem}
                  >
                    <label className={styles.coveredEpisodeEditor}>
                      <span className={styles.coveredEpisodeNumber}>
                        #{coveredEpisode.episodeNumber}
                      </span>
                      <textarea
                        className={`${styles.episodeTitleInput} ${styles.coveredEpisodeInput}`}
                        rows={2}
                        value={coveredEpisode.title ?? ""}
                        placeholder={`Episode ${coveredEpisode.episodeNumber}`}
                        aria-label={`Deutscher Titel für Episode ${coveredEpisode.episodeNumber}`}
                        onChange={(event) =>
                          onSetEpisodeTitle(
                            coveredEpisode.episodeNumber,
                            event.target.value,
                          )
                        }
                      />
                    </label>
                    {fillerLabel(coveredEpisode.fillerType) ? (
                      <span
                        className={`${styles.fillerBadge} ${styles[`filler_${coveredEpisode.fillerType ?? ""}`] ?? ""}`}
                      >
                        {fillerLabel(coveredEpisode.fillerType)}
                      </span>
                    ) : null}
                  </div>
                ))}
              </div>
            ) : null}
          </div>
        </div>
        {hasActionable ? (
          <div className={styles.episodeGroupActions}>
            <button
              className={styles.microButton}
              type="button"
              onClick={() => onConfirmEpisode(group.episodeNumber)}
            >
              Alle bestätigen
            </button>
            <button
              className={styles.microButton}
              type="button"
              onClick={() => onSkipEpisode(group.episodeNumber)}
            >
              Alle ueberspringen
            </button>
          </div>
        ) : null}
      </div>
      <div className={styles.mappingList}>
        {group.rows.map((row) => (
          <EpisodeImportMappingRowCard
            key={row.media_item_id}
            episodeNumber={group.episodeNumber}
            row={row}
            onSetTargets={onSetTargets}
            onSetRelease={onSetRelease}
            onSetSelectedFansubGroups={onSetSelectedFansubGroups}
            onAddSelectedFansubGroup={onAddSelectedFansubGroup}
            onRemoveSelectedFansubGroup={onRemoveSelectedFansubGroup}
            onApplyFansubGroupToEpisode={onApplyFansubGroupToEpisode}
            onApplyFansubGroupFromEpisode={onApplyFansubGroupFromEpisode}
            onSkip={onSkip}
            onApplyRow={onApplyRow}
            isApplyingRow={applyingRowId === row.media_item_id}
          />
        ))}
      </div>
    </div>
  );
}

function ContextField({
  label,
  value,
  mono = false,
}: {
  label: string;
  value: string;
  mono?: boolean;
}) {
  return (
    <div className={styles.contextField}>
      <span className={styles.contextFieldLabel}>{label}</span>
      <span
        className={
          mono ? styles.contextFieldValueMono : styles.contextFieldValue
        }
      >
        {value}
      </span>
    </div>
  );
}

function SummaryPill({
  label,
  value,
  tone,
}: {
  label: string;
  value: number;
  tone?: "good" | "danger" | "neutral";
}) {
  const cls = [
    styles.summaryPill,
    tone === "good" ? styles.summaryPillGood : "",
    tone === "danger" ? styles.summaryPillDanger : "",
    tone === "neutral" ? styles.summaryPillNeutral : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={cls}>
      <strong>{value}</strong>
      <span>{label}</span>
    </div>
  );
}

"use client";

import Link from "next/link";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { useParams } from "next/navigation";

import {
  createAdminEpisode,
  getAnimeByID,
  getFansubs,
  getGroupedEpisodes,
} from "@/lib/api";
import { PlatformAdminGate } from "@/components/auth/PlatformAdminGate";
import { useAuthSession } from "@/lib/useAuthSession";
import { AnimeDetail, EpisodeStatus } from "@/types/anime";
import { FansubGroup } from "@/types/fansub";
import { GroupedEpisode } from "@/types/episodeVersion";
import { EpisodesOverview } from "@/components/episodes/EpisodesOverview";

import styles from "../../AdminStudio.module.css";
import {
  parsePositiveInt,
  formatEpisodeStatusLabel,
} from "../../utils/anime-helpers";
import {
  formatAdminError,
  normalizeOptionalText,
} from "../../utils/studio-helpers";

const EPISODE_STATUSES: EpisodeStatus[] = ["disabled", "private", "public"];

function AdminAnimeEpisodesContent() {
  const params = useParams<{ id: string }>();
  const animeID = useMemo(
    () => parsePositiveInt((params.id || "").trim()),
    [params.id],
  );

  const { hasAccessToken, hasRefreshToken } = useAuthSession();
  const [anime, setAnime] = useState<AnimeDetail | null>(null);
  const [groupedEpisodes, setGroupedEpisodes] = useState<GroupedEpisode[]>([]);
  const [fansubs, setFansubs] = useState<FansubGroup[]>([]);
  const [isLoadingAnime, setIsLoadingAnime] = useState(true);
  const [isLoadingVersions, setIsLoadingVersions] = useState(false);
  const [isCreating, setIsCreating] = useState(false);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [versionsErrorMessage, setVersionsErrorMessage] = useState<
    string | null
  >(null);
  const [fansubsErrorMessage, setFansubsErrorMessage] = useState<string | null>(
    null,
  );
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [formState, setFormState] = useState({
    number: "",
    title: "",
    status: "disabled" as EpisodeStatus,
  });

  useEffect(() => {
    async function loadAnime() {
      if (!animeID) {
        setErrorMessage("Ungültige Anime-ID.");
        setIsLoadingAnime(false);
        return;
      }

      setIsLoadingAnime(true);
      setErrorMessage(null);

      try {
        const response = await getAnimeByID(animeID, {
          include_disabled: true,
        });
        setAnime(response.data);
      } catch (error) {
        setAnime(null);
        setErrorMessage(
          formatAdminError(error, "Episoden konnten nicht geladen werden."),
        );
      } finally {
        setIsLoadingAnime(false);
      }
    }

    void loadAnime();
  }, [animeID]);

  useEffect(() => {
    async function loadGroupedEpisodes() {
      if (!animeID) {
        return;
      }

      setIsLoadingVersions(true);
      setVersionsErrorMessage(null);

      try {
        const response = await getGroupedEpisodes(animeID);
        setGroupedEpisodes(response.data.episodes);
      } catch (error) {
        setVersionsErrorMessage(
          formatAdminError(error, "Versionen konnten nicht geladen werden."),
        );
        setGroupedEpisodes([]);
      } finally {
        setIsLoadingVersions(false);
      }
    }

    void loadGroupedEpisodes();
  }, [animeID]);

  useEffect(() => {
    async function loadFansubs() {
      setFansubsErrorMessage(null);

      try {
        const response = await getFansubs();
        setFansubs(response.data);
      } catch (error) {
        setFansubs([]);
        setFansubsErrorMessage(
          formatAdminError(error, "Fansub-Gruppen konnten nicht geladen werden."),
        );
      }
    }

    void loadFansubs();
  }, []);

  const episodeCount = useMemo(
    () => groupedEpisodes.length,
    [groupedEpisodes],
  );

  async function handleCreateEpisode(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setErrorMessage(null);
    setSuccessMessage(null);

    if (!animeID) {
      setErrorMessage("Ungültige Anime-ID.");
      return;
    }

    if (!hasAccessToken && !hasRefreshToken) {
      setErrorMessage(
        "Anmeldung erforderlich. Bitte zuerst anmelden.",
      );
      return;
    }

    const parsedEpisodeNumber = parsePositiveInt(formState.number);
    if (!parsedEpisodeNumber) {
      setErrorMessage("Die Episodennummer muss groesser als 0 sein.");
      return;
    }

    setIsCreating(true);
    try {
      await createAdminEpisode({
        anime_id: animeID,
        episode_number: String(parsedEpisodeNumber),
        title: normalizeOptionalText(formState.title) || undefined,
        status: formState.status,
      });

      const [refreshedAnime, refreshedVersions] = await Promise.all([
        getAnimeByID(animeID, { include_disabled: true }),
        getGroupedEpisodes(animeID),
      ]);

      setAnime(refreshedAnime.data);
      setGroupedEpisodes(refreshedVersions.data.episodes);
      setFormState({ number: "", title: "", status: "disabled" });
      setShowCreateForm(false);
      setSuccessMessage(`Episode ${parsedEpisodeNumber} wurde angelegt.`);
    } catch (error) {
      setErrorMessage(
        formatAdminError(error, "Episode konnte nicht angelegt werden."),
      );
    } finally {
      setIsCreating(false);
    }
  }

  return (
    <main className={styles.page}>
      <nav className={styles.breadcrumbs} aria-label="Breadcrumb">
        <Link href="/admin">Admin</Link>
        <span>/</span>
        <Link href="/admin/anime">Anime</Link>
        <span>/</span>
        <Link href={animeID ? `/admin/anime/${animeID}/edit` : "/admin/anime"}>
          Bearbeiten
        </Link>
        <span>/</span>
        <span>Episoden</span>
      </nav>

      <header className={styles.headerCard}>
        <div>
          <p className={styles.eyebrow}>Schritt 3</p>
          <h1 className={styles.pageTitle}>Episoden-Übersicht</h1>
          <p className={styles.pageSubtitle}>
            Episoden mit allen Versionen, Fansub-Zuordnungen und Version-Counts
            pro Episode. Accordion zeigt Details bei Bedarf.
          </p>
        </div>
        {anime ? (
          <div className={styles.headerActions}>
            <Link
              href={`/admin/anime/${anime.id}/edit`}
              className={`${styles.button} ${styles.buttonSecondary}`}
            >
              Zurück zum Anime
            </Link>
            <Link
              href={`/admin/anime/${anime.id}/episodes/import`}
              className={`${styles.button} ${styles.buttonSecondary}`}
            >
              Import & Mapping
            </Link>
            <button
              className={`${styles.button} ${styles.buttonPrimary}`}
              type="button"
              onClick={() => setShowCreateForm((current) => !current)}
            >
              {showCreateForm ? "Erstellen schließen" : "Neue Episode"}
            </button>
          </div>
        ) : null}
      </header>

      {isLoadingAnime ? (
        <div className={styles.noticeBox}>Episoden werden geladen...</div>
      ) : null}
      {errorMessage ? (
        <div className={styles.errorBox}>{errorMessage}</div>
      ) : null}
      {successMessage ? (
        <div className={styles.successBox}>{successMessage}</div>
      ) : null}

      {anime ? (
        <>
          <section className={styles.card}>
            <div className={styles.summaryGrid}>
              <div className={styles.summaryCard}>
                <p className={styles.summaryLabel}>Anime</p>
                <p className={styles.summaryValue}>{anime.title}</p>
              </div>
              <div className={styles.summaryCard}>
                <p className={styles.summaryLabel}>Episoden</p>
                <p className={styles.summaryValue}>{episodeCount}</p>
              </div>
              <div className={styles.summaryCard}>
                <p className={styles.summaryLabel}>Versionen gesamt</p>
                <p className={styles.summaryValue}>
                  {groupedEpisodes.reduce(
                    (sum, ep) => sum + ep.version_count,
                    0,
                  )}
                </p>
              </div>
            </div>
          </section>

          {showCreateForm ? (
            <section className={styles.card}>
              <div className={styles.sectionHeader}>
                <div>
                  <h2 className={styles.sectionTitle}>Neue Episode anlegen</h2>
                  <p className={styles.sectionMeta}>
                    Neue Episode im gleichen Anime-Kontext erstellen.
                  </p>
                </div>
              </div>

              <form
                className={styles.stack}
                onSubmit={(event) => void handleCreateEpisode(event)}
              >
                <div className={styles.formGrid}>
                  <label className={styles.field}>
                    <span>Episodennummer</span>
                    <input
                      className={styles.input}
                      value={formState.number}
                      onChange={(event) =>
                        setFormState((current) => ({
                          ...current,
                          number: event.target.value,
                        }))
                      }
                      required
                    />
                  </label>

                  <label className={styles.field}>
                    <span>Status</span>
                    <select
                      className={styles.select}
                      value={formState.status}
                      onChange={(event) =>
                        setFormState((current) => ({
                          ...current,
                          status: event.target.value as EpisodeStatus,
                        }))
                      }
                    >
                      {EPISODE_STATUSES.map((status) => (
                        <option key={status} value={status}>
                          {formatEpisodeStatusLabel(status)}
                        </option>
                      ))}
                    </select>
                  </label>

                  <label className={`${styles.field} ${styles.fieldWide}`}>
                    <span>Titel</span>
                    <input
                      className={styles.input}
                      value={formState.title}
                      onChange={(event) =>
                        setFormState((current) => ({
                          ...current,
                          title: event.target.value,
                        }))
                      }
                    />
                  </label>
                </div>

                <div className={styles.actionsRow}>
                  <button
                    className={`${styles.button} ${styles.buttonSuccess}`}
                    type="submit"
                    disabled={isCreating}
                  >
                    {isCreating ? "Speichert..." : "Episode speichern"}
                  </button>
                  <button
                    className={`${styles.button} ${styles.buttonSecondary}`}
                    type="button"
                    disabled={isCreating}
                    onClick={() => setShowCreateForm(false)}
                  >
                    Abbrechen
                  </button>
                </div>
              </form>
            </section>
          ) : null}

          <section className={styles.card}>
            <div className={styles.sectionHeader}>
              <div>
                <h2 className={styles.sectionTitle}>Episoden mit Versionen</h2>
                <p className={styles.sectionMeta}>
                  Accordion-Ansicht mit Version-Counts, Fansub-Badges und
                  direkten Bearbeitungslinks. Der normale Staffel-Import bleibt
                  der Jellyfin Saison-Sync im Anime-Editor.
                </p>
              </div>
            </div>

            {versionsErrorMessage ? (
              <div className={styles.errorBox}>{versionsErrorMessage}</div>
            ) : null}

            {fansubsErrorMessage ? (
              <div className={styles.errorBox}>{fansubsErrorMessage}</div>
            ) : null}

            <EpisodesOverview
              episodes={groupedEpisodes}
              episodeItems={anime.episodes}
              fansubs={fansubs}
              isLoading={isLoadingVersions}
              error={versionsErrorMessage}
              onRefresh={async () => {
                if (!animeID) return;
                const response = await getGroupedEpisodes(animeID);
                setGroupedEpisodes(response.data.episodes);
              }}
            />
          </section>
        </>
      ) : null}
    </main>
  );
}

