function formatSourceKindLabel(kind?: 'manual' | 'jellyfin'): string {
  if (kind === 'jellyfin') return 'Jellyfin'
  return 'Manuell'
}

function hasProviderSource(
  prefix: 'anisearch:' | 'jellyfin:',
  source?: string | null,
  sourceLinks?: string[] | null,
): boolean {
  const normalizedPrefix = prefix.toLowerCase()
  if ((source || '').trim().toLowerCase().startsWith(normalizedPrefix)) return true
  return (sourceLinks ?? []).some((value) => value.trim().toLowerCase().startsWith(normalizedPrefix))
}

export function AnimeEditWorkspace({
  anime,
  onSaved,
  onError,
  onRequest,
  onResponse,
}: AnimeEditWorkspaceProps) {
  const patch = useAnimePatch(
    (nextAnime) => onSaved(nextAnime, `Anime #${nextAnime.id} wurde gespeichert.`),
    onError,
    { onRequest, onResponse },
  )

  const hydratedState = useMemo(
    () =>
      hydrateManualDraftFromExistingAnime({
        title: anime.title,
        title_de: anime.title_de,
        title_en: anime.title_en,
        type: anime.type,
        content_type: anime.content_type,
        status: anime.status,
        year: anime.year,
        max_episodes: anime.max_episodes,
        genre: anime.genre,
        genres: anime.genres,
        tags: anime.tags,
        description: anime.description,
        cover_image: anime.cover_image,
        source: anime.source,
        folder_name: anime.folder_name,
        persisted_assets: anime.persisted_assets ?? undefined,
      }),
    [anime],
  )

  const [persistedAssets, setPersistedAssets] = useState<AdminAnimePersistedAssets>(
    hydratedState.persistedAssets,
  )
  const [jellyfinContext, setJellyfinContext] = useState<AdminAnimeJellyfinContext | null>(null)
  const [visibleJellyfinAssetSlots, setVisibleJellyfinAssetSlots] = useState<AdminAnimeJellyfinContext['asset_slots'] | null>(null)
  const [hasAdoptedJellyfinSelection, setHasAdoptedJellyfinSelection] = useState(false)
  const [isRefreshingAssets, setIsRefreshingAssets] = useState(false)
  const [activeAssetSearchKind, setActiveAssetSearchKind] = useState<SearchableAssetKind | null>(null)
  const [assetSearchQuery, setAssetSearchQuery] = useState('')
  const [assetSearchCandidates, setAssetSearchCandidates] = useState<
    Awaited<ReturnType<typeof searchAdminAnimeCreateAssetCandidates>>['data']
  >([])
  const [assetSearchSelectedIDs, setAssetSearchSelectedIDs] = useState<string[]>([])
  const [assetSearchErrorMessage, setAssetSearchErrorMessage] = useState<string | null>(null)
  const [assetSearchHasMore, setAssetSearchHasMore] = useState(false)
  const [assetSearchPage, setAssetSearchPage] = useState(1)
  const [isSearchingAssetCandidates, setIsSearchingAssetCandidates] = useState(false)
  const [isApplyingAssetCandidates, setIsApplyingAssetCandidates] = useState(false)
  const jellyfinIntake = useJellyfinIntake()

  const coverFileInputRef = useRef<HTMLInputElement | null>(null)
  const bannerFileInputRef = useRef<HTMLInputElement | null>(null)
  const logoFileInputRef = useRef<HTMLInputElement | null>(null)
  const backgroundFileInputRef = useRef<HTMLInputElement | null>(null)
  const backgroundVideoFileInputRef = useRef<HTMLInputElement | null>(null)

  const editor = useAnimeEditor('edit', {
    isDirty: patch.isDirty,
    canSubmit: patch.isDirty,
    isSubmitting: patch.isSubmitting,
    formID: 'anime-edit-form',
    submitButtonType: 'button',
    submitLabel: patch.isSubmitting ? 'Änderungen werden gespeichert...' : 'Änderungen speichern',
    dirtyStateTitle: 'Ungespeicherte Änderungen',
    dirtyStateMessage: 'Felder wurden angepasst. Speichere, um die Stammdaten zu übernehmen.',
    savedStateTitle: 'Alles gespeichert',
    savedStateMessage: 'Keine ausstehenden Stammdaten-Änderungen.',
    onSubmit: () => {
      void handleSave()
    },
  })

  const refreshAssetContext = useCallback(async () => {
    try {
      setIsRefreshingAssets(true)
      const response = await getAdminAnimeJellyfinContext(anime.id)
      setJellyfinContext(response.data)
      setPersistedAssets(response.data.persisted_assets || emptyPersistedAssets())
      setVisibleJellyfinAssetSlots((current) =>
        current ?? (response.data.asset_slots ? cloneJellyfinAssetSlots(response.data.asset_slots) : null),
      )
    } catch (error) {
      onError(formatAdminError(error, 'Asset-Kontext konnte nicht geladen werden.'))
    } finally {
      setIsRefreshingAssets(false)
    }
  }, [anime.id, onError])

  useEffect(() => {
    patch.resetFromAnime(anime)
    setPersistedAssets(hydratedState.persistedAssets)
    setJellyfinContext(null)
    setVisibleJellyfinAssetSlots(null)
  }, [anime, hydratedState.persistedAssets, patch.resetFromAnime])

  useEffect(() => {
    setVisibleJellyfinAssetSlots(
      jellyfinContext?.asset_slots ? cloneJellyfinAssetSlots(jellyfinContext.asset_slots) : null,
    )
  }, [jellyfinContext?.source, jellyfinContext?.jellyfin_series_id])

  useEffect(() => {
    void refreshAssetContext()
  }, [refreshAssetContext])

  useEffect(() => {
    if (jellyfinIntake.candidates.length === 1) {
      jellyfinIntake.reviewCandidate(jellyfinIntake.candidates[0].jellyfin_series_id)
    }
  }, [jellyfinIntake.candidates, jellyfinIntake.reviewCandidate])

  const reviewMissingFields: string[] = []
  if (!patch.values.title.trim()) reviewMissingFields.push('Titel')
  if (!persistedAssets.cover?.url && !patch.values.coverImage.trim()) {
    reviewMissingFields.push('Cover')
  }
  const adoptedJellyfinPreview = hasAdoptedJellyfinSelection ? jellyfinIntake.previewResult : null

  const handleSave = useCallback(async () => {
    onRequest?.(null)
    onResponse?.(null)

    const patchSaved = await patch.submit(anime.id)
    if (!patchSaved) {
      return
    }

    if (!adoptedJellyfinPreview) {
      return
    }

    try {
      await applyAdminAnimeMetadataFromJellyfin(
        anime.id,
        {
          jellyfin_series_id: adoptedJellyfinPreview.jellyfin_series_id,
          apply_cover: adoptedJellyfinPreview.asset_slots.cover.present,
          apply_banner: adoptedJellyfinPreview.asset_slots.banner.present,
          apply_logo: adoptedJellyfinPreview.asset_slots.logo.present,
          apply_backgrounds: adoptedJellyfinPreview.asset_slots.backgrounds.length > 0,
          apply_background_video: adoptedJellyfinPreview.asset_slots.background_video.present,
        },
      )
      jellyfinIntake.resetReview()
      setHasAdoptedJellyfinSelection(false)
      await refreshAssetContext()
    } catch (error) {
      onError(formatAdminError(error, 'Jellyfin-Assets konnten nicht gespeichert werden.'))
    }
  }, [adoptedJellyfinPreview, anime.id, jellyfinIntake, onError, onRequest, onResponse, patch, refreshAssetContext])

  function openAssetFileDialog(kind: AdminAnimeAssetKind) {
    const refs: Record<AdminAnimeAssetKind, React.RefObject<HTMLInputElement | null>> = {
      cover: coverFileInputRef,
      banner: bannerFileInputRef,
      logo: logoFileInputRef,
      background: backgroundFileInputRef,
      background_video: backgroundVideoFileInputRef,
    }
    refs[kind].current?.click()
  }

  function closeAssetSearch() {
    setActiveAssetSearchKind(null)
    setAssetSearchCandidates([])
    setAssetSearchSelectedIDs([])
    setAssetSearchErrorMessage(null)
    setAssetSearchHasMore(false)
    setAssetSearchPage(1)
  }

  async function handleAssetFileChange(kind: AdminAnimeAssetKind, event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]
    event.target.value = ''
    if (!file) return

    await patch.uploadAndLinkAsset(file, kind, anime.id)
    await refreshAssetContext()
  }

  async function handleRemoveSingularAsset(kind: 'cover' | 'banner' | 'logo' | 'background_video') {
    try {
      switch (kind) {
        case 'cover':
          await deleteAdminAnimeCoverAsset(anime.id)
          patch.setClearFlag('coverImage', true)
          patch.setField('coverImage', '')
          break
        case 'banner':
          await deleteAdminAnimeBannerAsset(anime.id)
          break
        case 'logo':
          await deleteAdminAnimeLogoAsset(anime.id)
          break
        case 'background_video':
          await deleteAdminAnimeBackgroundVideoAsset(anime.id)
          break
      }
      await refreshAssetContext()
    } catch (error) {
      onError(formatAdminError(error, 'Asset konnte nicht entfernt werden.'))
    }
  }

  async function handleRemoveBackground(backgroundID: number) {
    try {
      await deleteAdminAnimeBackgroundAsset(anime.id, backgroundID)
      await refreshAssetContext()
    } catch (error) {
      onError(formatAdminError(error, 'Background konnte nicht entfernt werden.'))
    }
  }

  async function handleAssetCandidateSearch() {
    if (!activeAssetSearchKind) {
      setAssetSearchErrorMessage('Bitte zuerst einen Asset-Slot wählen.')
      return
    }
    if (!assetSearchQuery.trim()) {
      setAssetSearchErrorMessage('Bitte zuerst einen Suchbegriff eingeben.')
      return
    }

    try {
      setIsSearchingAssetCandidates(true)
      setAssetSearchErrorMessage(null)
      const response = await searchAdminAnimeCreateAssetCandidates(
        {
          asset_kind: activeAssetSearchKind,
          query: assetSearchQuery.trim(),
          limit: activeAssetSearchKind === 'background' ? 12 : 8,
          page: 1,
        },
      )
      setAssetSearchPage(1)
      setAssetSearchCandidates(response.data)
      setAssetSearchSelectedIDs([])
      setAssetSearchHasMore(response.data.length >= (activeAssetSearchKind === 'background' ? 12 : 8))
    } catch (error) {
      onError(formatAdminError(error, 'Asset-Suche fehlgeschlagen.'))
    } finally {
      setIsSearchingAssetCandidates(false)
    }
  }

  async function handleLoadMoreAssets() {
    if (!activeAssetSearchKind || isSearchingAssetCandidates) return

    try {
      setIsSearchingAssetCandidates(true)
      const nextPage = assetSearchPage + 1
      const limit = activeAssetSearchKind === 'background' ? 12 : 8
      const response = await searchAdminAnimeCreateAssetCandidates(
        {
          asset_kind: activeAssetSearchKind,
          query: assetSearchQuery.trim(),
          limit,
          page: nextPage,
        },
      )
      setAssetSearchPage(nextPage)
      setAssetSearchCandidates((current) => [...current, ...response.data])
      setAssetSearchHasMore(response.data.length >= limit)
    } catch (error) {
      onError(formatAdminError(error, 'Weitere Assets konnten nicht geladen werden.'))
    } finally {
      setIsSearchingAssetCandidates(false)
    }
  }

  function toggleAssetCandidateSelection(candidateID: string) {
    if (activeAssetSearchKind === 'background') {
      setAssetSearchSelectedIDs((current) =>
        current.includes(candidateID)
          ? current.filter((id) => id !== candidateID)
          : [...current, candidateID],
      )
      return
    }
    setAssetSearchSelectedIDs((current) => (current[0] === candidateID ? [] : [candidateID]))
  }

  async function handleAssetCandidateAdoption() {
    if (!activeAssetSearchKind) return
    const selected = assetSearchCandidates.filter((candidate) =>
      assetSearchSelectedIDs.includes(candidate.id),
    )
    if (selected.length === 0) {
      setAssetSearchErrorMessage('Bitte zuerst mindestens ein Asset auswählen.')
      return
    }

    try {
      setIsApplyingAssetCandidates(true)
      for (const candidate of selected) {
        const staged = await stageRemoteCreateAssetCandidate(candidate)
        await patch.uploadAndLinkAsset(staged.file, activeAssetSearchKind, anime.id)
      }
      await refreshAssetContext()
      closeAssetSearch()
    } catch (error) {
      onError(formatAdminError(error, 'Ausgewählte Assets konnten nicht übernommen werden.'))
    } finally {
      setIsApplyingAssetCandidates(false)
    }
  }

  const effectiveSource = adoptedJellyfinPreview
    ? `jellyfin:${adoptedJellyfinPreview.jellyfin_series_id}`
    : jellyfinContext?.source || patch.values.source || hydratedState.values.source || ''
  const effectiveFolderPath = adoptedJellyfinPreview?.jellyfin_series_path?.trim()
    || jellyfinContext?.folder_name
    || jellyfinContext?.jellyfin_series_path
    || patch.values.folderName
    || hydratedState.values.folderName
    || ''
  const effectiveJellyfinSeriesID = adoptedJellyfinPreview?.jellyfin_series_id
    || jellyfinContext?.jellyfin_series_id
    || anime.jellyfin_series_id
    || ''
  const hasAniSearchSource = Boolean(
    anime.anisearch_id ||
      hasProviderSource('anisearch:', effectiveSource, anime.source_links),
  )
  const effectiveAniSearchID = resolveAniSearchID(effectiveSource, anime.source_links, anime.anisearch_id)
  const aniSearchURL = effectiveAniSearchID ? buildAniSearchAnimeURL(effectiveAniSearchID) : ''
  const hasJellyfinSource = Boolean(
    effectiveJellyfinSeriesID ||
      hasProviderSource('jellyfin:', effectiveSource, anime.source_links),
  )
  const effectiveSourceKind = adoptedJellyfinPreview ? 'Jellyfin' : formatSourceKindLabel(jellyfinContext?.source_kind)
  const isLinkedToJellyfin = Boolean(hasJellyfinSource || jellyfinContext?.linked)
  const coverSourceLabel =
    adoptedJellyfinPreview?.asset_slots.cover.present
      ? 'Jellyfin'
      : jellyfinContext?.cover.current_source === 'provider'
      ? 'Jellyfin'
      : jellyfinContext?.cover.current_source === 'manual'
        ? 'Manuell'
        : ''

  async function handleEditJellyfinSearch() {
    try {
      await jellyfinIntake.search()
      setHasAdoptedJellyfinSelection(false)
    } catch (error) {
      onError(formatAdminError(error, 'Jellyfin-Suche konnte nicht geladen werden.'))
    }
  }

  function handleEditJellyfinSelect(candidateID: string) {
    jellyfinIntake.reviewCandidate(candidateID)
    setHasAdoptedJellyfinSelection(false)
  }

  async function handleEditJellyfinAdopt(candidateID: string) {
    try {
      const preview = await jellyfinIntake.loadPreview(candidateID)
      if (!preview) {
        onError('Jellyfin-Vorschau konnte nicht geladen werden.')
        return
      }

      patch.setField('source', `jellyfin:${preview.jellyfin_series_id}`)
      patch.setField('folderName', preview.jellyfin_series_path?.trim() || '')
      setVisibleJellyfinAssetSlots(cloneJellyfinAssetSlots(preview.asset_slots))
      setHasAdoptedJellyfinSelection(true)
    } catch (error) {
      onError(formatAdminError(error, 'Jellyfin-Quelle konnte nicht übernommen werden.'))
    }
  }

  function handleDiscardEditJellyfinSelection() {
    jellyfinIntake.resetReview()
    setHasAdoptedJellyfinSelection(false)
    patch.setField('source', jellyfinContext?.source || hydratedState.values.source || '')
    patch.setField('folderName', jellyfinContext?.folder_name || hydratedState.values.folderName || '')
    setVisibleJellyfinAssetSlots(
      jellyfinContext?.asset_slots ? cloneJellyfinAssetSlots(jellyfinContext.asset_slots) : null,
    )
  }

  function handleRemoveVisibleJellyfinAsset(target: JellyfinDraftAssetTarget) {
    setVisibleJellyfinAssetSlots((current) => {
      if (!current) return current
      return removeJellyfinDraftAsset(hydratedState.values, current, target).assetSlots
    })
  }

  const sourceSection = (
    <div className={createStyles.providerGrid}>
      <section className={workspaceStyles.sectionCard}>
        <div className={workspaceStyles.sectionHeader}>
          <p className={workspaceStyles.sectionEyebrow}>Identität</p>
          <h2 className={workspaceStyles.sectionTitle}>Bestehender Anime</h2>
          <p className={workspaceStyles.sectionText}>
            Edit verwendet denselben Arbeitsraum wie Create, aber auf Basis eines bestehenden Datensatzes.
          </p>
        </div>

        <div className={styles.gridTwo}>
          <div className={styles.field}>
            <label htmlFor="edit-anime-id">Anime ID</label>
            <input id="edit-anime-id" value={String(anime.id)} readOnly />
          </div>
          <div className={styles.field}>
            <label htmlFor="edit-source">Quelle</label>
            <input id="edit-source" value={effectiveSource || 'Manuell'} readOnly />
          </div>
          <div className={styles.field}>
            <label htmlFor="edit-source-kind">Quelltyp</label>
            <input id="edit-source-kind" value={effectiveSourceKind} readOnly />
          </div>
          <div className={styles.field}>
            <label htmlFor="edit-anisearch-id">AniSearch ID</label>
            <div className={workspaceStyles.sourceLinkControl}>
              <Input
                id="edit-anisearch-id"
                value={effectiveAniSearchID}
                placeholder="Keine AniSearch-ID verknüpft"
                readOnly
              />
              <Button
                href={aniSearchURL || '#'}
                target="_blank"
                rel="noreferrer"
                variant="secondary"
                size="sm"
                disabled={!aniSearchURL}
              >
                AniSearch öffnen
              </Button>
            </div>
          </div>
          <div className={styles.field}>
            <label htmlFor="edit-link-status">Jellyfin-Link</label>
            <input id="edit-link-status" value={isLinkedToJellyfin ? 'Verknüpft' : 'Nicht verknüpft'} readOnly />
          </div>
          <div className={styles.field}>
            <label htmlFor="edit-jellyfin-item-id">Jellyfin Item ID</label>
            <input
              id="edit-jellyfin-item-id"
              value={effectiveJellyfinSeriesID}
              placeholder="Noch keine Jellyfin-Serie verknüpft"
              readOnly
            />
          </div>
          <div className={styles.field}>
            <label htmlFor="edit-cover-source">Cover-Quelle</label>
            <input
              id="edit-cover-source"
              value={coverSourceLabel}
              placeholder="Noch keine Kontextinfo geladen"
              readOnly
            />
          </div>
          <div className={`${styles.field} ${createStyles.folderPathField}`}>
            <label htmlFor="edit-folder-path">Ordnerpfad</label>
            <input
              id="edit-folder-path"
              className={createStyles.folderPathInput}
              value={effectiveFolderPath}
              placeholder="Noch kein Jellyfin-Ordner verknüpft"
              readOnly
            />
          </div>
        </div>
      </section>

      <section className={workspaceStyles.sectionCard}>
        <div className={workspaceStyles.sectionHeader}>
          <p className={workspaceStyles.sectionEyebrow}>Jellyfin</p>
          <h2 className={workspaceStyles.sectionTitle}>Jellyfin auswählen</h2>
          <p className={workspaceStyles.sectionText}>
            Verwende hier denselben einfachen Jellyfin-Flow wie beim Erstellen: suchen, passenden Ordner übernehmen, dann speichern.
          </p>
        </div>
        <CreateJellyfinCard
          query={jellyfinIntake.query}
          candidates={jellyfinIntake.candidates}
          currentAnimeID={anime.id}
          selectedCandidateID={jellyfinIntake.reviewState.selectedCandidate?.jellyfin_series_id}
          hasAdoptedAssets={hasAdoptedJellyfinSelection}
          isSearching={jellyfinIntake.isSearching}
          isLoadingPreview={jellyfinIntake.isLoadingPreview}
          canSearch={jellyfinIntake.query.trim().length >= 2}
          isSubmitting={patch.isSubmitting}
          showResults={jellyfinIntake.candidates.length > 0 || jellyfinIntake.reviewState.mode !== 'idle'}
          onQueryChange={jellyfinIntake.setQuery}
          onSearch={() => {
            void handleEditJellyfinSearch()
          }}
          onSelectCandidate={handleEditJellyfinSelect}
          onAdoptCandidate={(id) => {
            void handleEditJellyfinAdopt(id)
          }}
          onDiscard={handleDiscardEditJellyfinSelection}
        />
      </section>
    </div>
  )

  const assetsSection = (
    <>
      <AnimeEditAssetSection
        persistedAssets={persistedAssets}
        jellyfinAssetSlots={visibleJellyfinAssetSlots ?? jellyfinContext?.asset_slots ?? null}
        isBusy={patch.isUploadingCover || isRefreshingAssets || isApplyingAssetCandidates}
        onOpenFileDialog={openAssetFileDialog}
        onOpenAssetSearch={(kind) => setActiveAssetSearchKind(kind)}
        onRemoveJellyfinAsset={handleRemoveVisibleJellyfinAsset}
        onRemoveCover={() => void handleRemoveSingularAsset('cover')}
        onRemoveBanner={() => void handleRemoveSingularAsset('banner')}
        onRemoveLogo={() => void handleRemoveSingularAsset('logo')}
        onRemoveBackground={(backgroundID) => void handleRemoveBackground(backgroundID)}
        onRemoveBackgroundVideo={() => void handleRemoveSingularAsset('background_video')}
      />

      <input
        ref={coverFileInputRef}
        className={styles.fileInput}
        type="file"
        accept="image/*"
        onChange={(event) => void handleAssetFileChange('cover', event)}
      />
      <input
        ref={bannerFileInputRef}
        className={styles.fileInput}
        type="file"
        accept="image/*"
        onChange={(event) => void handleAssetFileChange('banner', event)}
      />
      <input
        ref={logoFileInputRef}
        className={styles.fileInput}
        type="file"
        accept="image/*"
        onChange={(event) => void handleAssetFileChange('logo', event)}
      />
      <input
        ref={backgroundFileInputRef}
        className={styles.fileInput}
        type="file"
        accept="image/*"
        onChange={(event) => void handleAssetFileChange('background', event)}
      />
      <input
        ref={backgroundVideoFileInputRef}
        className={styles.fileInput}
        type="file"
        accept="video/*"
        onChange={(event) => void handleAssetFileChange('background_video', event)}
      />
    </>
  )

  const detailsSection = (
    <div className={createStyles.detailsStack}>
      <section className={workspaceStyles.sectionCard}>
        <div className={workspaceStyles.sectionHeader}>
          <p className={workspaceStyles.sectionEyebrow}>Pflichtangaben</p>
          <h2 className={workspaceStyles.sectionTitle}>Basisdaten</h2>
          <p className={workspaceStyles.sectionText}>
            Dieselbe Kernstruktur wie im Create-Flow, jetzt für bestehende Anime.
          </p>
        </div>

        <div className={styles.gridTwo}>
          <div className={`${styles.field} ${workspaceStyles.titleField}`}>
            <label htmlFor="edit-title">Titel *</label>
            <div className={workspaceStyles.fieldMeta}>
              <input
                id="edit-title"
                className={`${workspaceStyles.titleFieldInput} ${
                  reviewMissingFields.includes('Titel') ? workspaceStyles.inputInvalid : ''
                }`}
                value={patch.values.title}
                onChange={(event) => patch.setField('title', event.target.value)}
              />
            </div>
          </div>

          <div className={styles.field}>
            <label htmlFor="edit-type">Typ *</label>
            <select id="edit-type" value={patch.values.type} onChange={(event) => patch.setField('type', event.target.value)}>
              {ANIME_TYPES.map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </div>

          <div className={styles.field}>
            <label htmlFor="edit-content-type">Inhaltstyp *</label>
            <select
              id="edit-content-type"
              value={patch.values.contentType}
              onChange={(event) => patch.setField('contentType', event.target.value)}
            >
              {CONTENT_TYPES.map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </div>

          <div className={styles.field}>
            <label htmlFor="edit-status">Status *</label>
            <select id="edit-status" value={patch.values.status} onChange={(event) => patch.setField('status', event.target.value)}>
              {ANIME_STATUSES.map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </div>

          <div className={styles.field}>
            <label htmlFor="edit-year">Jahr</label>
            <input id="edit-year" value={patch.values.year} onChange={(event) => patch.setField('year', event.target.value)} />
          </div>

          <div className={styles.field}>
            <label htmlFor="edit-max-episodes">Maximale Episoden</label>
            <input
              id="edit-max-episodes"
              value={patch.values.maxEpisodes}
              onChange={(event) => patch.setField('maxEpisodes', event.target.value)}
            />
          </div>

          <div className={styles.field}>
            <label htmlFor="edit-title-de">Titel DE</label>
            <input id="edit-title-de" value={patch.values.titleDE} onChange={(event) => patch.setField('titleDE', event.target.value)} />
          </div>

          <div className={styles.field}>
            <label htmlFor="edit-title-en">Titel EN</label>
            <input id="edit-title-en" value={patch.values.titleEN} onChange={(event) => patch.setField('titleEN', event.target.value)} />
          </div>
        </div>
      </section>

      <section className={workspaceStyles.sectionCard}>
        <div className={workspaceStyles.sectionHeader}>
          <p className={workspaceStyles.sectionEyebrow}>Metadaten</p>
          <h2 className={workspaceStyles.sectionTitle}>Genre, Tags und Beschreibung</h2>
          <p className={workspaceStyles.sectionText}>
            Diese Sektion folgt jetzt dem Create-Flow statt dem alten abgespeckten Edit-Formular.
          </p>
        </div>

        <div className={styles.grid}>
          <AnimeCreateGenreField
            draft={patch.values.genreDraft}
            selectedTokens={patch.values.genreTokens}
            suggestions={patch.genreSuggestions}
            suggestionsTotal={patch.genreSuggestionsTotal}
            loadedTokenCount={patch.genreTokens.length}
            isLoading={patch.isLoadingGenreTokens}
            error={patch.genreTokensError}
            isSubmitting={patch.isSubmitting}
            canLoadMore={patch.genreSuggestionLimit < 1000}
            canResetLimit={patch.genreSuggestionLimit > 40}
            onDraftChange={(value) => patch.setField('genreDraft', value)}
            onAddDraft={() => {
              patch.addGenreToken(patch.values.genreDraft)
              patch.setField('genreDraft', '')
            }}
            onRemoveToken={patch.removeGenreToken}
            onAddSuggestion={patch.addGenreToken}
            onIncreaseLimit={() => patch.setGenreSuggestionLimit(patch.genreSuggestionLimit + 40)}
            onResetLimit={() => patch.setGenreSuggestionLimit(40)}
          />

          <AnimeCreateTagField
            draft={patch.values.tagDraft}
            selectedTokens={patch.values.tagTokens}
            suggestions={patch.tagSuggestions}
            suggestionsTotal={patch.tagSuggestionsTotal}
            loadedTokenCount={patch.tagTokens.length}
            isLoading={patch.isLoadingTagTokens}
            error={patch.tagTokensError}
            isSubmitting={patch.isSubmitting}
            canLoadMore={patch.tagSuggestionLimit < 1000}
            canResetLimit={patch.tagSuggestionLimit > 40}
            onDraftChange={(value) => patch.setField('tagDraft', value)}
            onAddDraft={() => {
              patch.addTagToken(patch.values.tagDraft)
              patch.setField('tagDraft', '')
            }}
            onRemoveToken={patch.removeTagToken}
            onAddSuggestion={patch.addTagToken}
            onIncreaseLimit={() => patch.setTagSuggestionLimit(patch.tagSuggestionLimit + 40)}
            onResetLimit={() => patch.setTagSuggestionLimit(40)}
          />

          <FormField
            label="Beschreibung"
            htmlFor="edit-description"
            hint="Kurz, eindeutig und ohne Prozess-Text."
          >
            <Textarea
              id="edit-description"
              className={workspaceStyles.descriptionArea}
              value={patch.values.description}
              onChange={(event) => patch.setField('description', event.target.value)}
            />
          </FormField>
        </div>
      </section>
    </div>
  )

  const reviewSection = (
    <CreateReviewSection
      missingFields={reviewMissingFields}
      hasTitle={patch.values.title.trim().length > 0}
      hasCover={Boolean(persistedAssets.cover?.url || patch.values.coverImage.trim())}
      hasAniSearch={hasAniSearchSource}
      hasJellyfin={hasJellyfinSource}
      assetCount={
        (persistedAssets.backgrounds?.length ?? 0) +
        (persistedAssets.banner ? 1 : 0) +
        (persistedAssets.logo ? 1 : 0) +
        (persistedAssets.background_video ? 1 : 0)
      }
      isSubmitting={patch.isSubmitting}
      successMessage={null}
      errorMessage={null}
      submitLabel="Änderungen speichern"
      submittingLabel="Änderungen werden gespeichert…"
      note="Prüfe die Änderungen noch einmal, bevor du den bestehenden Anime aktualisierst."
      hideSubmitButton
      onSubmit={() => {
        void handleSave()
      }}
    />
  )

  return (
    <AnimeEditorShell editor={editor}>
      <form id="anime-edit-form" onSubmit={(event: FormEvent) => event.preventDefault()}>
        <SharedAnimeEditorWorkspace
          mode="edit"
          headerTitle="Anime bearbeiten"
          headerIntro="Create-Flow als Basis, aber mit direktem Bearbeiten bestehender Daten und Assets."
          sourceContent={sourceSection}
          assetsContent={assetsSection}
          detailsContent={detailsSection}
          reviewContent={reviewSection}
        />
      </form>

      <CreateAssetSearchDialog
        activeKind={activeAssetSearchKind}
        query={assetSearchQuery}
        candidates={assetSearchCandidates}
        selectedCandidateIDs={assetSearchSelectedIDs}
        errorMessage={assetSearchErrorMessage}
        hasMore={assetSearchHasMore}
        isOpen={activeAssetSearchKind !== null}
        isSearching={isSearchingAssetCandidates}
        isAdopting={isApplyingAssetCandidates}
        onClose={closeAssetSearch}
        onQueryChange={setAssetSearchQuery}
        onSearch={() => {
          void handleAssetCandidateSearch()
        }}
        onLoadMore={() => {
          void handleLoadMoreAssets()
        }}
        onToggleCandidate={toggleAssetCandidateSelection}
        onAdoptSelection={() => {
          void handleAssetCandidateAdoption()
        }}
      />
    </AnimeEditorShell>
  )
}

'use client'

import { useRef, useState } from 'react'

import {
  addAdminAnimeBackgroundAsset,
  assignAdminAnimeCoverAsset,
  assignAdminAnimeBackgroundVideoAsset,
  assignAdminAnimeBannerAsset,
  assignAdminAnimeLogoAsset,
  deleteAdminAnimeCoverAsset,
  deleteAdminAnimeBackgroundAsset,
  deleteAdminAnimeBackgroundVideoAsset,
  deleteAdminAnimeBannerAsset,
  deleteAdminAnimeLogoAsset,
  resolveApiUrl,
  uploadAdminAnimeMedia,
} from '@/lib/api'
import type { AdminAnimeJellyfinContext } from '@/types/admin'
import { MediaOwnershipContext, MediaOwnershipContextValue } from '@/components/admin/media/MediaOwnershipContext'

import styles from '../../AdminStudio.module.css'
import workspaceStyles from './AnimeEditWorkspace.module.css'
import { EDIT_UPLOAD_TARGETS, EditUploadTarget, getEditUploadStatusLabel } from './animeJellyfinAssetUpload'
import type { AssetCardDescriptor } from './AnimeJellyfinMetadataSection.helpers'
import { summarizeAssetSlotDecision } from './AnimeJellyfinMetadataSection.helpers'

interface AnimeJellyfinAssetUploadControlsProps {
  animeID: number
  animeTitle?: string
  disabled?: boolean
  assetCards: AssetCardDescriptor[]
  coverCurrentImage?: string
  coverCurrentSource: AdminAnimeJellyfinContext['cover']['current_source']
  persistedAssets: AdminAnimeJellyfinContext['persisted_assets']
  onSuccess: (message: string) => void
  onError: (message: string) => void
  onAfterMutation: () => Promise<void>
}

function formatOwnershipLabel(value: 'manual' | 'provider'): string {
  return value === 'manual' ? 'Manuell' : 'Provider'
}

export function AnimeJellyfinAssetUploadControls({
  animeID,
  animeTitle,
  disabled = false,
  assetCards,
  coverCurrentImage,
  coverCurrentSource,
  persistedAssets,
  onSuccess,
  onError,
  onAfterMutation,
}: AnimeJellyfinAssetUploadControlsProps) {
  const [isMutatingAssets, setIsMutatingAssets] = useState(false)
  const [uploadTarget, setUploadTarget] = useState<EditUploadTarget | null>(null)
  const [uploadProgress, setUploadProgress] = useState(0)
  const [isUploadingCover, setIsUploadingCover] = useState(false)
  // D-07: MediaOwnershipContext-Zustand (Surface 2, Branding-Slot)
  const [ownerCtx, setOwnerCtx] = useState<MediaOwnershipContextValue | null>(null)

  const coverInputRef = useRef<HTMLInputElement | null>(null)
  const bannerInputRef = useRef<HTMLInputElement | null>(null)
  const logoInputRef = useRef<HTMLInputElement | null>(null)
  const backgroundInputRef = useRef<HTMLInputElement | null>(null)
  const backgroundVideoInputRef = useRef<HTMLInputElement | null>(null)

  const isBusy = disabled || isMutatingAssets || isUploadingCover
  const mutationStatusLabel = getEditUploadStatusLabel(uploadTarget, false)

  async function handleCoverUpload(file: File) {
    // D-06-Guard: kein Upload ohne aufgelösten Owner-Kontext
    if (!ownerCtx?.ownerResolved) {
      onError('Upload nicht möglich: Kein gültiger Owner-Kontext.')
      return
    }
    setIsUploadingCover(true)

    try {
      const upload = await uploadAdminAnimeMedia({
        animeID,
        assetType: 'poster',
        file,
        visibilityCode: ownerCtx.visibilityCode,
        reviewStatusCode: ownerCtx.reviewStatusCode,
      })

      await assignAdminAnimeCoverAsset(animeID, upload.id)
      await onAfterMutation()
      onSuccess('Cover wurde hochgeladen und als aktives Asset gesetzt.')
    } catch (error) {
      if (error instanceof Error && error.message.trim()) {
        onError(error.message)
      } else {
        onError('Cover Upload fehlgeschlagen.')
      }
    } finally {
      setIsUploadingCover(false)
      if (coverInputRef.current) coverInputRef.current.value = ''
    }
  }

  async function handleRemoveCover() {
    setIsUploadingCover(true)
    try {
      await deleteAdminAnimeCoverAsset(animeID)
      await onAfterMutation()
      onSuccess('Cover wurde entfernt.')
    } catch (error) {
      if (error instanceof Error && error.message.trim()) {
        onError(error.message)
      } else {
        onError('Cover konnte nicht entfernt werden.')
      }
    } finally {
      setIsUploadingCover(false)
    }
  }

  async function handleManualUpload(target: EditUploadTarget, file: File) {
    // D-06-Guard: kein Upload ohne aufgelösten Owner-Kontext
    if (!ownerCtx?.ownerResolved) {
      onError('Upload nicht möglich: Kein gültiger Owner-Kontext.')
      return
    }
    setIsMutatingAssets(true)
    setUploadTarget(target)
    setUploadProgress(0)

    try {
      const upload = await uploadAdminAnimeMedia({
        animeID,
        assetType: EDIT_UPLOAD_TARGETS[target].assetType,
        file,
        onProgress: setUploadProgress,
        visibilityCode: ownerCtx.visibilityCode,
        reviewStatusCode: ownerCtx.reviewStatusCode,
      })

      if (target === 'banner') {
        await assignAdminAnimeBannerAsset(animeID, upload.id)
      } else if (target === 'logo') {
        await assignAdminAnimeLogoAsset(animeID, upload.id)
      } else if (target === 'background_video') {
        await assignAdminAnimeBackgroundVideoAsset(animeID, upload.id)
      } else {
        await addAdminAnimeBackgroundAsset(animeID, upload.id)
      }

      await onAfterMutation()
      onSuccess(EDIT_UPLOAD_TARGETS[target].successMessage)
    } catch (error) {
      if (error instanceof Error && error.message.trim()) {
        onError(error.message)
      } else {
        onError(EDIT_UPLOAD_TARGETS[target].errorMessage)
      }
    } finally {
      setIsMutatingAssets(false)
      setUploadTarget(null)
      setUploadProgress(0)
      if (bannerInputRef.current) bannerInputRef.current.value = ''
      if (logoInputRef.current) logoInputRef.current.value = ''
      if (backgroundInputRef.current) backgroundInputRef.current.value = ''
      if (backgroundVideoInputRef.current) backgroundVideoInputRef.current.value = ''
    }
  }

  async function handleRemoveSingularAsset(target: 'banner' | 'logo' | 'background_video') {
    setIsMutatingAssets(true)
    try {
      if (target === 'banner') {
        await deleteAdminAnimeBannerAsset(animeID)
      } else if (target === 'logo') {
        await deleteAdminAnimeLogoAsset(animeID)
      } else {
        await deleteAdminAnimeBackgroundVideoAsset(animeID)
      }

      await onAfterMutation()
      onSuccess(`${EDIT_UPLOAD_TARGETS[target].removeLabel} abgeschlossen.`)
    } catch (error) {
      if (error instanceof Error && error.message.trim()) {
        onError(error.message)
      } else {
        onError(`${EDIT_UPLOAD_TARGETS[target].removeLabel} fehlgeschlagen.`)
      }
    } finally {
      setIsMutatingAssets(false)
    }
  }

  async function handleRemoveBackground(backgroundID: number) {
    setIsMutatingAssets(true)
    try {
      await deleteAdminAnimeBackgroundAsset(animeID, backgroundID)
      await onAfterMutation()
      onSuccess('Background wurde entfernt.')
    } catch (error) {
      if (error instanceof Error && error.message.trim()) {
        onError(error.message)
      } else {
        onError('Background konnte nicht entfernt werden.')
      }
    } finally {
      setIsMutatingAssets(false)
    }
  }

  function triggerUpload(target: EditUploadTarget) {
    if (target === 'banner') {
      bannerInputRef.current?.click()
      return
    }
    if (target === 'logo') {
      logoInputRef.current?.click()
      return
    }
    if (target === 'background_video') {
      backgroundVideoInputRef.current?.click()
      return
    }
    backgroundInputRef.current?.click()
  }

  function triggerCoverUpload() {
    coverInputRef.current?.click()
  }

  function renderPersistedStatus(kind: AssetCardDescriptor['kind']) {
    if (kind === 'cover') {
      return null
    }
    if (kind === 'backgrounds') {
      return (
        <span className={`${styles.badge} ${styles.badgeMuted}`}>
          {persistedAssets.backgrounds.length} aktiv
        </span>
      )
    }

    const asset =
      kind === 'banner'
        ? persistedAssets.banner
        : kind === 'logo'
          ? persistedAssets.logo
          : persistedAssets.background_video

    if (!asset) {
      return (
        <span className={`${styles.badge} ${styles.badgeMuted}`}>
          Noch nicht persistiert
        </span>
      )
    }

    return (
      <span className={`${styles.badge} ${asset.ownership === 'manual' ? styles.badgeWarning : styles.badgeSuccess}`}>
        Aktiv: {formatOwnershipLabel(asset.ownership)}
      </span>
    )
  }

  function renderStateFrame(
    imageUrl: string | undefined,
    alt: string,
    options?: { isVideo?: boolean; poster?: boolean },
  ) {
    const isVideo = options?.isVideo ?? false
    const poster = options?.poster ?? false

    if (!imageUrl) {
      return (
        <div className={`${workspaceStyles.assetStateEmpty} ${poster ? workspaceStyles.assetStateEmptyPoster : ''}`}>
          Noch kein Asset verfügbar.
        </div>
      )
    }

    if (isVideo) {
      return (
        <div className={workspaceStyles.assetStateEmpty}>
          Background-Video ist gesetzt.
        </div>
      )
    }

    return (
      <div
        className={`${workspaceStyles.assetPreviewFrame} ${
          poster ? workspaceStyles.assetPreviewFramePoster : workspaceStyles.assetPreviewFrameWide
        }`}
      >
        <img className={workspaceStyles.assetPreviewImage} src={imageUrl} alt={alt} />
      </div>
    )
  }

  function renderPersistedBody(kind: AssetCardDescriptor['kind']) {
    if (kind === 'cover') {
      const hasActiveCover = Boolean(coverCurrentImage?.trim())

      return (
        <>
          <div className={workspaceStyles.assetComparisonGrid}>
            <div className={workspaceStyles.assetStatePanel}>
              <span className={workspaceStyles.assetStateLabel}>Provider-Vorschau</span>
              {renderStateFrame(
                assetCards.find((item) => item.kind === 'cover')?.previewURL,
                'Provider-Cover',
                { poster: true },
              )}
              <div className={workspaceStyles.assetLinkRow}>
                {assetCards.find((item) => item.kind === 'cover')?.previewURL ? (
                  <a
                    className={`${styles.button} ${styles.buttonGhost}`}
                    href={assetCards.find((item) => item.kind === 'cover')?.previewURL}
                    target="_blank"
                    rel="noreferrer"
                  >
                    Provider-Asset öffnen
                  </a>
                ) : null}
              </div>
            </div>
            <div className={workspaceStyles.assetStatePanel}>
              <span className={workspaceStyles.assetStateLabel}>Aktiv gespeichert</span>
              {renderStateFrame(coverCurrentImage ? resolveApiUrl(coverCurrentImage) : undefined, 'Aktives Cover', {
                poster: true,
              })}
              <p className={workspaceStyles.helperText}>
                {coverCurrentSource === 'provider'
                  ? 'Aktiv: Provider-Cover'
                  : coverCurrentSource === 'manual'
                    ? 'Aktiv: manuelles Cover'
                    : 'Aktiv: kein Cover'}
              </p>
              {isUploadingCover ? (
                <p className={workspaceStyles.statusNote} aria-live="polite">
                  Cover wird verarbeitet...
                </p>
              ) : null}
              <div className={workspaceStyles.assetActionStack}>
                <div className={workspaceStyles.assetActionRowCompact}>
                  <button
                    type="button"
                    className={`${styles.button} ${styles.buttonPrimary}`}
                    disabled={isBusy}
                    onClick={triggerCoverUpload}
                  >
                    {isUploadingCover ? 'Upload läuft...' : 'Cover hochladen'}
                  </button>
                  <button
                    type="button"
                    className={`${styles.button} ${styles.buttonDanger}`}
                    disabled={!hasActiveCover || isBusy}
                    onClick={() => void handleRemoveCover()}
                  >
                    Cover entfernen
                  </button>
                </div>
                {hasActiveCover ? (
                  <div className={workspaceStyles.assetLinkRow}>
                    <a
                      className={`${styles.button} ${styles.buttonGhost}`}
                      href={resolveApiUrl(coverCurrentImage)}
                      target="_blank"
                      rel="noreferrer"
                    >
                      Aktives Cover öffnen
                    </a>
                  </div>
                ) : null}
              </div>
            </div>
          </div>
        </>
      )
    }
    if (kind === 'backgrounds') {
      const backgroundCard = assetCards.find((item) => item.kind === 'backgrounds')
      const providerBackgrounds = backgroundCard?.previewURLs || []

      return (
        <>
          <div className={workspaceStyles.assetComparisonGrid}>
            <div className={workspaceStyles.assetStatePanel}>
              <span className={workspaceStyles.assetStateLabel}>Provider-Vorschau</span>
              {providerBackgrounds.length > 0 ? (
                <div className={workspaceStyles.assetGallery}>
                  {providerBackgrounds.map((url, index) => (
                    <div key={url} className={workspaceStyles.assetGalleryItem}>
                      <div className={workspaceStyles.assetGalleryThumb}>
                        <img src={url} alt={`Provider-Background ${index + 1}`} />
                      </div>
                      <span className={workspaceStyles.assetGalleryMeta}>Provider #{index + 1}</span>
                    </div>
                  ))}
                </div>
              ) : (
                <div className={workspaceStyles.assetStateEmpty}>
                  Keine Provider-Backgrounds verfügbar.
                </div>
              )}
              <p className={workspaceStyles.helperText}>
                Provider-Bilder sind nur Vorschläge. Aktiv gespeichert werden nur die Backgrounds, die du explizit hinzufügst.
              </p>
            </div>
            <div className={workspaceStyles.assetStatePanel}>
              <span className={workspaceStyles.assetStateLabel}>Aktiv gespeichert</span>
              {persistedAssets.backgrounds.length > 0 ? (
                <div className={workspaceStyles.assetGallery}>
                  {persistedAssets.backgrounds.map((item) => (
                    <div key={item.id} className={workspaceStyles.assetGalleryItem}>
                      <div className={workspaceStyles.assetGalleryThumb}>
                        <img src={resolveApiUrl(item.url)} alt={`Aktiver Background ${item.sort_order}`} />
                      </div>
                      <span className={workspaceStyles.assetGalleryMeta}>
                        #{item.sort_order} · {formatOwnershipLabel(item.ownership)}
                      </span>
                      <div className={styles.actionsRow}>
                        <a className={`${styles.button} ${styles.buttonGhost}`} href={resolveApiUrl(item.url)} target="_blank" rel="noreferrer">
                          Öffnen
                        </a>
                        <button
                          type="button"
                          className={`${styles.button} ${styles.buttonDanger}`}
                          disabled={isBusy}
                          onClick={() => void handleRemoveBackground(item.id)}
                        >
                          Entfernen
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className={workspaceStyles.assetStateEmpty}>
                  Noch kein manueller Background gespeichert.
                </div>
              )}
            </div>
          </div>
          <div className={styles.actionsRow}>
            <button
              type="button"
              className={`${styles.button} ${styles.buttonSecondary}`}
              disabled={isBusy}
              onClick={() => triggerUpload('background')}
            >
              {uploadTarget === 'background' ? `Background lädt... ${uploadProgress}%` : EDIT_UPLOAD_TARGETS.background.buttonLabel}
            </button>
          </div>
          {uploadTarget === 'background' ? (
            <p className={workspaceStyles.statusNote} aria-live="polite">
              {mutationStatusLabel}
            </p>
          ) : null}
        </>
      )
    }

    const target = kind as Exclude<EditUploadTarget, 'background'>
    const asset =
      kind === 'banner'
        ? persistedAssets.banner
        : kind === 'logo'
          ? persistedAssets.logo
          : persistedAssets.background_video

    return (
      <>
        <div className={workspaceStyles.assetComparisonGrid}>
          <div className={workspaceStyles.assetStatePanel}>
            <span className={workspaceStyles.assetStateLabel}>Provider-Vorschau</span>
            {renderStateFrame(
              assetCards.find((item) => item.kind === kind)?.previewURL,
              `Provider-${kind}`,
              { isVideo: kind === 'background_video' },
            )}
            <p className={workspaceStyles.helperText}>
              Provider-Vorschau, nicht automatisch aktiv.
            </p>
          </div>
          <div className={workspaceStyles.assetStatePanel}>
            <span className={workspaceStyles.assetStateLabel}>Aktiv gespeichert</span>
            {renderStateFrame(
              asset?.url ? resolveApiUrl(asset.url) : undefined,
              `Aktives ${kind}`,
              { isVideo: kind === 'background_video' },
            )}
            <p className={workspaceStyles.helperText}>
              {asset
                ? `Aktiv: ${formatOwnershipLabel(asset.ownership)}`
                : 'Aktiv: noch nicht gespeichert'}
            </p>
          </div>
        </div>
        {uploadTarget === target ? (
          <p className={workspaceStyles.statusNote} aria-live="polite">
            {target === 'banner'
              ? `Banner lädt... ${uploadProgress}%`
              : target === 'logo'
                ? `Logo lädt... ${uploadProgress}%`
                : `Background-Video lädt... ${uploadProgress}%`}
          </p>
        ) : null}
        <div className={styles.actionsRow}>
          <button
            type="button"
            className={`${styles.button} ${styles.buttonSecondary}`}
            disabled={isBusy}
            onClick={() => triggerUpload(target)}
          >
            {uploadTarget === target
              ? target === 'banner'
                ? `Banner lädt... ${uploadProgress}%`
                : target === 'logo'
                  ? `Logo lädt... ${uploadProgress}%`
                  : `Background-Video lädt... ${uploadProgress}%`
              : EDIT_UPLOAD_TARGETS[target].buttonLabel}
          </button>
          <button
            type="button"
            className={`${styles.button} ${styles.buttonDanger}`}
            disabled={!asset || isBusy}
            onClick={() => void handleRemoveSingularAsset(target)}
          >
            {EDIT_UPLOAD_TARGETS[target].removeLabel}
          </button>
          {assetCards.find((item) => item.kind === kind)?.previewURL ? (
            <a
              className={`${styles.button} ${styles.buttonGhost}`}
              href={assetCards.find((item) => item.kind === kind)?.previewURL}
              target="_blank"
              rel="noreferrer"
            >
              Provider öffnen
            </a>
          ) : null}
          {asset?.url ? (
            <a className={`${styles.button} ${styles.buttonGhost}`} href={resolveApiUrl(asset.url)} target="_blank" rel="noreferrer">
              Aktives Asset öffnen
            </a>
          ) : null}
        </div>
      </>
    )
  }

  return (
    <>
      {/* D-07: MediaOwnershipContext — Surface 2, Anime-Assets (Branding-Slot, D-09) */}
      <MediaOwnershipContext
        ownerType="anime"
        ownerID={animeID}
        ownerLabel={animeTitle ? `Anime «${animeTitle}»` : `Anime ${animeID}`}
        categoryMode="slot"
        categoryValue="anime-asset"
        statusPolicy="immediate"
        disabled={isBusy}
        onContextChange={setOwnerCtx}
      />
    <input
        ref={coverInputRef}
        type="file"
        accept=".jpg,.jpeg,.png,.webp,.gif,image/*"
        hidden
        onChange={(event) => {
          const file = event.target.files?.[0]
          if (file) {
            void handleCoverUpload(file)
          }
        }}
      />
      <input
        ref={bannerInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp,image/gif"
        hidden
        onChange={(event) => {
          const file = event.target.files?.[0]
          if (file) {
            void handleManualUpload('banner', file)
          }
        }}
      />
      <input
        ref={logoInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp,image/gif"
        hidden
        onChange={(event) => {
          const file = event.target.files?.[0]
          if (file) {
            void handleManualUpload('logo', file)
          }
        }}
      />
      <input
        ref={backgroundInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp,image/gif"
        hidden
        onChange={(event) => {
          const file = event.target.files?.[0]
          if (file) {
            void handleManualUpload('background', file)
          }
        }}
      />
      <input
        ref={backgroundVideoInputRef}
        type="file"
        accept="video/mp4,video/webm,video/ogg"
        hidden
        onChange={(event) => {
          const file = event.target.files?.[0]
          if (file) {
            void handleManualUpload('background_video', file)
          }
        }}
      />

      <div className={workspaceStyles.sectionGridTwo}>
        {assetCards.map((asset) => {
          const decision = summarizeAssetSlotDecision(asset.kind, {
            hasIncoming: asset.hasIncoming,
            currentSource: coverCurrentSource,
          })
          const isCover = asset.kind === 'cover'
          const isBackgroundVideo = asset.kind === 'background_video'

          return (
            <div key={asset.key} className={workspaceStyles.assetCard}>
              <div className={workspaceStyles.assetCardHeader}>
                <span>{asset.title}</span>
                {renderPersistedStatus(asset.kind)}
              </div>
              <div className={styles.badgeRow}>
                <span className={`${styles.badge} ${asset.hasIncoming ? styles.badgeSuccess : styles.badgeMuted}`}>
                  {asset.hasIncoming ? 'Provider-Slot vorhanden' : 'Kein Provider-Slot'}
                </span>
                {!isCover ? (
                  <span className={`${styles.badge} ${styles.badgeWarning}`}>
                    Manuell oder explizit steuerbar
                  </span>
                ) : null}
                {asset.countLabel ? <span className={`${styles.badge} ${styles.badgeMuted}`}>{asset.countLabel}</span> : null}
              </div>
              <p className={workspaceStyles.helperText}>{decision}</p>
              {!isCover ? renderPersistedBody(asset.kind) : null}
              {isCover ? renderPersistedBody(asset.kind) : null}
            </div>
          )
        })}
      </div>
    </>
  )
}

'use client'

import { useEffect, useMemo, useRef, useState } from 'react'

import {
  applyAdminAnimeMetadataFromJellyfin,
  getAdminAnimeJellyfinContext,
  previewAdminAnimeMetadataFromJellyfin,
} from '@/lib/api'
import type { AdminAnimeJellyfinContext, AdminAnimeJellyfinMetadataPreviewResult } from '@/types/admin'

import styles from '../../AdminStudio.module.css'
import workspaceStyles from './AnimeEditWorkspace.module.css'
import { AnimeJellyfinAssetUploadControls } from './AnimeJellyfinAssetUploadControls'
import {
  buildAssetCards,
  formatCoverSource,
  formatSourceKindLabel,
  summarizeAssetSlots,
} from './AnimeJellyfinMetadataSection.helpers'

export { formatCoverSource, summarizeAssetSlotDecision, summarizeAssetSlots } from './AnimeJellyfinMetadataSection.helpers'

interface AnimeJellyfinMetadataSectionProps {
  animeID: number
  onError: (message: string) => void
  onSuccess: (message: string) => void
  onAfterApply: () => Promise<void>
  onContextLoaded?: (context: AdminAnimeJellyfinContext | null) => void
}

export function AnimeJellyfinMetadataSection({
  animeID,
  onError,
  onSuccess,
  onAfterApply,
  onContextLoaded,
}: AnimeJellyfinMetadataSectionProps) {
  const [context, setContext] = useState<AdminAnimeJellyfinContext | null>(null)
  const [preview, setPreview] = useState<AdminAnimeJellyfinMetadataPreviewResult | null>(null)
  const [isLoadingContext, setIsLoadingContext] = useState(true)
  const [isPreviewing, setIsPreviewing] = useState(false)
  const [isApplying, setIsApplying] = useState(false)
  const [applyCover, setApplyCover] = useState(false)
  const [applyBanner, setApplyBanner] = useState(false)
  const [applyBackgrounds, setApplyBackgrounds] = useState(false)

  const onErrorRef = useRef(onError)
  const onContextLoadedRef = useRef(onContextLoaded)

  useEffect(() => {
    onErrorRef.current = onError
  }, [onError])

  useEffect(() => {
    onContextLoadedRef.current = onContextLoaded
  }, [onContextLoaded])

  async function refreshContext(options?: { resetPreview?: boolean }) {
    const resetPreview = options?.resetPreview ?? false
    const response = await getAdminAnimeJellyfinContext(animeID)
    setContext(response.data)
    onContextLoadedRef.current?.(response.data)
    if (resetPreview) {
      setPreview(null)
      setApplyCover(false)
      setApplyBanner(false)
      setApplyBackgrounds(false)
    }
    return response.data
  }

  useEffect(() => {
    let cancelled = false

    async function loadContext() {
      setIsLoadingContext(true)
      setPreview(null)
      setApplyCover(false)
      setApplyBanner(false)
      setApplyBackgrounds(false)

      try {
        const response = await getAdminAnimeJellyfinContext(animeID)
        if (cancelled) return
        setContext(response.data)
        onContextLoadedRef.current?.(response.data)
      } catch (error) {
        if (cancelled) return
        setContext(null)
        onContextLoadedRef.current?.(null)
        onErrorRef.current(error instanceof Error ? error.message : 'Jellyfin-Kontext konnte nicht geladen werden.')
      } finally {
        if (!cancelled) {
          setIsLoadingContext(false)
        }
      }
    }

    void loadContext()

    return () => {
      cancelled = true
    }
  }, [animeID])

  const hasApplicableDiff = useMemo(() => preview?.diff.some((item) => item.apply) ?? false, [preview])
  const canApply = Boolean(preview) && (hasApplicableDiff || applyCover || applyBanner || applyBackgrounds)
  const assetCards = useMemo(() => buildAssetCards(context, preview), [context, preview])
  const isBusy = isPreviewing || isApplying

  async function handlePreview() {
    setIsPreviewing(true)
    setApplyCover(false)
    setApplyBanner(false)
    setApplyBackgrounds(false)

    try {
      const response = await previewAdminAnimeMetadataFromJellyfin(animeID, {})
      setPreview(response.data)
      onSuccess('Jellyfin-Metadatenvorschau geladen.')
    } catch (error) {
      onError(error instanceof Error ? error.message : 'Jellyfin-Metadatenvorschau fehlgeschlagen.')
    } finally {
      setIsPreviewing(false)
    }
  }

  async function handleApply() {
    if (!preview) return

    setIsApplying(true)
    try {
      await applyAdminAnimeMetadataFromJellyfin(
        animeID,
        {
          jellyfin_series_id: preview.jellyfin_series_id,
          apply_cover: applyCover,
          apply_banner: applyBanner,
          apply_backgrounds: applyBackgrounds,
        },
      )
      await onAfterApply()
      await refreshContext({ resetPreview: true })
      onSuccess('Jellyfin-Metadaten wurden übernommen.')
    } catch (error) {
      onError(error instanceof Error ? error.message : 'Jellyfin-Metadaten konnten nicht übernommen werden.')
    } finally {
      setIsApplying(false)
    }
  }

  return (
    <section className={`${styles.card} ${workspaceStyles.sectionCard}`}>
      <div className={styles.sectionHeader}>
        <div>
          <h2 className={styles.sectionTitle}>Jellyfin Provenance</h2>
          <p className={styles.sectionMeta}>Linkage, sichere Metadaten-Preview und explizite Übernahme für bestehende Anime.</p>
        </div>
      </div>

      {isLoadingContext ? <p className={workspaceStyles.helperText}>Jellyfin-Kontext wird geladen...</p> : null}

      {context ? (
        <>
          <div className={workspaceStyles.sectionGridTwo}>
            <div className={workspaceStyles.field}>
              <span>Quelle</span>
              <div className={styles.badgeRow}>
                <span className={`${styles.badge} ${context.linked ? styles.badgePrimary : styles.badgeMuted}`}>
                  {context.linked ? 'Mit Jellyfin verknüpft' : 'Manuell gepflegt'}
                </span>
                <span className={`${styles.badge} ${styles.badgeMuted}`}>{formatSourceKindLabel(context.source_kind)}</span>
                <span className={`${styles.badge} ${styles.badgeMuted}`}>{formatCoverSource(context.cover.current_source)}</span>
              </div>
            </div>
            <div className={workspaceStyles.field}>
              <span>Kontext</span>
              <p className={workspaceStyles.helperText}>
                {context.source ? `Quelle: ${context.source}` : 'Keine direkte Quelle gesetzt.'}
              </p>
            </div>
            <div className={workspaceStyles.field}>
              <span>Jellyfin-Serie</span>
              <input className={styles.input} value={context.jellyfin_series_name || context.jellyfin_series_id || ''} readOnly disabled />
            </div>
            <div className={workspaceStyles.field}>
              <span>Ordner / Pfad</span>
              <input className={styles.input} value={context.folder_name || context.jellyfin_series_path || ''} readOnly disabled />
            </div>
            <div className={workspaceStyles.field}>
              <span>Provider-Assets</span>
              <p className={workspaceStyles.helperText}>{summarizeAssetSlots(context.asset_slots)}</p>
            </div>
          </div>

          <div className={styles.actionsRow}>
            <button
              type="button"
              className={`${styles.button} ${styles.buttonSecondary}`}
              disabled={!context.linked || isBusy}
              onClick={() => void handlePreview()}
            >
              {isPreviewing ? 'Preview läuft...' : 'Metadaten preview laden'}
            </button>
          </div>

          {!context.linked ? (
            <p className={workspaceStyles.helperText}>
              Dieser Anime hat aktuell keinen persistierten Jellyfin-Link. Phase 4 zeigt hier bewusst keine verdeckte Auto-Verknüpfung.
            </p>
          ) : null}
        </>
      ) : null}

      {preview ? (
        <div className={workspaceStyles.sectionCard}>
          <div className={workspaceStyles.panelHeader}>
            <div>
              <h3 className={styles.sectionTitle}>Preview-Entscheidung</h3>
              <p className={styles.sectionMeta}>Nur explizit angehakte Provider-Assets dürfen bestehende persistierte Daten ergänzen oder ersetzen.</p>
            </div>
            <span className={`${styles.badge} ${hasApplicableDiff ? styles.badgeSuccess : styles.badgeMuted}`}>
              {hasApplicableDiff ? 'Änderungen verfügbar' : 'Keine Feld-Diffs'}
            </span>
          </div>
          <div className={workspaceStyles.sectionGridTwo}>
            {preview.diff.length === 0 ? (
              <p className={workspaceStyles.helperText}>
                Keine Feld-Änderungen vorgesehen. Nutze die Asset-Aktionen unten, wenn du Banner, Logo, Backgrounds oder Background-Videos separat verwalten willst.
              </p>
            ) : null}
            {preview.diff.map((item) => (
              <div key={item.field} className={workspaceStyles.infoPanel}>
                <span>{item.label}</span>
                <div className={styles.badgeRow}>
                  <span className={`${styles.badge} ${item.apply ? styles.badgeSuccess : styles.badgeMuted}`}>
                    {item.apply ? 'Wird gefüllt' : item.action === 'protect' ? 'Geschützt' : 'Keine Änderung'}
                  </span>
                  {item.reason ? <span className={`${styles.badge} ${styles.badgeMuted}`}>{item.reason}</span> : null}
                </div>
                <input className={styles.input} value={item.current_value || ''} readOnly disabled />
                <input className={styles.input} value={item.incoming_value || ''} readOnly disabled />
              </div>
            ))}
          </div>

          <div className={workspaceStyles.toggleStack}>
            <label className={workspaceStyles.choiceCard}>
              <div className={workspaceStyles.choiceHeader}>
                <input
                  type="checkbox"
                  checked={applyCover}
                  disabled={!preview.cover.can_apply || isApplying}
                  onChange={(event) => setApplyCover(event.target.checked)}
                />
                <div>
                  <strong>Jellyfin-Cover übernehmen</strong>
                  <p className={workspaceStyles.helperText}>
                    {preview.cover.can_apply
                      ? `Aktuell: ${formatCoverSource(preview.cover.current_source)}. Provider-Cover wird nur mit explizitem Haken angewendet.`
                      : preview.cover.reason || 'Kein Jellyfin-Cover verfügbar.'}
                  </p>
                </div>
              </div>
            </label>

            <label className={workspaceStyles.choiceCard}>
              <div className={workspaceStyles.choiceHeader}>
                <input
                  type="checkbox"
                  checked={applyBanner}
                  disabled={!preview.asset_slots.banner.present || isApplying}
                  onChange={(event) => setApplyBanner(event.target.checked)}
                />
                <div>
                  <strong>Jellyfin-Banner übernehmen</strong>
                  <p className={workspaceStyles.helperText}>
                    {preview.asset_slots.banner.present
                      ? 'Provider-Banner wird nur mit explizitem Haken übernommen. Manuelle Banner bleiben bis zum Entfernen geschützt.'
                      : 'Kein Jellyfin-Banner verfügbar.'}
                  </p>
                </div>
              </div>
            </label>

            <label className={workspaceStyles.choiceCard}>
              <div className={workspaceStyles.choiceHeader}>
                <input
                  type="checkbox"
                  checked={applyBackgrounds}
                  disabled={preview.asset_slots.backgrounds.length === 0 || isApplying}
                  onChange={(event) => setApplyBackgrounds(event.target.checked)}
                />
                <div>
                  <strong>Jellyfin-Backgrounds übernehmen</strong>
                  <p className={workspaceStyles.helperText}>
                    {preview.asset_slots.backgrounds.length > 0
                      ? 'Provider-Backgrounds werden nur mit explizitem Haken aktualisiert oder ergänzt. Manuelle Backgrounds bleiben geschützt.'
                      : 'Keine Jellyfin-Backgrounds verfügbar.'}
                  </p>
                </div>
              </div>
            </label>
          </div>

          <div className={styles.actionsRow}>
            <button
              type="button"
              className={`${styles.button} ${styles.buttonPrimary}`}
              disabled={!canApply || isApplying}
              onClick={() => void handleApply()}
            >
              {isApplying ? 'Metadaten werden übernommen...' : 'Preview anwenden'}
            </button>
          </div>
        </div>
      ) : null}

      {assetCards.length > 0 && context ? (
        <div className={workspaceStyles.sectionCard}>
          <div className={styles.sectionHeader}>
            <div>
              <h3 className={styles.sectionTitle}>Asset-Provenance</h3>
              <p className={styles.sectionMeta}>
                Cover, Banner, Logo, Backgrounds und Background-Video können explizit aus Jellyfin übernommen und manuell ersetzt oder ergänzt werden.
              </p>
            </div>
          </div>

          <AnimeJellyfinAssetUploadControls
            animeID={animeID}
            disabled={isBusy}
            assetCards={assetCards}
            coverCurrentImage={context.cover.current_image}
            coverCurrentSource={context.cover.current_source}
            persistedAssets={context.persisted_assets}
            onSuccess={onSuccess}
            onError={onError}
            onAfterMutation={async () => {
              await onAfterApply()
              await refreshContext()
            }}
          />
        </div>
      ) : null}
    </section>
  )
}

'use client'

import styles from '../../AdminStudio.module.css'
import relationStyles from './AnimeRelationsSection.module.css'
import {
  AdminAnimeRelation,
  AdminAnimeRelationLabel,
  AdminAnimeRelationTarget,
} from '@/types/admin'
import {
  UseAdminAnimeRelationsModel,
  buildRelationsSummary,
  useAdminAnimeRelations,
} from '../../hooks/useAdminAnimeRelations'

const RELATION_LABELS: AdminAnimeRelationLabel[] = [
  'Hauptgeschichte',
  'Nebengeschichte',
  'Fortsetzung',
  'Zusammenfassung',
]

interface AnimeRelationsSectionProps {
  animeID: number
  defaultOpen?: boolean
  modelOverride?: UseAdminAnimeRelationsModel
  onSuccess?: (message: string) => void
  onError?: (message: string) => void
  [legacyProp: string]: unknown
}

function formatTargetMeta(target: AdminAnimeRelationTarget): string {
  const segments = [`#${String(target.anime_id).padStart(3, '0')}`, `Typ ${target.type}`]
  if (target.year) {
    segments.push(String(target.year))
  }
  return segments.join(' | ')
}

function formatRelationMeta(relation: AdminAnimeRelation): string {
  const segments = [`#${String(relation.target_anime_id).padStart(3, '0')}`, relation.relation_label, `Typ ${relation.target_type}`]
  if (relation.target_year) {
    segments.push(String(relation.target_year))
  }
  return segments.join(' | ')
}

export function AnimeRelationsSection({
  animeID,
  defaultOpen = false,
  modelOverride,
  onSuccess,
  onError,
}: AnimeRelationsSectionProps) {
  const liveModel = useAdminAnimeRelations({ animeID, onSuccess, onError })
  const model = modelOverride ?? liveModel

  return (
    <section className={`${styles.card} ${relationStyles.sectionCard}`}>
      <details className={relationStyles.details} open={defaultOpen}>
        <summary className={relationStyles.summary}>
          <div className={relationStyles.summaryTitle}>
            <div>
              <h2 className={styles.sectionTitle}>Relationen</h2>
              <p className={styles.sectionMeta}>Bestehende Anime-Verknüpfungen pflegen, ohne die Edit-Route zu verlassen.</p>
            </div>
            <div className={relationStyles.summaryRow}>
              <span>{buildRelationsSummary(model.relations, model.errorMessage)}</span>
              {model.isLoading ? <span>Lade...</span> : null}
            </div>
          </div>
        </summary>

        <div className={relationStyles.content}>
          <p className={relationStyles.helper}>
            Der ausgewählte Typ beschreibt immer das Ziel-Anime aus Sicht des aktuell bearbeiteten Anime.
            Beispiel: <strong>Fortsetzung</strong> bedeutet, dass das Ziel die Fortsetzung dieses Anime ist.
          </p>

          {model.errorMessage ? <p className={relationStyles.errorBox}>{model.errorMessage}</p> : null}

          <div className={relationStyles.grid}>
            <div className={relationStyles.searchBlock}>
              <label className={relationStyles.field}>
                <span>Ziel-Anime suchen</span>
                <input
                  className={styles.input}
                  value={model.query}
                  onChange={(event) => model.setQuery(event.target.value)}
                  placeholder="Titel eingeben"
                />
              </label>

              {model.isSearching ? <p className={relationStyles.emptyState}>Suche läuft...</p> : null}

              {model.targets.length > 0 ? (
                <div className={relationStyles.results}>
                  {model.targets.map((target) => (
                    <button
                      key={target.anime_id}
                      type="button"
                      className={relationStyles.resultButton}
                      onClick={() => model.selectTarget(target)}
                    >
                      <strong>{target.title}</strong>
                      <div className={relationStyles.resultMeta}>{formatTargetMeta(target)}</div>
                    </button>
                  ))}
                </div>
              ) : null}
            </div>

            <div className={relationStyles.createBlock}>
              <label className={relationStyles.field}>
                <span>Relationstyp</span>
                <select
                  className={styles.select}
                  value={model.relationLabel}
                  onChange={(event) => model.setRelationLabel(event.target.value as AdminAnimeRelationLabel)}
                >
                  {RELATION_LABELS.map((label) => (
                    <option key={label} value={label}>
                      {label}
                    </option>
                  ))}
                </select>
              </label>

              {model.selectedTarget ? (
                <p className={relationStyles.helper}>
                  Ausgewählt: <strong>{model.selectedTarget.title}</strong> ({formatTargetMeta(model.selectedTarget)})
                </p>
              ) : (
                <p className={relationStyles.helper}>Noch kein Ziel-Anime ausgewählt.</p>
              )}

              {model.inlineError ? <p className={relationStyles.errorBox}>{model.inlineError}</p> : null}

              <div className={relationStyles.actions}>
                <button type="button" className={`${styles.button} ${styles.buttonSuccess}`} onClick={() => void model.createRelation()} disabled={model.isSaving}>
                  Relation speichern
                </button>
              </div>
            </div>
          </div>

          <div className={relationStyles.listBlock}>
            <h3 className={styles.sectionTitle}>Bestehende Relationen</h3>
            {model.relations.length === 0 ? <p className={relationStyles.emptyState}>Noch keine Relationen vorhanden.</p> : null}

            {model.relations.map((relation) => {
              const isEditing = model.editingTargetID === relation.target_anime_id
              return (
                <div key={relation.target_anime_id} className={relationStyles.relationRow}>
                  <div>
                    <strong>{relation.target_title}</strong>
                    <div className={relationStyles.relationMeta}>{formatRelationMeta(relation)}</div>
                  </div>

                  {isEditing ? (
                    <div className={relationStyles.editingRow}>
                      <select
                        className={styles.select}
                        value={model.editingLabel}
                        onChange={(event) => model.setEditingLabel(event.target.value as AdminAnimeRelationLabel)}
                      >
                        {RELATION_LABELS.map((label) => (
                          <option key={label} value={label}>
                            {label}
                          </option>
                        ))}
                      </select>
                      <button type="button" className={`${styles.button} ${styles.buttonSuccess}`} onClick={() => void model.saveEditing()} disabled={model.isSaving}>
                        Speichern
                      </button>
                      <button type="button" className={styles.buttonSecondary} onClick={() => model.cancelEditing()}>
                        Abbrechen
                      </button>
                    </div>
                  ) : (
                    <div className={relationStyles.actions}>
                      <button type="button" className={styles.buttonSecondary} onClick={() => model.startEditing(relation)}>
                        Bearbeiten
                      </button>
                      <button
                        type="button"
                        className={styles.buttonSecondary}
                        onClick={() => {
                          if (typeof window === 'undefined' || window.confirm('Relation wirklich löschen?')) {
                            void model.deleteRelation(relation.target_anime_id)
                          }
                        }}
                      >
                        Löschen
                      </button>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </div>
      </details>
    </section>
  )
}

'use client'

import { useEffect, useState } from 'react'

import { getAnimeByID } from '@/lib/api'
import { AdminAnimeTheme, AdminAnimeThemeSegment } from '@/types/admin'

import styles from '../../AdminStudio.module.css'
import themeStyles from './AnimeThemesSection.module.css'
import { UseAdminAnimeThemesModel, useAdminAnimeThemes } from '../../hooks/useAdminAnimeThemes'

interface AnimeThemesSectionProps {
  animeID: number
  defaultOpen?: boolean
  modelOverride?: UseAdminAnimeThemesModel
  onSuccess?: (message: string) => void
  onError?: (message: string) => void
  [legacyProp: string]: unknown
}

interface EpisodeOption {
  id: number
  label: string
}

interface AnimeThemeRowProps {
  animeID: number
  theme: AdminAnimeTheme
  episodes: EpisodeOption[]
  model: UseAdminAnimeThemesModel
}

function buildThemeSummary(themes: AdminAnimeTheme[], errorMessage: string | null): string {
  const countLabel = themes.length === 1 ? '1 Theme' : `${themes.length} Themes`
  if (errorMessage) {
    return `${countLabel} | Fehler vorhanden`
  }

  return countLabel
}

function formatThemeMeta(theme: AdminAnimeTheme): string {
  const parts = [`#${theme.id}`, theme.theme_type_name]
  if (theme.title) {
    parts.push(theme.title)
  }
  return parts.join(' | ')
}

function formatSegmentLabel(segment: AdminAnimeThemeSegment): string {
  const start = segment.start_episode_number ?? 'Start offen'
  const end = segment.end_episode_number ?? 'Ende offen'
  return `${start} bis ${end}`
}

function AnimeThemeRow({ animeID, theme, episodes, model }: AnimeThemeRowProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [startEpisodeID, setStartEpisodeID] = useState<number | null>(null)
  const [endEpisodeID, setEndEpisodeID] = useState<number | null>(null)
  const isEditing = model.editingThemeID === theme.id
  const loadedSegments = model.segments.get(theme.id) ?? []

  return (
    <details
      className={themeStyles.themeRow}
      onToggle={(event) => {
        const nextOpen = (event.currentTarget as HTMLDetailsElement).open
        setIsOpen(nextOpen)
        if (nextOpen) {
          void model.loadSegments(theme.id)
        }
      }}
    >
      <summary className={themeStyles.summary}>
        <div className={themeStyles.summaryTitle}>
          <div>
            <strong>{theme.title?.trim() || theme.theme_type_name}</strong>
            <div className={themeStyles.themeMeta}>{formatThemeMeta(theme)}</div>
          </div>
          <div className={themeStyles.actions}>
            {!isEditing ? (
              <>
                <button type="button" className={styles.buttonSecondary} onClick={() => model.startEditing(theme)}>
                  Bearbeiten
                </button>
                <button
                  type="button"
                  className={styles.buttonSecondary}
                  onClick={() => {
                    if (typeof window === 'undefined' || window.confirm('Theme wirklich löschen?')) {
                      void model.deleteTheme(theme.id)
                    }
                  }}
                >
                  Löschen
                </button>
              </>
            ) : null}
          </div>
        </div>
      </summary>

      <div className={themeStyles.content}>
        {isEditing ? (
          <div className={themeStyles.editingRow}>
            <select
              className={styles.select}
              value={model.editingTypeID}
              onChange={(event) => model.setEditingTypeID(Number(event.target.value))}
            >
              {model.themeTypes.map((type) => (
                <option key={type.id} value={type.id}>
                  {type.name}
                </option>
              ))}
            </select>
            <input
              className={styles.input}
              value={model.editingTitle}
              onChange={(event) => model.setEditingTitle(event.target.value)}
              placeholder="Optionaler Titel"
            />
            <button type="button" className={`${styles.button} ${styles.buttonSuccess}`} onClick={() => void model.saveEditing()} disabled={model.isSaving}>
              Speichern
            </button>
            <button type="button" className={styles.buttonSecondary} onClick={() => model.cancelEditing()}>
              Abbrechen
            </button>
          </div>
        ) : (
          <p className={themeStyles.helper}>
            Theme-Typ <strong>{theme.theme_type_name}</strong> für Anime #{animeID}. Segmente nutzen die Episoden-IDs, zeigen aber
            die Episodennummern an.
          </p>
        )}

        <div className={themeStyles.segmentCard}>
          <h3 className={styles.sectionTitle}>Episodenbereiche</h3>
          <div className={themeStyles.episodeSelects}>
            <label className={themeStyles.field}>
              <span>Start-Episode</span>
              <select
                className={styles.select}
                value={startEpisodeID ?? ''}
                onChange={(event) => setStartEpisodeID(event.target.value ? Number(event.target.value) : null)}
              >
                <option value="">Offen</option>
                {episodes.map((episode) => (
                  <option key={`${theme.id}-start-${episode.id}`} value={episode.id}>
                    {episode.label}
                  </option>
                ))}
              </select>
            </label>

            <label className={themeStyles.field}>
              <span>End-Episode</span>
              <select
                className={styles.select}
                value={endEpisodeID ?? ''}
                onChange={(event) => setEndEpisodeID(event.target.value ? Number(event.target.value) : null)}
              >
                <option value="">Offen</option>
                {episodes.map((episode) => (
                  <option key={`${theme.id}-end-${episode.id}`} value={episode.id}>
                    {episode.label}
                  </option>
                ))}
              </select>
            </label>
          </div>

          <div className={themeStyles.segmentForm}>
            <button
              type="button"
              className={styles.buttonPrimary}
              disabled={model.isSaving}
              onClick={async () => {
                await model.createSegment(theme.id, startEpisodeID, endEpisodeID)
                setStartEpisodeID(null)
                setEndEpisodeID(null)
                if (!isOpen) {
                  void model.loadSegments(theme.id)
                }
              }}
            >
              Episodenbereich hinzufügen
            </button>
          </div>

          {loadedSegments.length === 0 ? <p className={themeStyles.emptyState}>Noch keine Segmente vorhanden.</p> : null}

          {loadedSegments.length > 0 ? (
            <div className={themeStyles.segmentList}>
              {loadedSegments.map((segment) => (
                <div key={segment.id} className={themeStyles.segmentRow}>
                  <div>
                    <strong>{formatSegmentLabel(segment)}</strong>
                    <div className={themeStyles.segmentMeta}>
                      Start-ID {segment.start_episode_id ?? 'offen'} | Ende-ID {segment.end_episode_id ?? 'offen'}
                    </div>
                  </div>
                  <button
                    type="button"
                    className={styles.buttonSecondary}
                    onClick={() => void model.deleteSegment(theme.id, segment.id)}
                  >
                    Löschen
                  </button>
                </div>
              ))}
            </div>
          ) : null}
        </div>
      </div>
    </details>
  )
}

export function AnimeThemesSection({
  animeID,
  defaultOpen = false,
  modelOverride,
  onSuccess,
  onError,
}: AnimeThemesSectionProps) {
  const hookModel = useAdminAnimeThemes({ animeID, onSuccess, onError })
  const model = modelOverride ?? hookModel
  const [episodes, setEpisodes] = useState<EpisodeOption[]>([])

  useEffect(() => {
    let active = true
    getAnimeByID(animeID, { include_disabled: true })
      .then((response) => {
        if (!active) return
        const nextEpisodes = response.data.episodes.map((episode) => ({
          id: episode.id,
          label: `Episode ${episode.episode_number}${episode.title ? ` - ${episode.title}` : ''}`,
        }))
        setEpisodes(nextEpisodes)
      })
      .catch(() => {
        if (active) {
          setEpisodes([])
        }
      })

    return () => {
      active = false
    }
  }, [animeID])

  return (
    <section className={`${styles.card} ${themeStyles.sectionCard}`}>
      <details className={themeStyles.details} open={defaultOpen}>
        <summary className={themeStyles.summary}>
          <div className={themeStyles.summaryTitle}>
            <div>
              <h2 className={styles.sectionTitle}>OP/ED Themes</h2>
              <p className={styles.sectionMeta}>Themes, Typen und Episodenbereiche direkt auf der Edit-Seite pflegen.</p>
            </div>
            <div className={themeStyles.summaryRow}>
              <span>{buildThemeSummary(model.themes, model.errorMessage)}</span>
              {model.isLoading ? <span>Lade...</span> : null}
            </div>
          </div>
        </summary>

        <div className={themeStyles.content}>
          <p className={themeStyles.helper}>
            Theme-Typen kommen aus der Datenbank. Segmente zeigen die Episodennummer für die Lesbarkeit, senden an die API aber
            immer die Episode-ID.
          </p>

          {model.errorMessage ? <p className={themeStyles.errorBox}>{model.errorMessage}</p> : null}

          <div className={themeStyles.grid}>
            <div className={themeStyles.createBlock}>
              <label className={themeStyles.field}>
                <span>Theme-Typ</span>
                <select
                  className={styles.select}
                  value={model.newTypeID}
                  onChange={(event) => model.setNewTypeID(Number(event.target.value))}
                >
                  <option value={0}>Bitte wählen</option>
                  {model.themeTypes.map((type) => (
                    <option key={type.id} value={type.id}>
                      {type.name}
                    </option>
                  ))}
                </select>
              </label>

              <label className={themeStyles.field}>
                <span>Optionaler Titel</span>
                <input
                  className={styles.input}
                  value={model.newTitle}
                  onChange={(event) => model.setNewTitle(event.target.value)}
                  placeholder="z. B. Creditless"
                />
              </label>

              {model.inlineError ? <p className={themeStyles.errorBox}>{model.inlineError}</p> : null}

              <div className={themeStyles.actions}>
                <button type="button" className={`${styles.button} ${styles.buttonSuccess}`} onClick={() => void model.createTheme()} disabled={model.isSaving}>
                  Theme speichern
                </button>
              </div>
            </div>

            <div className={themeStyles.listBlock}>
              <h3 className={styles.sectionTitle}>Bestehende Themes</h3>
              {model.themes.length === 0 ? <p className={themeStyles.emptyState}>Noch keine Themes vorhanden.</p> : null}

              {model.themes.map((theme) => (
                <AnimeThemeRow
                  key={theme.id}
                  animeID={animeID}
                  theme={theme}
                  episodes={episodes}
                  model={model}
                />
              ))}
            </div>
          </div>
        </div>
      </details>
    </section>
  )
}

