import Image from 'next/image'
import { useRef } from 'react'

import { AnimePatchClearFlags, AnimePatchValues } from '../../types/admin-anime'
import { handleCoverImgError, resolveCoverUrl } from '../../utils/anime-helpers'
import styles from '../../../admin.module.css'

interface AnimeCoverFieldProps {
  values: AnimePatchValues
  clearFlags: AnimePatchClearFlags
  contextCoverImage?: string
  isSubmitting: boolean
  isUploadingCover: boolean
  onFieldChange: (field: keyof AnimePatchValues, value: string) => void
  onClearFlagChange: (field: keyof AnimePatchClearFlags, value: boolean) => void
  onUploadFile: (file: File) => Promise<void>
  onRemoveCover: () => Promise<void>
}

export function AnimeCoverField({
  values,
  clearFlags,
  contextCoverImage,
  isSubmitting,
  isUploadingCover,
  onFieldChange,
  onClearFlagChange,
  onUploadFile,
  onRemoveCover,
}: AnimeCoverFieldProps) {
  const fileInputRef = useRef<HTMLInputElement>(null)
  return (
    <div className={styles.field}>
      <label htmlFor="update-cover-image">Cover Image</label>
      <input
        id="update-cover-image"
        value={values.coverImage}
        onChange={(event) => onFieldChange('coverImage', event.target.value)}
        disabled={isSubmitting || isUploadingCover || clearFlags.coverImage}
      />
      <label className={styles.nullToggle}>
        <input
          type="checkbox"
          checked={clearFlags.coverImage}
          onChange={(event) => onClearFlagChange('coverImage', event.target.checked)}
          disabled={isSubmitting || isUploadingCover}
        />
        Wert löschen (null)
      </label>
      <div className={styles.coverInline}>
        <Image
          className={styles.coverPreviewSmall}
          src={resolveCoverUrl(clearFlags.coverImage ? '' : values.coverImage || contextCoverImage)}
          alt="Cover Vorschau"
          width={88}
          height={132}
          unoptimized
          onError={handleCoverImgError}
        />
        <div className={styles.actions}>
          <a
            className={styles.buttonSecondary}
            href={resolveCoverUrl(clearFlags.coverImage ? '' : values.coverImage || contextCoverImage)}
            target="_blank"
            rel="noreferrer"
          >
            Cover öffnen
          </a>
        </div>
        <div className={styles.actions}>
          <input
            ref={fileInputRef}
            className={styles.fileInput}
            type="file"
            accept="image/*"
            onChange={async (event) => {
              const file = event.target.files?.[0]
              if (!file) {
                return
              }
              try {
                await onUploadFile(file)
              } finally {
                event.target.value = ''
              }
            }}
            disabled={isUploadingCover || isSubmitting}
          />
          <button
            className={styles.buttonSecondary}
            type="button"
            disabled={isUploadingCover || isSubmitting}
            onClick={() => fileInputRef.current?.click()}
          >
            {isUploadingCover ? 'Upload...' : 'Cover hochladen (lokal)'}
          </button>
          {contextCoverImage ? (
            <button
              className={styles.buttonSecondary}
              type="button"
              disabled={isUploadingCover || isSubmitting}
              onClick={() => {
                onFieldChange('coverImage', contextCoverImage || '')
                onClearFlagChange('coverImage', false)
              }}
            >
              Kontext-Cover einsetzen
            </button>
          ) : null}
          <button className={styles.buttonSecondary} type="button" disabled={isUploadingCover || isSubmitting} onClick={() => void onRemoveCover()}>
            Cover entfernen
          </button>
        </div>
        <p className={styles.hint}>
          Hinweis: Cover-Upload nutzt die verifizierte V2-Upload-Seam; Banner, Logo, Backgrounds und Background-Video hängen an derselben Asset-Logik.
        </p>
      </div>
    </div>
  )
}

import { KeyboardEvent } from 'react'

import { FormField } from '@/components/ui/FormField'
import { Textarea } from '@/components/ui/Textarea'
import { AnimePatchClearFlags, AnimePatchValues } from '../../types/admin-anime'
import styles from '../../../admin.module.css'

interface GenreSuggestion {
  name: string
  count: number
}

interface AnimeMetaFieldsProps {
  values: AnimePatchValues
  clearFlags: AnimePatchClearFlags
  isSubmitting: boolean
  genreSuggestions: GenreSuggestion[]
  genreSuggestionsTotal: number
  loadedGenreCount: number
  isLoadingGenreTokens: boolean
  genreTokensError: string | null
  genreSuggestionLimit: number
  onFieldChange: (field: keyof AnimePatchValues, value: string) => void
  onClearFlagChange: (field: keyof AnimePatchClearFlags, value: boolean) => void
  onAddGenreToken: (token: string) => void
  onRemoveGenreToken: (token: string) => void
  onGenreSuggestionLimitChange: (next: number) => void
}

export function AnimeMetaFields({
  values,
  clearFlags,
  isSubmitting,
  genreSuggestions,
  genreSuggestionsTotal,
  loadedGenreCount,
  isLoadingGenreTokens,
  genreTokensError,
  genreSuggestionLimit,
  onFieldChange,
  onClearFlagChange,
  onAddGenreToken,
  onRemoveGenreToken,
  onGenreSuggestionLimitChange,
}: AnimeMetaFieldsProps) {
  const groupedSuggestions = genreSuggestions.reduce<Record<string, GenreSuggestion[]>>((acc, token) => {
    const first = token.name.trim().charAt(0).toUpperCase()
    const key = /[A-F]/.test(first) ? 'A-F' : /[G-M]/.test(first) ? 'G-M' : /[N-T]/.test(first) ? 'N-T' : 'U-Z/0-9'
    if (!acc[key]) acc[key] = []
    acc[key].push(token)
    return acc
  }, {})

  const onGenreInputKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key !== 'Enter') return
    event.preventDefault()
    onAddGenreToken(values.genreDraft)
    onFieldChange('genreDraft', '')
  }

  return (
    <div className={styles.grid}>
      <div className={styles.field}>
        <label htmlFor="update-genre">Genre</label>
        {values.genreTokens.length > 0 ? (
          <div className={styles.chipRow} aria-label="Ausgewählte Genres">
            {values.genreTokens.map((token) => (
              <button
                key={token}
                type="button"
                className={`${styles.chip} ${styles.chipActive}`}
                onClick={() => onRemoveGenreToken(token)}
                disabled={isSubmitting || clearFlags.genre}
                title="Klicken zum Entfernen"
              >
                {token} x
              </button>
            ))}
          </div>
        ) : (
          <p className={styles.hint}>Noch keine Genres gesetzt.</p>
        )}

        <div className={styles.inputRow}>
          <input
            id="update-genre"
            value={values.genreDraft}
            onChange={(event) => onFieldChange('genreDraft', event.target.value)}
            disabled={isSubmitting || clearFlags.genre}
            placeholder="Genre hinzufügen (Komma getrennt)"
            onKeyDown={onGenreInputKeyDown}
          />
          <button
            type="button"
            className={styles.buttonSecondary}
            disabled={isSubmitting || clearFlags.genre || values.genreDraft.trim().length === 0}
            onClick={() => {
              onAddGenreToken(values.genreDraft)
              onFieldChange('genreDraft', '')
            }}
          >
            Hinzufügen
          </button>
        </div>

        {isLoadingGenreTokens ? <p className={styles.hint}>Genre-Vorschläge werden geladen...</p> : null}
        {genreTokensError ? <p className={styles.hint}>Hinweis: {genreTokensError}</p> : null}
        {!isLoadingGenreTokens && !clearFlags.genre && genreSuggestions.length > 0 ? (
          <>
            <p className={styles.hint}>
              Vorschläge: {genreSuggestions.length}/{genreSuggestionsTotal} (geladen: {loadedGenreCount})
            </p>
            <div className={styles.genreSuggestionBox} aria-label="Genre Vorschläge">
              {Object.entries(groupedSuggestions).map(([group, tokens]) => (
                <div key={group} className={styles.genreSuggestionGroup}>
                  <p className={styles.genreSuggestionGroupTitle}>{group}</p>
                  <div className={styles.genreSuggestionList}>
                    {tokens.map((token) => (
                      <button
                        key={`${group}-${token.name}`}
                        type="button"
                        className={styles.genreSuggestionItem}
                        onClick={() => onAddGenreToken(token.name)}
                        disabled={isSubmitting || clearFlags.genre}
                        title={`+ ${token.name} (x${token.count})`}
                      >
                        <span>{token.name}</span>
                        <span className={styles.genreSuggestionCount}>x{token.count}</span>
                      </button>
                    ))}
                  </div>
                </div>
              ))}
            </div>
            <div className={styles.actions}>
              <button
                type="button"
                className={styles.buttonSecondary}
                disabled={isSubmitting || clearFlags.genre || genreSuggestionLimit >= 1000}
                onClick={() => onGenreSuggestionLimitChange(genreSuggestionLimit + 40)}
              >
                Mehr anzeigen
              </button>
              <button
                type="button"
                className={styles.buttonSecondary}
                disabled={isSubmitting || clearFlags.genre || genreSuggestionLimit <= 40}
                onClick={() => onGenreSuggestionLimitChange(40)}
              >
                Zurücksetzen
              </button>
              </div>
          </>
        ) : null}
        <label className={styles.nullToggle}>
          <input
            type="checkbox"
            checked={clearFlags.genre}
            onChange={(event) => onClearFlagChange('genre', event.target.checked)}
            disabled={isSubmitting}
          />
          Wert löschen (null)
        </label>
        <p className={styles.hint}>Aktuell: {values.genreTokens.join(', ') || '(leer)'}</p>
      </div>
      <div className={styles.field}>
        <FormField label="Beschreibung" htmlFor="update-description">
          <Textarea
            id="update-description"
            value={values.description}
            onChange={(event) => onFieldChange('description', event.target.value)}
            disabled={isSubmitting || clearFlags.description}
          />
        </FormField>
        <label className={styles.nullToggle}>
          <input
            type="checkbox"
            checked={clearFlags.description}
            onChange={(event) => onClearFlagChange('description', event.target.checked)}
            disabled={isSubmitting}
          />
          Wert löschen (null)
        </label>
      </div>
    </div>
  )
}

import { FormEvent, useEffect, useRef, useState } from 'react'

import { deleteAdminAnimeCoverAsset, getAnimeByID } from '@/lib/api'
import { AdminAnimeAssetKind, AnimeType } from '@/types/admin'
import { AnimeDetail, AnimeStatus, ContentType } from '@/types/anime'

import { parsePositiveInt } from '../../utils/anime-helpers'
import { useAnimePatch } from '../../hooks/useAnimePatch'
import { AnimeBasicFields } from './AnimeBasicFields'
import { AnimeMetaFields } from './AnimeMetaFields'
import { AnimeCoverField } from './AnimeCoverField'
import styles from '../../../admin.module.css'

const ANIME_TYPES: AnimeType[] = ['tv', 'film', 'ova', 'ona', 'special', 'bonus']
const CONTENT_TYPES: ContentType[] = ['anime', 'hentai']
const ANIME_STATUSES: AnimeStatus[] = ['disabled', 'ongoing', 'done', 'aborted', 'licensed']
const NON_COVER_ASSET_UPLOADS: Array<{ kind: Exclude<AdminAnimeAssetKind, 'cover'>; label: string; accept: string }> = [
  { kind: 'banner', label: 'Banner hochladen', accept: 'image/*' },
  { kind: 'logo', label: 'Logo hochladen', accept: 'image/*' },
  { kind: 'background', label: 'Background anhaengen', accept: 'image/*' },
  { kind: 'background_video', label: 'Background-Video hochladen', accept: 'video/*' },
]

interface AnimePatchFormProps {
  anime: AnimeDetail | null
  onSuccess: (anime: AnimeDetail) => void
  onError: (msg: string) => void
  onRequest?: (request: string | null) => void
  onResponse?: (response: string | null) => void
  onEditorStateChange?: (state: { hasUnsavedChanges: boolean; isSaving: boolean }) => void
  onRegisterSaveAction?: (saveAction: (() => void) | null) => void
}

export function AnimePatchForm({
  anime,
  onSuccess,
  onError,
  onRequest,
  onResponse,
  onEditorStateChange,
  onRegisterSaveAction,
}: AnimePatchFormProps) {
  const [animeIDInput, setAnimeIDInput] = useState('')
  const formRef = useRef<HTMLFormElement>(null)
  const bannerInputRef = useRef<HTMLInputElement>(null)
  const logoInputRef = useRef<HTMLInputElement>(null)
  const backgroundInputRef = useRef<HTMLInputElement>(null)
  const backgroundVideoInputRef = useRef<HTMLInputElement>(null)

  const patch = useAnimePatch(onSuccess, onError, {
    onRequest,
    onResponse,
  })

  useEffect(() => {
    if (!anime) {
      setAnimeIDInput('')
      return
    }

    setAnimeIDInput(String(anime.id))
    patch.resetFromAnime(anime)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [anime?.id])

  useEffect(() => {
    onEditorStateChange?.({ hasUnsavedChanges: patch.isDirty, isSaving: patch.isSubmitting })
  }, [onEditorStateChange, patch.isDirty, patch.isSubmitting])

  useEffect(() => {
    onRegisterSaveAction?.(() => {
      formRef.current?.requestSubmit()
    })
    return () => onRegisterSaveAction?.(null)
  }, [onRegisterSaveAction])

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    onRequest?.(null)
    onResponse?.(null)

    const animeID = parsePositiveInt(animeIDInput) ?? anime?.id ?? null
    if (!animeID) {
      onError('Anime-ID ist ungültig.')
      return
    }

    await patch.submit(animeID)
  }

  const handleRemoveCover = async () => {
    if (!anime) {
      onError('Bitte zuerst einen Anime-Kontext laden.')
      return
    }
    try {
      await deleteAdminAnimeCoverAsset(anime.id)
      const refreshed = await getAnimeByID(anime.id, { include_disabled: true })
      patch.setField('coverImage', '')
      patch.setClearFlag('coverImage', false)
      onSuccess(refreshed.data)
    } catch (error) {
      if (error instanceof Error) onError(error.message)
      else onError('Cover konnte nicht entfernt werden.')
    }
  }

  function resolveUploadRef(kind: Exclude<AdminAnimeAssetKind, 'cover'>) {
    if (kind === 'banner') return bannerInputRef
    if (kind === 'logo') return logoInputRef
    if (kind === 'background_video') return backgroundVideoInputRef
    return backgroundInputRef
  }

  async function handleNonCoverUpload(kind: Exclude<AdminAnimeAssetKind, 'cover'>, file: File) {
    const animeID = parsePositiveInt(animeIDInput) ?? anime?.id ?? null
    await patch.uploadAndLinkAsset(file, kind, animeID)
  }

  return (
    <section className={`${styles.panel} ${styles.editPanel}`}>
      <h2>Anime bearbeiten</h2>
      <p className={styles.hint}>
        Inhalte und Metadaten aktualisieren. Ohne ID wird die aktuell geladene Kontext-ID verwendet.
      </p>
      <form ref={formRef} className={styles.form} onSubmit={handleSubmit}>
        <AnimeBasicFields
          animeIDInput={animeIDInput}
          values={patch.values}
          clearFlags={patch.clearFlags}
          isSubmitting={patch.isSubmitting}
          animeTypes={ANIME_TYPES}
          contentTypes={CONTENT_TYPES}
          animeStatuses={ANIME_STATUSES}
          onAnimeIDChange={setAnimeIDInput}
          onFieldChange={(field, value) => patch.setField(field, value)}
          onClearFlagChange={patch.setClearFlag}
        />

        <div className={styles.grid}>
          <AnimeMetaFields
            values={patch.values}
            clearFlags={patch.clearFlags}
            isSubmitting={patch.isSubmitting}
            genreSuggestions={patch.genreSuggestions}
            genreSuggestionsTotal={patch.genreSuggestionsTotal}
            loadedGenreCount={patch.genreTokens.length}
            isLoadingGenreTokens={patch.isLoadingGenreTokens}
            genreTokensError={patch.genreTokensError}
            genreSuggestionLimit={patch.genreSuggestionLimit}
            onFieldChange={(field, value) => patch.setField(field, value)}
            onClearFlagChange={patch.setClearFlag}
            onAddGenreToken={patch.addGenreToken}
            onRemoveGenreToken={patch.removeGenreToken}
            onGenreSuggestionLimitChange={patch.setGenreSuggestionLimit}
          />

          <AnimeCoverField
            values={patch.values}
            clearFlags={patch.clearFlags}
            contextCoverImage={anime?.cover_image}
            isSubmitting={patch.isSubmitting}
            isUploadingCover={patch.isUploadingCover}
            onFieldChange={(field, value) => patch.setField(field, value)}
            onClearFlagChange={patch.setClearFlag}
            onUploadFile={async (file) => {
              const animeID = parsePositiveInt(animeIDInput) ?? anime?.id
              await patch.uploadAndSetCover(file, animeID)
            }}
            onRemoveCover={handleRemoveCover}
          />

          <div className={styles.field}>
            <label>Weitere Assets</label>
            <p className={styles.hint}>
              Banner, Logo, Backgrounds und Background-Video nutzen dieselbe verifizierte V2-Upload-Seam wie Cover.
            </p>
            {NON_COVER_ASSET_UPLOADS.map((asset) => (
              <input
                key={`${asset.kind}-input`}
                ref={resolveUploadRef(asset.kind)}
                className={styles.fileInput}
                type="file"
                accept={asset.accept}
                onChange={async (event) => {
                  const file = event.target.files?.[0]
                  if (!file) return
                  try {
                    await handleNonCoverUpload(asset.kind, file)
                  } finally {
                    event.target.value = ''
                  }
                }}
                disabled={patch.isUploadingCover || patch.isSubmitting}
              />
            ))}
            <div className={styles.actions}>
              {NON_COVER_ASSET_UPLOADS.map((asset) => (
                <button
                  key={asset.kind}
                  className={styles.buttonSecondary}
                  type="button"
                  disabled={patch.isUploadingCover || patch.isSubmitting}
                  onClick={() => resolveUploadRef(asset.kind).current?.click()}
                >
                  {asset.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className={styles.actions}>
          <button className={`${styles.button} ${styles.buttonSuccess}`} type="submit" disabled={patch.isSubmitting || !patch.isDirty}>
            {patch.isSubmitting ? 'Speichern...' : 'Änderungen speichern'}
          </button>
          {anime ? (
            <button
              className={styles.buttonSecondary}
              type="button"
              disabled={patch.isSubmitting}
              onClick={() => setAnimeIDInput(String(anime.id))}
            >
              Kontext-ID #{anime.id} einsetzen
            </button>
          ) : null}
          {anime ? (
            <button
              className={styles.buttonSecondary}
              type="button"
              disabled={patch.isSubmitting}
              onClick={() => patch.resetFromAnime(anime)}
            >
              Patch-Form aus Kontext neu fuellen
            </button>
          ) : null}
        </div>
      </form>
    </section>
  )
}

