                zugewiesen.
              </p>
              <div className={styles.contextFansubGrid}>
                {selectedEpisodeVersions.map((version) => {
                  return (
                  <article key={version.id} className={styles.contextFansubCard}>
                    <p className={styles.contextFansubTitle}>#{version.id} - {resolveVersionTitle(version)}</p>
                    <p className={styles.hint}>
                      Gruppe: {(version.fansub_groups ?? []).map((g) => g.name).join(', ') || 'keine'} | Qualitaet: {version.video_quality || 'n/a'} | Sub:{' '}
                      {version.subtitle_type || 'n/a'}
                    </p>
                    <p className={styles.hint}>
                      Provider: {version.media_provider} | Item: {version.media_item_id} | Release:{' '}
                      {formatReleaseDate(version.release_date)}
                    </p>
                    <p className={styles.contextDescription}>
                      Stream-Link (direkt): {version.stream_url || 'nicht gesetzt'}
                      <br />
                      Stream-Link (proxy): <code>/api/v1/releases/{version.id}/stream</code>
                    </p>
                    <div className={styles.actions}>
                      <Link href={`/admin/episode-versions/${version.id}/edit`} className={styles.buttonSecondary}>
                        Version bearbeiten
                      </Link>
                      {version.fansub_groups && version.fansub_groups.length > 0 ? (
                        <Link href={`/admin/fansubs/${version.fansub_groups[0].id}/edit`} className={styles.buttonSecondary}>
                          Gruppe bearbeiten
                        </Link>
                      ) : null}
                      <Link href={`/admin/anime/${animeID}/episodes/${selectedEpisode.id}/versions#version-${version.id}`} className={styles.buttonSecondary}>
                        Im Versionsbrowser
                      </Link>
                    </div>
                  </article>
                  )
                })}
              </div>
            </>
          ) : null}
        </div>

        <div className={styles.actions}>
          <button
            className={hasUnsavedChanges ? `${styles.button} ${styles.buttonSuccess}` : styles.buttonSecondary}
            type="submit"
            disabled={isUpdating || !parsePositiveInt(values.id) || !hasUnsavedChanges}
          >
            {isUpdating ? 'Speichern...' : 'Änderungen speichern'}
          </button>
          {episodeOpenID ? (
            <Link href={`/episodes/${episodeOpenID}`} className={styles.buttonSecondary} target="_blank" rel="noreferrer">
              Episode öffnen
            </Link>
          ) : null}
        </div>
      </form>
    </>
  )
}

import sharedStyles from '../../../admin.module.css'
import episodeStyles from './EpisodeManager.module.css'

const styles = { ...sharedStyles, ...episodeStyles }

interface EpisodeInlineEditProps {
  clearTitle: boolean
  disabled: boolean
  onToggleClearTitle: (value: boolean) => void
  onSave: () => void
  onCancel: () => void
}

export function EpisodeInlineEdit({ clearTitle, disabled, onToggleClearTitle, onSave, onCancel }: EpisodeInlineEditProps) {
  return (
    <div className={styles.episodeActionsCell}>
      <label className={styles.nullToggle}>
        <input
          type="checkbox"
          checked={clearTitle}
          onChange={(event) => onToggleClearTitle(event.target.checked)}
          disabled={disabled}
        />
        Feld zurücksetzen
      </label>
      <button className={`${styles.episodeMiniButton} ${styles.episodeMiniSaveButton}`} type="button" disabled={disabled} onClick={onSave}>
        Speichern
      </button>
      <button className={styles.episodeMiniButton} type="button" disabled={disabled} onClick={onCancel}>
        Abbrechen
      </button>
    </div>
  )
}

import Link from 'next/link'
import { MoreHorizontal } from 'lucide-react'

import { EpisodeListItem, EpisodeStatus } from '@/types/anime'

import { formatEpisodeStatusLabel, resolveEpisodeStatusClass } from '../../utils/anime-helpers'
import { EpisodeInlineEdit } from './EpisodeInlineEdit'
import sharedStyles from '../../../admin.module.css'
import episodeStyles from './EpisodeManager.module.css'

const styles = { ...sharedStyles, ...episodeStyles }

interface EpisodeRowProps {
  episode: EpisodeListItem
  isSelected: boolean
  isInlineEditing: boolean
  inlineValues: { number: string; title: string; status: EpisodeStatus; clearTitle: boolean }
  isUpdating: boolean
  isApplyingBulk: boolean
  isRemoving: boolean
  statuses: EpisodeStatus[]
  onSelect: () => void
  onToggleSelected: () => void
  onBeginInlineEdit: () => void
  onInlineFieldChange: (field: 'number' | 'title' | 'status' | 'clearTitle', value: string | boolean) => void
  onSaveInlineEdit: () => void
  onCancelInlineEdit: () => void
  onRemove: () => void
}

export function EpisodeRow({
  episode,
  isSelected,
  isInlineEditing,
  inlineValues,
  isUpdating,
  isApplyingBulk,
  isRemoving,
  statuses,
  onSelect,
  onToggleSelected,
  onBeginInlineEdit,
  onInlineFieldChange,
  onSaveInlineEdit,
  onCancelInlineEdit,
  onRemove,
}: EpisodeRowProps) {
  const rowDisabled = isUpdating || isApplyingBulk

  return (
    <div
      className={`${styles.episodeTableRow} ${isSelected ? styles.episodeTableRowSelected : ''} ${isInlineEditing ? '' : styles.episodeTableRowClickable}`}
      role={isInlineEditing ? undefined : 'button'}
      tabIndex={isInlineEditing ? undefined : 0}
      onKeyDown={
        isInlineEditing
          ? undefined
          : (event) => {
              if (rowDisabled) return
              if (event.key !== 'Enter' && event.key !== ' ') return
              event.preventDefault()
              onSelect()
            }
      }
      onClick={
        isInlineEditing
          ? undefined
          : (event) => {
              if (rowDisabled) return
              const target = event.target as HTMLElement | null
              if (!target) return
              if (target.closest('input,button,a,select,label,summary')) return
              onSelect()
            }
      }
    >
      <div className={styles.episodeSelect}>
        <input
          type="checkbox"
          checked={isSelected}
          onChange={onToggleSelected}
          disabled={rowDisabled || isRemoving}
          aria-label={`Episode ${episode.episode_number} markieren`}
        />
      </div>

      {isInlineEditing ? (
        <div className={styles.episodeInlineShell}>
          <div className={styles.episodeInlineGrid}>
            <input
              className={styles.episodeFieldInput}
              value={inlineValues.number}
              onChange={(event) => onInlineFieldChange('number', event.target.value)}
              disabled={rowDisabled}
              aria-label="Episode Nummer"
            />
            <input
              className={styles.episodeFieldInput}
              value={inlineValues.title}
              onChange={(event) => onInlineFieldChange('title', event.target.value)}
              disabled={rowDisabled || inlineValues.clearTitle}
              placeholder="(ohne Titel)"
              aria-label="Episode Titel"
            />
            <select
              className={styles.episodeFieldInput}
              value={inlineValues.status}
              onChange={(event) => onInlineFieldChange('status', event.target.value)}
              disabled={rowDisabled}
              aria-label="Episode Status"
            >
              {statuses.map((value) => (
                <option key={value} value={value}>
                  {formatEpisodeStatusLabel(value)}
                </option>
              ))}
            </select>
          </div>
          <EpisodeInlineEdit
            clearTitle={inlineValues.clearTitle}
            disabled={rowDisabled}
            onToggleClearTitle={(value) => onInlineFieldChange('clearTitle', value)}
            onSave={onSaveInlineEdit}
            onCancel={onCancelInlineEdit}
          />
        </div>
      ) : (
        <>
          <div className={styles.episodeRowMain}>
            <span className={styles.episodeNumberBadge}>Episode {episode.episode_number}</span>
            <div className={styles.episodeTitleWrap}>
              <span className={styles.episodeTitleCell} title={episode.title || '(ohne Titel)'}>
                {episode.title || '(ohne Titel)'}
              </span>
              <span className={styles.episodeIDCell}>ID #{episode.id}</span>
            </div>
          </div>

          <span className={`${styles.episodeStatusBadge} ${styles[resolveEpisodeStatusClass(episode.status)]}`}>
            {formatEpisodeStatusLabel(episode.status)}
          </span>

          <div className={styles.episodeActionsCell}>
            <details className={styles.rowContextMenu}>
              <summary className={styles.episodeContextTrigger} aria-label={`Aktionen für Episode ${episode.episode_number}`}>
                <MoreHorizontal size={16} />
              </summary>
              <div className={styles.rowContextMenuBody}>
                <button className={styles.episodeContextButton} type="button" disabled={rowDisabled || isRemoving} onClick={onSelect}>
                  Im Editor öffnen
                </button>
                <button className={styles.episodeContextButton} type="button" disabled={rowDisabled || isRemoving} onClick={onBeginInlineEdit}>
                  Schnell bearbeiten
                </button>
                <Link href={`/episodes/${episode.id}`} className={styles.episodeOpenLink} target="_blank" rel="noreferrer">
                  Öffnen
                </Link>
                <button className={`${styles.episodeContextButton} ${styles.episodeDangerButton}`} type="button" disabled={rowDisabled || isRemoving} onClick={onRemove}>
                  Entfernen
                </button>
              </div>
            </details>
          </div>
        </>
      )}
    </div>
  )
}

import Link from "next/link";
import type { AdminJellyfinIntakeSearchItem } from "@/types/admin";
import { resolveJellyfinIntakeAssetUrl } from "../../utils/jellyfin-intake-assets";

import styles from "./JellyfinCandidateCard.module.css";

interface JellyfinCandidateCardProps {
  candidate: AdminJellyfinIntakeSearchItem;
  currentAnimeID?: number;
  isSelected?: boolean;
  isLoadingPreview?: boolean;
  isAdopted?: boolean;
  onSelect: (candidateID: string) => void;
  onAdopt: (candidateID: string) => void;
}

function confidenceLabel(confidence: AdminJellyfinIntakeSearchItem["confidence"]) {
  switch (confidence) {
    case "high":
      return "Passend";
    case "medium":
      return "Ähnlich";
    default:
      return "Pruefen";
  }
}

export function JellyfinCandidateCard({
  candidate,
  currentAnimeID,
  isSelected = false,
  isLoadingPreview = false,
  isAdopted = false,
  onSelect,
  onAdopt,
}: JellyfinCandidateCardProps) {
  const posterUrl = resolveJellyfinIntakeAssetUrl(candidate.poster_url);
  const isCurrentAnime =
    typeof currentAnimeID === "number" &&
    typeof candidate.existing_anime_id === "number" &&
    candidate.existing_anime_id === currentAnimeID;
  const isBlockedImported = candidate.already_imported && !isCurrentAnime;

  return (
    <article className={`${styles.card} ${isSelected ? styles.selected : ""}`}>
      <div className={styles.posterWrap}>
        {posterUrl ? (
          <img
            className={styles.posterImage}
            src={posterUrl}
            alt={`Poster Vorschau für ${candidate.name}`}
          />
        ) : (
          <div className={styles.posterEmpty}>Keine Vorschau</div>
        )}
        <span
          className={`${styles.matchBadge} ${
            candidate.confidence === "high" ? styles.matchBadgeHigh : ""
          }`}
        >
          {confidenceLabel(candidate.confidence)}
        </span>
      </div>

      <div className={styles.content}>
        <div className={styles.textBlock}>
          <h3 className={styles.title}>{candidate.name}</h3>
          <p className={styles.pathText}>
            {candidate.production_year ? `${candidate.production_year} | ` : ""}
            {candidate.path || "ohne Pfad"}
          </p>
          <p className={styles.metaText}>
            {candidate.type_hint.suggested_type?.toUpperCase() || "OFFEN"}
            {candidate.parent_context ? ` | ${candidate.parent_context}` : ""}
            {candidate.library_context ? ` | ${candidate.library_context}` : ""}
          </p>
        </div>

        {isBlockedImported ? (
          <div className={styles.importedBox}>
            <strong>Bereits importiert</strong>
            <p>
              {candidate.existing_title || candidate.name}
              {candidate.existing_anime_id ? ` (#${candidate.existing_anime_id})` : ""}
            </p>
            {candidate.existing_anime_id ? (
              <Link
                className={styles.importedLink}
                href={`/admin/anime/${candidate.existing_anime_id}/edit`}
              >
                Bestehenden Anime öffnen
              </Link>
            ) : null}
          </div>
        ) : isCurrentAnime ? (
          <div className={styles.importedBox}>
            <strong>Dieser Anime</strong>
            <p>
              {candidate.existing_title || candidate.name}
              {candidate.existing_anime_id ? ` (#${candidate.existing_anime_id})` : ""}
            </p>
          </div>
        ) : null}

        <div className={styles.actionRow}>
          <button
            className={styles.secondaryButton}
            type="button"
            onClick={() => onSelect(candidate.jellyfin_series_id)}
          >
            {isSelected ? "Im Fokus" : "Ansehen"}
          </button>

          {isBlockedImported ? (
            <button className={styles.disabledButton} type="button" disabled>
              Bereits importiert
            </button>
          ) : (
            <button
              className={styles.primaryButton}
              type="button"
              onClick={() => onAdopt(candidate.jellyfin_series_id)}
              disabled={isLoadingPreview}
            >
              {isAdopted
                ? "Ausgewählt"
                : isLoadingPreview
                  ? "Übernimmt..."
                  : isCurrentAnime
                    ? "Mit diesem Anime verknüpfen"
                    : "Jellyfin übernehmen"}
            </button>
          )}
        </div>
      </div>
    </article>
  );
}

'use client'

import styles from '../../../admin.module.css'
import type { AdminJellyfinIntakeAssetSlots } from '@/types/admin'
import { resolveJellyfinIntakeAssetUrl } from '../../utils/jellyfin-intake-assets'
import type { JellyfinDraftAssetTarget } from '../../hooks/useManualAnimeDraft'

interface JellyfinDraftAssetsProps {
  animeTitle: string
  assetSlots: AdminJellyfinIntakeAssetSlots
  onRemoveAsset: (target: JellyfinDraftAssetTarget) => void
}

function slotLabel(kind: JellyfinDraftAssetTarget['kind']): string {
  switch (kind) {
    case 'cover':
      return 'Poster'
    case 'logo':
      return 'Logo'
    case 'banner':
      return 'Banner'
    case 'background':
      return 'Background'
    case 'background_video':
      return 'Background-Video'
  }
}

function missingSlotLabel(kind: Exclude<JellyfinDraftAssetTarget['kind'], 'background'>): string {
  switch (kind) {
    case 'cover':
      return 'Kein Jellyfin-Poster gefunden'
    case 'logo':
      return 'Kein Jellyfin-Logo gefunden'
    case 'banner':
      return 'Kein Jellyfin-Banner gefunden'
    case 'background_video':
      return 'Kein Jellyfin-Background-Video gefunden'
  }
}

function renderAssetPreview(animeTitle: string, kind: JellyfinDraftAssetTarget['kind'], url?: string) {
  const resolvedUrl = resolveJellyfinIntakeAssetUrl(url)
  if (!resolvedUrl && kind !== 'background_video') {
    return <p className={styles.hint}>{kind === 'background' ? 'Kein Jellyfin-Background gefunden' : missingSlotLabel(kind)}</p>
  }

  if (kind === 'background_video') {
    return (
      <div className={styles.details}>
        <strong>{slotLabel(kind)}</strong>
        <p className={styles.hint}>Jellyfin-Quelle für {animeTitle}</p>
        <a className={styles.buttonSecondary} href={resolvedUrl} target="_blank" rel="noreferrer">
          Videoquelle öffnen
        </a>
      </div>
    )
  }

  return (
    <div className={styles.coverInline}>
      <img
        className={styles.coverPreviewSmall}
        src={resolvedUrl}
        alt={`${slotLabel(kind)} von Jellyfin für ${animeTitle}`}
      />
      <p className={styles.hint}>Jellyfin-Quelle für {animeTitle}</p>
    </div>
  )
}

export function JellyfinDraftAssets({ animeTitle, assetSlots, onRemoveAsset }: JellyfinDraftAssetsProps) {
  const singleKinds: Array<Exclude<JellyfinDraftAssetTarget['kind'], 'background'>> = ['cover', 'logo', 'banner', 'background_video']

  return (
    <section className={styles.panel}>
      <h2>Jellyfin-Medien im Entwurf</h2>
      <p className={styles.hint}>
        Diese Vorschau bleibt unverbindlich. Erst die zentrale Save-Bar legt wirklich einen Anime an.
      </p>
      <div className={styles.gridTwo}>
        {singleKinds.map((kind) => {
          const slot = assetSlots[kind]
          return (
            <div key={kind} className={styles.details}>
              <strong>{slotLabel(kind)}</strong>
              {slot.present ? renderAssetPreview(animeTitle, kind, slot.url) : <p className={styles.hint}>{missingSlotLabel(kind)}</p>}
              <div className={styles.actions}>
                <button
                  className={`${styles.buttonSecondary} ${styles.buttonDanger}`}
                  type="button"
                  disabled={!slot.present}
                  onClick={() => onRemoveAsset({ kind })}
                >
                  Aus Entwurf entfernen
                </button>
              </div>
            </div>
          )
        })}
        <div className={styles.details}>
          <strong>Backgrounds</strong>
          {assetSlots.backgrounds.length > 0 ? (
            <div className={styles.gridTwo}>
              {assetSlots.backgrounds.map((slot, index) => (
                <div key={`${slot.kind}-${slot.url}`} className={styles.details}>
                  {renderAssetPreview(animeTitle, 'background', slot.url)}
                  <p className={styles.hint}>Background {index + 1}</p>
                  <div className={styles.actions}>
                    <button
                      className={`${styles.buttonSecondary} ${styles.buttonDanger}`}
                      type="button"
                      onClick={() => onRemoveAsset({ kind: 'background', index })}
                    >
                      Bild aus Entwurf entfernen
                    </button>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p className={styles.hint}>Keine Jellyfin-Backgrounds gefunden</p>
          )}
        </div>
      </div>
    </section>
  )
}

