export type AssetSource =
  | "Jellyfin"
  | "Manuell"
  | "Online"
  | "TMDB"
  | "Zerochan"
  | "Fanart.tv"
  | "AniList"
  | "Konachan"
  | "Safebooru";

export type CreateAssetCardVariant =
  | "cover"
  | "banner"
  | "logo"
  | "background"
  | "backgroundVideo"
  | "adder";

interface CreateAssetCardProps {
  label: string;
  previewUrl?: string | null;
  source?: AssetSource | null;
  variant?: CreateAssetCardVariant;
  isEmpty?: boolean;
  isRequired?: boolean;
  statusNote?: string;
  actions?: ReactNode;
  onEmptyClick?: () => void;
}

export function CreateAssetCard({
  label,
  previewUrl,
  source,
  variant = "cover",
  isEmpty,
  isRequired,
  statusNote,
  actions,
  onEmptyClick,
}: CreateAssetCardProps) {
  const sourceModifierClass: string = (() => {
    if (!source) return "";
    const map: Record<AssetSource, string> = {
      Jellyfin: createStyles.assetCardSourceOverlayJellyfin,
      TMDB: createStyles.assetCardSourceOverlayTMDB,
      Zerochan: createStyles.assetCardSourceOverlayZerochan,
      "Fanart.tv": createStyles.assetCardSourceOverlayFanart,
      AniList: createStyles.assetCardSourceOverlayAniList,
      Konachan: createStyles.assetCardSourceOverlayKonachan,
      Safebooru: createStyles.assetCardSourceOverlaySafebooru,
      Manuell: createStyles.assetCardSourceOverlayManuell,
      Online: createStyles.assetCardSourceOverlayOnline,
    };
    return map[source] ?? "";
  })();

  const cardVariantClass: string = (() => {
    const map: Record<CreateAssetCardVariant, string> = {
      cover: createStyles.assetCardCover,
      banner: createStyles.assetCardBanner,
      logo: createStyles.assetCardLogo,
      background: createStyles.assetCardBackground,
      backgroundVideo: createStyles.assetCardBackgroundVideo,
      adder: createStyles.assetCardAdder,
    };
    return map[variant] ?? createStyles.assetCardCover;
  })();

  const previewVariantClass: string = (() => {
    const map: Record<CreateAssetCardVariant, string> = {
      cover: createStyles.assetCardPreviewCover,
      banner: createStyles.assetCardPreviewBanner,
      logo: createStyles.assetCardPreviewLogo,
      background: createStyles.assetCardPreviewBackground,
      backgroundVideo: createStyles.assetCardPreviewBackgroundVideo,
      adder: createStyles.assetCardPreviewAdder,
    };
    return map[variant] ?? createStyles.assetCardPreviewCover;
  })();

  const imageVariantClass: string = (() => {
    const map: Record<CreateAssetCardVariant, string> = {
      cover: createStyles.assetCardImageCover,
      banner: createStyles.assetCardImageBanner,
      logo: createStyles.assetCardImageLogo,
      background: createStyles.assetCardImageBackground,
      backgroundVideo: createStyles.assetCardImageBackgroundVideo,
      adder: createStyles.assetCardImageCover,
    };
    return map[variant] ?? createStyles.assetCardImageCover;
  })();

  const emptyClass =
    variant === "adder" ? createStyles.assetCardEmptyAdder : createStyles.assetCardEmptyStandard;

  return (
    <div className={[createStyles.assetCard, cardVariantClass].join(" ")}>
      <div className={createStyles.assetCardHeader}>
        <span className={createStyles.assetCardLabel}>
          {label}
          {isRequired ? <span className={createStyles.assetCardRequired}> *</span> : null}
        </span>
        {source ? (
          <span
            className={[createStyles.assetCardSourcePill, sourceModifierClass]
              .filter(Boolean)
              .join(" ")}
          >
            {source}
          </span>
        ) : null}
      </div>
      <div className={[createStyles.assetCardPreview, previewVariantClass].join(" ")}>
        {previewUrl && variant === "backgroundVideo" ? (
          <video
            src={previewUrl}
            className={[createStyles.assetCardImage, imageVariantClass].join(" ")}
            muted
            playsInline
            preload="metadata"
          />
        ) : previewUrl ? (
          <img
            src={previewUrl}
            alt={label}
            className={[createStyles.assetCardImage, imageVariantClass].join(" ")}
          />
        ) : onEmptyClick ? (
          <div
            className={[createStyles.assetCardEmpty, createStyles.assetCardEmptyClickable].join(" ")}
            onClick={onEmptyClick}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onEmptyClick();
              }
            }}
          >
            <span>{isEmpty ? (isRequired ? "Cover fehlt" : "Noch nichts ausgewählt") : "–"}</span>
            <Upload size={20} className={createStyles.assetCardEmptyUploadIcon} />
          </div>
        ) : (
          <div className={[createStyles.assetCardEmpty, emptyClass].join(" ")}>
            <span>
              {variant === "adder"
                ? "+ Neuer Hintergrund"
                : isEmpty
                  ? isRequired
                    ? "Cover fehlt"
                    : "Noch nichts ausgewählt"
                  : "-"}
            </span>
          </div>
        )}
        {actions ? (
          <div className={createStyles.assetCardActions}>{actions}</div>
        ) : null}
        {source ? (
          <span
            className={[createStyles.assetCardImageSource, sourceModifierClass]
              .filter(Boolean)
              .join(" ")}
          >
            {source}
          </span>
        ) : null}
      </div>
      {statusNote ? (
        <div className={createStyles.assetCardFooter}>
          <span className={createStyles.assetStatusNote}>{statusNote}</span>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import Image from "next/image";

import styles from "../../admin.module.css";
import createStyles from "./page.module.css";
import type {
  AdminAnimeAssetKind,
  AdminAnimeAssetSearchCandidate,
} from "@/types/admin";

/**
 * Eingeschraenkte Asset-Arten, für die eine Online-Suche unterstützt wird.
 * Schliesst background_video aus, das nicht durchsucht werden kann.
 */
type SearchableAssetKind = Extract<
  AdminAnimeAssetKind,
  "cover" | "banner" | "logo" | "background"
>;

/**
 * Props des CreateAssetSearchDialog. Steuert Suchzustand, Kandidatenliste,
 * Auswahlstatus und Aktionen für den Asset-Suchdialog auf der Erstellen-Seite.
 */
interface CreateAssetSearchDialogProps {
  activeKind: SearchableAssetKind | null;
  query: string;
  candidates: AdminAnimeAssetSearchCandidate[];
  selectedCandidateIDs: string[];
  errorMessage: string | null;
  hasMore: boolean;
  isOpen: boolean;
  isSearching: boolean;
  isAdopting: boolean;
  onClose: () => void;
  onQueryChange: (value: string) => void;
  onSearch: () => void;
  onLoadMore: () => void;
  onToggleCandidate: (candidateID: string) => void;
  onAdoptSelection: () => void;
}

/**
 * Gibt Ueberschrift, Hilfetext und Button-Beschriftung für den jeweiligen
 * Asset-Typ zurück. Erleichtert das kontextgenaue Beschriften des Dialogs.
 */
function getAssetCopy(kind: SearchableAssetKind | null) {
  switch (kind) {
    case "cover":
      return {
        title: "Cover online suchen",
        helper: "Wähle ein Cover aus und uebernimm es in den Entwurf.",
        action: "Cover übernehmen",
      };
    case "banner":
      return {
        title: "Banner online suchen",
        helper: "Wähle ein Banner aus und uebernimm es in den Entwurf.",
        action: "Banner übernehmen",
      };
    case "logo":
      return {
        title: "Logo online suchen",
        helper: "Wähle ein Logo aus und uebernimm es in den Entwurf.",
        action: "Logo übernehmen",
      };
    case "background":
      return {
        title: "Backgrounds online suchen",
        helper: "Du kannst mehrere Backgrounds markieren und gesammelt übernehmen.",
        action: "Auswahl übernehmen",
      };
    default:
      return {
        title: "Assets online suchen",
        helper: "Suche nach passenden Assets und uebernimm sie in den Entwurf.",
        action: "Auswahl übernehmen",
      };
  }
}

/**
 * Rendert den modalen Asset-Suchdialog auf der Anime-Erstellen-Seite. Erlaubt
 * die Suche nach Cover-, Banner-, Logo- oder Hintergrundbildern aus externen
 * Quellen. Mehrfachauswahl ist nur für Hintergrundbilder erlaubt.
 * Geschlossen wird der Dialog, wenn kein aktiver Asset-Typ gesetzt ist.
 */
export function CreateAssetSearchDialog({
  activeKind,
  query,
  candidates,
  selectedCandidateIDs,
  errorMessage,
  hasMore,
  isOpen,
  isSearching,
  isAdopting,
  onClose,
  onQueryChange,
  onSearch,
  onLoadMore,
  onToggleCandidate,
  onAdoptSelection,
}: CreateAssetSearchDialogProps) {
  if (!isOpen || !activeKind) {
    return null;
  }

  const copy = getAssetCopy(activeKind);
  const selectedCount = selectedCandidateIDs.length;
  const canAdopt = selectedCount > 0 && !isAdopting;
  const candidateGridClass = [
    createStyles.assetCandidateGrid,
    activeKind === "cover" ? createStyles.assetCandidateGridCover : "",
  ]
    .filter(Boolean)
    .join(" ");
  const candidatePreviewClass = [
    createStyles.assetCandidatePreview,
    activeKind === "cover" ? createStyles.assetCandidatePreviewCover : "",
    activeKind === "logo" ? createStyles.assetCandidatePreviewLogo : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div
      className={createStyles.candidateModalBackdrop}
      role="presentation"
      onClick={onClose}
    >
      <div
        className={`${createStyles.candidateModal} ${createStyles.assetModal}`}
        role="dialog"
        aria-modal="true"
        aria-labelledby="create-asset-search-title"
        onClick={(event) => event.stopPropagation()}
      >
        <div className={createStyles.candidateModalHeader}>
          <div>
            <h3
              id="create-asset-search-title"
              className={createStyles.candidateModalTitle}
            >
              {copy.title}
            </h3>
            <p className={createStyles.candidateModalText}>{copy.helper}</p>
          </div>
          <button
            type="button"
            className={createStyles.secondaryAction}
            onClick={onClose}
          >
            Schließen
          </button>
        </div>

        <div className={styles.inputRow}>
          <label className={styles.field}>
            <span>Suchbegriff</span>
            <input
              value={query}
              placeholder="z. B. Ao Haru Ride"
              onChange={(event) => onQueryChange(event.target.value)}
            />
          </label>
          <button
            type="button"
            className={createStyles.primaryAction}
            aria-busy={isSearching}
            disabled={isSearching || !query.trim()}
            onClick={onSearch}
          >
            {isSearching ? "Suche laeuft..." : "Assets suchen"}
          </button>
        </div>

        <div className={createStyles.assetSearchToolbar}>
          <p className={createStyles.assetSearchStatus} aria-live="polite">
            {isSearching
              ? "Treffer werden geladen..."
              : selectedCount > 0
                ? `${selectedCount} Treffer ausgewählt`
                : candidates.length > 0
                  ? `${candidates.length} Treffer geladen`
                  : "Noch nichts ausgewählt"}
          </p>
          <button
            type="button"
            className={createStyles.secondaryAction}
            disabled={!canAdopt}
            onClick={onAdoptSelection}
          >
            {isAdopting ? "Uebernahme laeuft..." : copy.action}
          </button>
        </div>

        {errorMessage ? <div className={styles.errorBox}>{errorMessage}</div> : null}

        {candidates.length > 0 ? (
          <>
            <div className={candidateGridClass}>
              {candidates.map((candidate) => {
                const isSelected = selectedCandidateIDs.includes(candidate.id);
                return (
                  <button
                    key={candidate.id}
                    type="button"
                    className={`${createStyles.assetCandidateCard} ${
                      isSelected ? createStyles.assetCandidateCardSelected : ""
                    }`}
                    onClick={() => onToggleCandidate(candidate.id)}
                  >
                    <div className={candidatePreviewClass}>
                      <Image
                        src={candidate.preview_url}
                        alt={candidate.title || `${candidate.source} Asset`}
                        fill
                        sizes="(max-width: 720px) 50vw, 220px"
                        className={createStyles.assetCandidateImage}
                        unoptimized
                      />
                      <span className={createStyles.assetSourceBadge}>
                        {candidate.source}
                      </span>
                      {isSelected ? (
                        <span className={createStyles.assetCandidateSelectedBadge}>
                          Ausgewählt
                        </span>
                      ) : null}
                    </div>
                    <div className={createStyles.assetCandidateBody}>
                      {candidate.title ? (
                        <strong className={createStyles.assetCandidateTitle}>
                          {candidate.title}
                        </strong>
                      ) : null}
                      <p className={createStyles.assetMetaText}>
                        {candidate.width && candidate.height
                          ? `${candidate.width} x ${candidate.height}`
                          : "Groesse unbekannt"}
                        {candidate.year ? ` | ${candidate.year}` : ""}
                      </p>
                    </div>
                  </button>
                );
              })}
            </div>

            {hasMore ? (
              <div className={createStyles.assetLoadMoreRow}>
                <button
                  type="button"
                  className={createStyles.secondaryAction}
                  aria-busy={isSearching}
                  disabled={isSearching}
                  onClick={onLoadMore}
                >
                  {isSearching ? "Laden..." : "Mehr laden"}
                </button>
              </div>
            ) : null}
          </>
        ) : (
          <div className={styles.details}>
            <p className={styles.hint}>
              Noch keine Treffer geladen. Starte eine Suche, um passende Assets zu
              sehen.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import createStyles from "./page.module.css";
import styles from "../../admin.module.css";
import { JellyfinCandidateCard } from "../components/JellyfinIntake/JellyfinCandidateCard";
import type { AdminJellyfinIntakeSearchItem } from "@/types/admin";

interface CreateJellyfinCardProps {
  query: string;
  candidates: AdminJellyfinIntakeSearchItem[];
  currentAnimeID?: number;
  selectedCandidateID: string | undefined;
  hasAdoptedAssets: boolean;
  isSearching: boolean;
  isLoadingPreview: boolean;
  canSearch: boolean;
  isSubmitting: boolean;
  showResults: boolean;
  onQueryChange: (value: string) => void;
  onSearch: () => void;
  onSelectCandidate: (id: string) => void;
  onAdoptCandidate: (id: string) => void;
  onDiscard: () => void;
}

export function CreateJellyfinCard({
  query,
  candidates,
  currentAnimeID,
  selectedCandidateID,
  hasAdoptedAssets,
  isSearching,
  isLoadingPreview,
  canSearch,
  isSubmitting,
  showResults,
  onQueryChange,
  onSearch,
  onSelectCandidate,
  onAdoptCandidate,
  onDiscard,
}: CreateJellyfinCardProps) {
  const selectedCandidate = selectedCandidateID
    ? candidates.find((candidate) => candidate.jellyfin_series_id === selectedCandidateID)
    : null;

  return (
    <section className={createStyles.providerCard}>
      <div className={createStyles.providerCardHeader}>
        <p className={createStyles.resultsEyebrow}>Jellyfin</p>
        <h2 className={createStyles.resultsTitle}>Jellyfin</h2>
        <p className={createStyles.resultsText}>
          Dateiordner und passende Quelle für Cover, Banner, Logo und Hintergruende
        </p>
      </div>

      <div className={createStyles.providerInputRow}>
        <label className={[styles.field, createStyles.providerFieldGrow].join(" ")}>
          <span>Suche</span>
          <input
            value={query}
            placeholder="z. B. Bleach"
            onChange={(e) => onQueryChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && canSearch && !isSearching) onSearch();
            }}
          />
        </label>
        <button
          className={createStyles.primaryAction}
          type="button"
          disabled={!canSearch || isSearching || isSubmitting}
          onClick={onSearch}
        >
          {isSearching ? "Sucht..." : "Scannen"}
        </button>
      </div>

      {hasAdoptedAssets ? (
        <div className={createStyles.jellyfinSourceNotice}>
          <p className={createStyles.jellyfinSourceText}>
            <strong>{selectedCandidate?.name || "Jellyfin-Ordner"}</strong> ist jetzt
            als Quelle gesetzt. Die übernommenen Assets bearbeitest du direkt im
            Asset-Bereich.
          </p>
          <button
            className={`${styles.buttonSecondary} ${styles.buttonDanger}`}
            type="button"
            onClick={onDiscard}
          >
            Auswahl verwerfen
          </button>
        </div>
      ) : showResults && candidates.length > 0 ? (
        <div className={createStyles.providerResultsBlock}>
          <div className={createStyles.providerResultsHeader}>
            <p className={createStyles.resultsEyebrow}>Gefundene Ordner</p>
            <strong className={createStyles.providerResultsCount}>
              {candidates.length} Treffer
            </strong>
          </div>
          <div className={createStyles.providerList}>
            {candidates.map((candidate) => (
              <JellyfinCandidateCard
                key={candidate.jellyfin_series_id}
                candidate={candidate}
                currentAnimeID={currentAnimeID}
                isSelected={candidate.jellyfin_series_id === selectedCandidateID}
                isLoadingPreview={
                  isLoadingPreview && candidate.jellyfin_series_id === selectedCandidateID
                }
                isAdopted={hasAdoptedAssets && candidate.jellyfin_series_id === selectedCandidateID}
                onSelect={onSelectCandidate}
                onAdopt={onAdoptCandidate}
              />
            ))}
          </div>
        </div>
      ) : null}

      {!hasAdoptedAssets && showResults && candidates.length === 0 && !isSearching ? (
        <p className={createStyles.resultsText}>
          Keine Ordner gefunden. Pruefe die Schreibweise.
        </p>
      ) : null}
    </section>
  );
}

