      queueMicrotask(() => setProjectTimeline(null));
      return;
    }

    let cancelled = false;
    void getAnimeFansubProjectTimeline(fansubId, animeId)
      .then((timeline) => {
        if (!cancelled) setProjectTimeline(timeline);
      })
      .catch(() => {
