import { useEffect, useState } from 'react'

import {
  CATEGORY_ALLOWS_PREVIEW,
  CATEGORY_LABELS,
  ReleaseVersionMediaItem,
  ReleaseVersionMediaPatchRequest,
} from '@/types/releaseVersionMedia'
import { FormField } from '@/components/ui/FormField'
import { Textarea } from '@/components/ui/Textarea'

import styles from './ReleaseVersionMediaSection.module.css'

interface ReleaseVersionMediaDetailPanelProps {
  item: ReleaseVersionMediaItem
  versionId: number
  onClose: () => void
  onPatch: (mediaId: number, patch: ReleaseVersionMediaPatchRequest) => Promise<void>
  onDelete: (mediaId: number) => Promise<void>
  canEdit: boolean
  canDelete: boolean
}

function readError(error: unknown, fallback: string): string {
  if (error instanceof Error) {
    return error.message
  }
  return fallback
}

export function ReleaseVersionMediaDetailPanel({
  item,
  versionId: _versionId,
  onClose,
  onPatch,
  onDelete,
  canEdit,
  canDelete,
}: ReleaseVersionMediaDetailPanelProps) {
  const [caption, setCaption] = useState(item.caption ?? '')
  const [localError, setLocalError] = useState<string | null>(null)
  const [isSaving, setIsSaving] = useState(false)
  const [isDeleting, setIsDeleting] = useState(false)
  const captionFieldId = `release-media-caption-${item.id}`

  useEffect(() => {
    setCaption(item.caption ?? '')
    setLocalError(null)
  }, [item])

  async function saveCaption() {
    setLocalError(null)
    setIsSaving(true)
    try {
      await onPatch(item.id, { caption: caption.trim() || null })
    } catch (error) {
      setLocalError(readError(error, 'Beschreibung konnte nicht gespeichert werden.'))
    } finally {
      setIsSaving(false)
    }
  }

  async function togglePreview(nextValue: boolean) {
    setLocalError(null)
    setIsSaving(true)
    try {
      await onPatch(item.id, { is_preview_candidate: nextValue })
    } catch (error) {
      setLocalError(readError(error, 'Preview-Status konnte nicht gespeichert werden.'))
    } finally {
      setIsSaving(false)
    }
  }

  async function handleDelete() {
    if (!window.confirm('Dieses Medium wirklich entfernen?')) {
      return
    }

    setLocalError(null)
    setIsDeleting(true)
    try {
      await onDelete(item.id)
      onClose()
    } catch (error) {
      setLocalError(readError(error, 'Medium konnte nicht gelöscht werden.'))
    } finally {
      setIsDeleting(false)
    }
  }

  return (
    <aside className={styles.detailPanel}>
      <div className={styles.detailHeader}>
        <div>
          <h3 className={styles.detailTitle}>Medium bearbeiten</h3>
          <p className={styles.helper}>Kategorie: {CATEGORY_LABELS[item.category]}</p>
        </div>
        <button type="button" className={styles.buttonSecondary} onClick={onClose}>
          Schließen
        </button>
      </div>

      <div className={styles.detailPreview}>
        {item.original_url || item.thumbnail_url ? (
          <img
            className={styles.detailPreviewImage}
            src={item.original_url || item.thumbnail_url || ''}
            alt={item.caption || `Asset ${item.id}`}
          />
        ) : (
          <span className={styles.placeholder}>Kein Bild verfügbar</span>
        )}
      </div>

      <FormField label="Beschreibung" htmlFor={captionFieldId}>
        <Textarea
          id={captionFieldId}
          value={caption}
          onChange={(event) => setCaption(event.target.value)}
          disabled={!canEdit}
        />
      </FormField>
      <div className={styles.buttonRow}>
        <button
          type="button"
          className={`${styles.buttonPrimary} ${styles.buttonSuccess}`}
          onClick={() => void saveCaption()}
          disabled={!canEdit || isSaving || isDeleting}
        >
          Beschreibung speichern
        </button>
      </div>

      {CATEGORY_ALLOWS_PREVIEW[item.category] ? (
        <label className={styles.checkboxRow}>
          <input
            type="checkbox"
            checked={item.is_preview_candidate}
            disabled={!canEdit || isSaving || isDeleting}
            onChange={(event) => void togglePreview(event.target.checked)}
          />
          <span>Als Preview aktiv</span>
        </label>
      ) : null}

      {localError ? <div className={styles.errorBox}>{localError}</div> : null}

      <div className={styles.buttonRow}>
        <button
          type="button"
          className={styles.buttonSecondary}
          onClick={() => void handleDelete()}
          disabled={!canDelete || isSaving || isDeleting}
        >
          {isDeleting ? 'Löschen...' : 'Medium löschen'}
        </button>
      </div>
    </aside>
  )
}

'use client'

import { useRef, useState } from 'react'

import {
  CATEGORY_LABELS,
  RELEASE_VERSION_MEDIA_CATEGORIES,
  ReleaseVersionMediaCategory,
  ReleaseVersionMediaItem,
  ReleaseVersionMediaReorderRequest,
} from '@/types/releaseVersionMedia'

import styles from './ReleaseVersionMediaGallery.module.css'

interface ReleaseVersionMediaGalleryProps {
  items: ReleaseVersionMediaItem[]
  selectedItemId: number | null
  onSelectItem: (item: ReleaseVersionMediaItem) => void
  versionId: number
  onReorder?: (versionId: number, body: ReleaseVersionMediaReorderRequest) => Promise<void>
  canReorder?: boolean
}

function cardLabel(item: ReleaseVersionMediaItem): string {
  return item.caption?.trim() || `Asset #${item.id}`
}

function isGif(item: ReleaseVersionMediaItem): boolean {
  return (
    item.original_url?.toLowerCase().endsWith('.gif') === true ||
    (item as unknown as { mime_type?: string }).mime_type === 'image/gif'
  )
}

interface DragState {
  draggedId: number | null
  draggedCategory: ReleaseVersionMediaCategory | null
  overCategory: ReleaseVersionMediaCategory | null
}

const INITIAL_DRAG_STATE: DragState = {
  draggedId: null,
  draggedCategory: null,
  overCategory: null,
}

interface HoverPreviewState {
  item: ReleaseVersionMediaItem | null
}

export function ReleaseVersionMediaGallery({
  items,
  selectedItemId,
  onSelectItem,
  versionId,
  onReorder,
  canReorder = true,
}: ReleaseVersionMediaGalleryProps) {
  const [dragState, setDragState] = useState<DragState>(INITIAL_DRAG_STATE)
  const [dragOverItemId, setDragOverItemId] = useState<number | null>(null)
  const [hoveredItem, setHoveredItem] = useState<HoverPreviewState>({ item: null })
  const [gifHoveredIds, setGifHoveredIds] = useState<Set<number>>(new Set())
  const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  function handleMouseEnter(item: ReleaseVersionMediaItem) {
    if (hoverTimeoutRef.current) {
      clearTimeout(hoverTimeoutRef.current)
      hoverTimeoutRef.current = null
    }
    hoverTimeoutRef.current = setTimeout(() => {
      setHoveredItem({ item })
      if (isGif(item)) {
        setGifHoveredIds((prev) => {
          const next = new Set(prev)
          next.add(item.id)
          return next
        })
      }
    }, 200)
  }

  function handleMouseLeave(item: ReleaseVersionMediaItem) {
    if (hoverTimeoutRef.current) {
      clearTimeout(hoverTimeoutRef.current)
      hoverTimeoutRef.current = null
    }
    setHoveredItem({ item: null })
    if (isGif(item)) {
      setGifHoveredIds((prev) => {
        const next = new Set(prev)
        next.delete(item.id)
        return next
      })
    }
  }

  function handleDragStart(item: ReleaseVersionMediaItem) {
    setDragState({
      draggedId: item.id,
      draggedCategory: item.category,
      overCategory: null,
    })
  }

  function handleDragOver(item: ReleaseVersionMediaItem) {
    setDragOverItemId(item.id)
    setDragState((prev) => ({ ...prev, overCategory: item.category }))
  }

  function handleDrop(targetItem: ReleaseVersionMediaItem) {
    const { draggedId, draggedCategory } = dragState

    // Reset drag state immediately
    setDragState(INITIAL_DRAG_STATE)
    setDragOverItemId(null)

    if (draggedId == null || draggedId === targetItem.id) {
      return
    }

    // Cross-category drag is blocked
    if (draggedCategory !== targetItem.category) {
      return
    }

    if (!onReorder) {
      return
    }

    // Compute new order within the category
    const categoryItems = items
      .filter((i) => i.category === draggedCategory)
      .sort((a, b) => a.sort_order - b.sort_order)

    const draggedIndex = categoryItems.findIndex((i) => i.id === draggedId)
    const targetIndex = categoryItems.findIndex((i) => i.id === targetItem.id)

    if (draggedIndex === -1 || targetIndex === -1) {
      return
    }

    // Build reordered array
    const reordered = [...categoryItems]
    const [removed] = reordered.splice(draggedIndex, 1)
    reordered.splice(targetIndex, 0, removed)

    // Assign new sort_order values (gap of 10 to match backend convention)
    const reorderItems = reordered.map((item, index) => ({
      id: item.id,
      sort_order: (index + 1) * 10,
    }))

    onReorder(versionId, { items: reorderItems }).catch(() => {
      // Errors surface through the hook's error state; no local handling needed
    })
  }

  function handleDragEnd() {
    setDragState(INITIAL_DRAG_STATE)
    setDragOverItemId(null)
  }

  const previewItem = hoveredItem.item

  return (
    <div className={styles.gallery}>
      {RELEASE_VERSION_MEDIA_CATEGORIES.map((category) => {
        const categoryItems = items
          .filter((item) => item.category === category)
          .sort((a, b) => a.sort_order - b.sort_order)

        return (
          <section key={category} className={styles.section}>
            <div className={styles.headingRow}>
              <h3 className={styles.heading}>{CATEGORY_LABELS[category]}</h3>
              <span className={styles.count}>{categoryItems.length} Medien</span>
            </div>

            {categoryItems.length === 0 ? (
              <p className={styles.emptySection}>Noch keine Medien in dieser Kategorie.</p>
            ) : (
              <div className={styles.cardGrid}>
                {categoryItems.map((item) => {
                  const isDragging = dragState.draggedId === item.id
                  const isDropTarget =
                    dragOverItemId === item.id &&
                    dragState.draggedId !== null &&
                    dragState.draggedId !== item.id &&
                    dragState.draggedCategory === item.category
                  const isGifHovered = gifHoveredIds.has(item.id)

                  return (
                    <div
                      key={item.id}
                      draggable={canReorder}
                      className={[
                        styles.cardWrapper,
                        isDragging ? styles.cardDragging : '',
                        isDropTarget ? styles.cardDropTarget : '',
                      ]
                        .filter(Boolean)
                        .join(' ')}
                      onMouseEnter={() => handleMouseEnter(item)}
                      onMouseLeave={() => handleMouseLeave(item)}
                      onDragStart={() => handleDragStart(item)}
                      onDragOver={(event) => {
                        event.preventDefault()
                        handleDragOver(item)
                      }}
                      onDrop={(event) => {
                        event.preventDefault()
                        handleDrop(item)
                      }}
                      onDragEnd={handleDragEnd}
                    >
                      <button
                        type="button"
                        draggable={canReorder}
                        className={[
                          styles.card,
                          selectedItemId === item.id ? styles.cardActive : '',
                        ]
                          .filter(Boolean)
                          .join(' ')}
                        onClick={() => onSelectItem(item)}
                        onMouseEnter={() => handleMouseEnter(item)}
                        onMouseLeave={() => handleMouseLeave(item)}
                      >
                        <div className={styles.thumb}>
                          {(item.thumbnail_url || (isGifHovered && item.original_url)) ? (
                            <img
                              className={styles.thumbImage}
                              src={isGifHovered && item.original_url ? item.original_url : (item.thumbnail_url ?? '')}
                              alt={cardLabel(item)}
                            />
                          ) : (
                            <span className={styles.placeholder}>Kein Thumbnail</span>
                          )}
                        </div>
                        <div className={styles.caption}>{cardLabel(item)}</div>
                        <div className={styles.metaRow}>
                          {item.is_preview_candidate ? (
                            <span className={styles.previewBadge}>Preview</span>
                          ) : (
                            <span />
                          )}
                          {item.original_url ? (
                            <a
                              className={styles.openLink}
                              href={item.original_url}
                              target="_blank"
                              rel="noreferrer"
                              onClick={(event) => event.stopPropagation()}
                            >
                              Öffnen
                            </a>
                          ) : null}
                        </div>
                      </button>

                      {previewItem?.id === item.id && (
                        <div
                          role="tooltip"
                          className={styles.hoverPreview}
                          aria-label={`Vorschau: ${cardLabel(item)}`}
                        >
                          <div className={styles.hoverPreviewImageWrapper}>
                            {(item.thumbnail_url || item.original_url) ? (
                              <img
                                className={styles.hoverPreviewImage}
                                src={
                                  isGifHovered && item.original_url
                                    ? item.original_url
                                    : (item.thumbnail_url ?? item.original_url ?? '')
                                }
                                alt={cardLabel(item)}
                              />
                            ) : (
                              <span className={styles.placeholder}>Kein Bild</span>
                            )}
                          </div>
                          <div className={styles.hoverPreviewCaption}>{cardLabel(item)}</div>
                        </div>
                      )}
                    </div>
                  )
                })}
              </div>
            )}
          </section>
        )
      })}
    </div>
  )
}

