import { useEffect, useState } from "react";

import { getGroupedEpisodes } from "@/lib/api";

import {
  computeNeighborNavigation,
  type NeighborNavigationResult,
} from "./episodeNeighborNavigation";

export interface UseEpisodeNeighborNavigationParams {
  animeId: number | null;
  currentVersionId: number | null;
  groupId: number | null;
  releaseVersion: string;
}

export interface UseEpisodeNeighborNavigationResult
  extends NeighborNavigationResult {
  isLoading: boolean;
  error: string | null;
}

const EMPTY_TARGETS: NeighborNavigationResult = {
  currentIndex: -1,
  totalCount: 0,
  prevVersionId: null,
  prevEpisodeNumber: null,
  nextVersionId: null,
  nextEpisodeNumber: null,
};

export function useEpisodeNeighborNavigation(
  params: UseEpisodeNeighborNavigationParams,
): UseEpisodeNeighborNavigationResult {
  const { animeId, currentVersionId, groupId, releaseVersion } = params;

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [navigation, setNavigation] =
    useState<NeighborNavigationResult>(EMPTY_TARGETS);

  useEffect(() => {
    if (animeId == null || currentVersionId == null) {
      setIsLoading(false);
      setError(null);
      setNavigation(EMPTY_TARGETS);
      return;
    }

    let cancelled = false;
    setIsLoading(true);
    setError(null);

    void getGroupedEpisodes(animeId)
      .then((response) => {
        if (cancelled) return;
        const result = computeNeighborNavigation({
          episodes: response.data.episodes,
          currentVersionId,
          groupId,
          releaseVersion,
        });
        setNavigation(result);
        setError(null);
      })
      .catch((caughtError: unknown) => {
        if (cancelled) return;
        const message =
          caughtError instanceof Error
            ? caughtError.message
            : "Nachbar-Folgen konnten nicht geladen werden.";
        setError(message);
        setNavigation(EMPTY_TARGETS);
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [animeId, currentVersionId, groupId, releaseVersion]);

  return {
    isLoading,
    error,
    ...navigation,
  };
}

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { ApiError, getReleaseVersionCapabilities, deleteReleaseVersionMediaItem, getReleaseVersionMedia, patchReleaseVersionMediaItem, replaceReleaseVersionMediaFile, reorderReleaseVersionMedia, uploadReleaseVersionMedia } from '@/lib/api'
import { CATEGORY_ALLOWS_PREVIEW, ReleaseVersionMediaCategory, ReleaseVersionCapabilities, ReleaseVersionMediaItem, ReleaseVersionMediaPatchRequest, ReleaseVersionMediaReorderRequest } from '@/types/releaseVersionMedia'
import { buildReplaceMediaFileRequest, fileKey } from './ReleaseVersionMediaSection.helpers'

export interface UploadFileDraft {
  file: File
  title: string
  caption: string
}

export interface UploadQueueItem {
  file: File
  status: 'idle' | 'uploading' | 'processing' | 'ready' | 'failed'
  progress: number
  errorMessage: string | null
  resultId: number | null
  title?: string
  caption?: string
  isPreviewCandidate?: boolean
  /** Kept with resultId so metadata retries never upload the binary again. */
  sourceRevision?: number
}

export interface UploadRunResult {
  items: UploadQueueItem[]
  allSucceeded: boolean
}

interface UploadConfig {
  category: ReleaseVersionMediaCategory
  versionId: number
}

export interface UseReleaseVersionMediaResult {
  items: ReleaseVersionMediaItem[]
  isLoading: boolean
  error: string | null
  reload: () => void
  uploadItems: UploadQueueItem[]
  startUpload: (category: ReleaseVersionMediaCategory, drafts: UploadFileDraft[], previewFileKey?: string | null) => Promise<UploadRunResult>
  retryUpload: (fileIndex: number) => Promise<UploadRunResult>
  clearUploadQueue: () => void
  patchItem: (mediaId: number, patch: ReleaseVersionMediaPatchRequest) => Promise<void>
  replaceItem: (mediaId: number, options: { file: File; category?: ReleaseVersionMediaCategory; title?: string | null; caption?: string | null; isPreviewCandidate?: boolean }) => Promise<void>
  deleteItem: (mediaId: number) => Promise<void>
  reorderItems: (versionId: number, body: ReleaseVersionMediaReorderRequest) => Promise<void>
  patchError: string | null
  replaceError: string | null
  deleteError: string | null
  reorderError: string | null
  capabilities?: ReleaseVersionCapabilities | null
  capabilitiesError?: string | null
}

function sortMediaItems(items: ReleaseVersionMediaItem[]): ReleaseVersionMediaItem[] {
  return [...items].sort((a, b) => a.sort_order - b.sort_order)
}

function applyReorderToItems(
  current: ReleaseVersionMediaItem[],
  body: ReleaseVersionMediaReorderRequest,
): ReleaseVersionMediaItem[] {
  const orderMap = new Map(body.items.map((item) => [item.id, item.sort_order]))

  return sortMediaItems(
    current.map((item) => {
      const nextSortOrder = orderMap.get(item.id)
      return nextSortOrder !== undefined ? { ...item, sort_order: nextSortOrder } : item
    }),
  )
}

function readUploadError(error: unknown, fallback: string): string {
  if (error instanceof ApiError) {
    return error.message
  }
  if (error instanceof Error) {
    return error.message
  }
  return fallback
}

export function useReleaseVersionMedia(versionId: number | null): UseReleaseVersionMediaResult {
  const [items, setItems] = useState<ReleaseVersionMediaItem[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [uploadItems, setUploadItems] = useState<UploadQueueItem[]>([])
  const [patchError, setPatchError] = useState<string | null>(null)
  const [replaceError, setReplaceError] = useState<string | null>(null)
  const [deleteError, setDeleteError] = useState<string | null>(null)
  const [reorderError, setReorderError] = useState<string | null>(null)
  const [capabilities, setCapabilities] = useState<ReleaseVersionCapabilities | null>(null)
  const [capabilitiesError, setCapabilitiesError] = useState<string | null>(null)
  const [reloadKey, setReloadKey] = useState(0)
  const lastUploadConfigRef = useRef<UploadConfig | null>(null)
  const itemsRef = useRef<ReleaseVersionMediaItem[]>([])

  useEffect(() => {
    itemsRef.current = items
  }, [items])

  const reload = useCallback(() => {
    setReloadKey((k) => k + 1)
  }, [])

  const patchUploadedItem = useCallback(
    async (queueItem: UploadQueueItem): Promise<UploadQueueItem> => {
      const patch: ReleaseVersionMediaPatchRequest = {}
      const title = queueItem.title?.trim()
      const caption = queueItem.caption?.trim()
      if (title) patch.title = title
      if (caption) patch.caption = caption
      // Unselected images must not clear an existing preview.
      if (queueItem.isPreviewCandidate) patch.is_preview_candidate = true

      try {
        let sourceRevision = queueItem.sourceRevision
        if (Object.keys(patch).length > 0 && versionId !== null && queueItem.resultId !== null) {
          if (sourceRevision != null) patch.source_revision = sourceRevision
          const updated = await patchReleaseVersionMediaItem(versionId, queueItem.resultId, patch)
          sourceRevision = updated.source_revision ?? sourceRevision
        }
        return { ...queueItem, status: 'ready', progress: 100, errorMessage: null, sourceRevision }
      } catch (patchError) {
        return {
          ...queueItem,
          status: 'failed',
          progress: 100,
          errorMessage: readUploadError(patchError, 'Metadaten konnten nach dem Upload nicht gesetzt werden.'),
        }
      }
    },
    [versionId],
  )

  const runUpload = useCallback(
    async (queueIndices: number[], queue: UploadQueueItem[], config: UploadConfig): Promise<UploadRunResult> => {
      if (versionId === null || queue.length === 0) {
        return { items: [], allSucceeded: true }
      }

      setError(null)
      setUploadItems((current) => current.map((item, index) => queueIndices.includes(index)
        ? { ...item, status: 'uploading', progress: 0, errorMessage: null }
        : item))

      try {
        const response = await uploadReleaseVersionMedia({
          versionId,
          category: config.category,
          files: queue.map(item => item.file),
          // The existing XHR reports progress for the whole multipart request.
          onProgress: (_fileIndex, percent) => {
            setUploadItems((current) => current.map((item, index) =>
              queueIndices.includes(index) && item.status === 'uploading'
                ? { ...item, progress: percent }
                : item))
          },
        })

        setUploadItems((current) => current.map((item, index) =>
          queueIndices.includes(index) && item.status === 'uploading'
            ? { ...item, status: 'processing', progress: 100 }
            : item))

        const outcomes: UploadQueueItem[] = []
        let shouldReload = false
        // Backend appends exactly one result per multipart input in input order,
        // including failures. Filenames are not unique and are never lookup keys.
        for (const [position, queueItem] of queue.entries()) {
          const result = response.results[position]
          const targetIndex = queueIndices[position]
          let outcome: UploadQueueItem
          if (result?.status === 'ready' && typeof result.release_version_media_id === 'number') {
            shouldReload = true
            const uploaded: UploadQueueItem = {
              ...queueItem, status: 'processing', progress: 100, errorMessage: null,
              resultId: result.release_version_media_id, sourceRevision: result.source_revision,
            }
            setUploadItems(current => current.map((item, index) => index === targetIndex ? uploaded : item))
            outcome = await patchUploadedItem(uploaded)
          } else {
            outcome = {
              ...queueItem, status: 'failed', progress: 100,
              errorMessage: result?.error_code || 'Upload fehlgeschlagen.', resultId: null,
            }
          }
          outcomes.push(outcome)
          setUploadItems(current => current.map((item, index) => index === targetIndex ? outcome : item))
        }
        if (shouldReload) reload()
        return { items: outcomes, allSucceeded: outcomes.every(item => item.status === 'ready') }
      } catch (uploadError) {
        const message = readUploadError(uploadError, 'Upload fehlgeschlagen.')
        setError(message)
        setUploadItems(current => current.map((item, index) => queueIndices.includes(index)
          ? { ...item, status: 'failed', errorMessage: message }
          : item))
        throw uploadError
      }
    },
    [patchUploadedItem, reload, versionId],
  )

  const startUpload = useCallback(
    async (
      category: ReleaseVersionMediaCategory,
      drafts: UploadFileDraft[],
      previewFileKey?: string | null,
    ): Promise<UploadRunResult> => {
      if (versionId === null || drafts.length === 0) return { items: [], allSucceeded: true }

      const config: UploadConfig = { category, versionId }
      lastUploadConfigRef.current = config
      const previewIndex = CATEGORY_ALLOWS_PREVIEW[category] && previewFileKey
        ? drafts.findIndex(draft => fileKey(draft.file) === previewFileKey)
        : -1
      const initialQueue = drafts.map<UploadQueueItem>((draft, index) => ({
        ...draft,
        isPreviewCandidate: index === previewIndex,
        status: 'idle', progress: 0, errorMessage: null, resultId: null,
      }))
      setUploadItems(initialQueue)
      return runUpload(initialQueue.map((_, index) => index), initialQueue, config)
    },
    [runUpload, versionId],
  )

  const retryUpload = useCallback(
    async (fileIndex: number): Promise<UploadRunResult> => {
      const config = lastUploadConfigRef.current
      const queueItem = uploadItems[fileIndex]
      if (!config || config.versionId !== versionId || !queueItem || queueItem.status !== 'failed') {
        return { items: [], allSucceeded: false }
      }
      if (queueItem.resultId === null) return runUpload([fileIndex], [queueItem], config)

      setError(null)
      setUploadItems(current => current.map((item, index) => index === fileIndex
        ? { ...item, status: 'processing', errorMessage: null }
        : item))
      const outcome = await patchUploadedItem(queueItem)
      setUploadItems(current => current.map((item, index) => index === fileIndex ? outcome : item))
      if (outcome.status === 'ready') reload()
      return { items: [outcome], allSucceeded: outcome.status === 'ready' }
    },
    [patchUploadedItem, reload, runUpload, uploadItems, versionId],
  )

  const clearUploadQueue = useCallback(() => {
    lastUploadConfigRef.current = null
    setUploadItems([])
  }, [])

  const patchItem = useCallback(
    async (mediaId: number, patch: ReleaseVersionMediaPatchRequest) => {
      if (versionId === null) {
        return
      }

      setPatchError(null)
      try {
        const currentItem = itemsRef.current.find((item) => item.id === mediaId)
        const revisionBoundPatch = currentItem?.source_revision != null
          ? { ...patch, source_revision: currentItem.source_revision }
          : patch
        const updated = await patchReleaseVersionMediaItem(versionId, mediaId, revisionBoundPatch)
        setItems((current) => {
          const next = current.map((item) => {
            if (item.id === mediaId) return updated
            if (patch.is_preview_candidate === true) return { ...item, is_preview_candidate: false }
            return item
          })
          // Re-sort immediately when sort_order was part of the patch so the
          // in-memory list reflects the new order without a full reload.
          if (patch.sort_order !== undefined) {
            return sortMediaItems(next)
          }
          return next
        })
      } catch (patchItemError) {
        const message = readUploadError(patchItemError, 'Änderung konnte nicht gespeichert werden.')
        setPatchError(message)
        throw patchItemError
      }
    },
    [versionId],
  )

  const replaceItem = useCallback(
    async (mediaId: number, options: { file: File; category?: ReleaseVersionMediaCategory; title?: string | null; caption?: string | null; isPreviewCandidate?: boolean }) => {
      if (versionId === null) return
      setReplaceError(null)
      try {
        const currentItem = itemsRef.current.find((item) => item.id === mediaId)
        const updated = await replaceReleaseVersionMediaFile(buildReplaceMediaFileRequest(versionId, mediaId, options, currentItem?.source_revision))
        setItems((current) => current.map((item) => (item.id === mediaId ? updated : options.isPreviewCandidate === true ? { ...item, is_preview_candidate: false } : item)))
      } catch (replaceItemError) {
        const message = readUploadError(replaceItemError, 'Datei konnte nicht ersetzt werden. Versuch es erneut oder wähle eine andere Datei.')
        setReplaceError(message)
        throw replaceItemError
      }
    },
    [versionId],
  )

  const reorderItems = useCallback(
    async (targetVersionId: number, body: ReleaseVersionMediaReorderRequest) => {
      const previousItems = itemsRef.current
      const optimisticItems = applyReorderToItems(previousItems, body)

      setReorderError(null)
      setItems(optimisticItems)

      try {
        await reorderReleaseVersionMedia(targetVersionId, body)
      } catch (reorderItemsError) {
        setItems(previousItems)
        setReorderError(
          readUploadError(reorderItemsError, 'Reihenfolge konnte nicht gespeichert werden.'),
        )
        throw reorderItemsError
      }
    },
    [],
  )

  const deleteItem = useCallback(
    async (mediaId: number) => {
      if (versionId === null) {
        return
      }

      setDeleteError(null)
      try {
        await deleteReleaseVersionMediaItem(versionId, mediaId)
        setItems((current) => current.filter((item) => item.id !== mediaId))
      } catch (deleteItemError) {
        const message = readUploadError(deleteItemError, 'Medium konnte nicht gelöscht werden.')
        setDeleteError(message)
        throw deleteItemError
      }
    },
    [versionId],
  )

  useEffect(() => {
    if (versionId === null) {
      setItems([])
      setError(null)
      setCapabilities(null)
      setCapabilitiesError(null)
      return
    }

    let cancelled = false
    setIsLoading(true)
    setError(null)
    setCapabilitiesError(null)

    Promise.all([
      getReleaseVersionMedia(versionId),
      getReleaseVersionCapabilities(versionId),
    ])
      .then(([response, capabilitiesResponse]) => {
        if (cancelled) return
        setItems(sortMediaItems(Array.isArray(response.data) ? response.data : []))
        setCapabilities(capabilitiesResponse.data)
      })
      .catch((err: unknown) => {
        if (cancelled) return
        const message = err instanceof Error ? err.message : String(err)
        setError(message)
        setCapabilitiesError(message)
      })
      .finally(() => {
        if (!cancelled) {
          setIsLoading(false)
        }
      })

    return () => {
      cancelled = true
    }
  }, [versionId, reloadKey])

  return {
    items,
    isLoading,
    error,
    reload,
    uploadItems,
    startUpload,
    retryUpload,
    clearUploadQueue,
    patchItem,
    replaceItem,
    deleteItem,
    reorderItems,
    patchError,
    replaceError,
    deleteError,
    reorderError,
    capabilities,
    capabilitiesError,
  }
}

"use client";

import Image from "next/image";
import Link from "next/link";
import { FormEvent, useEffect, useState } from "react";

import { AnimeListItem, AnimeStatus, EpisodeStatus } from "@/types/anime";
import {
  AdminEpisodeCreateRequest,
  AdminEpisodePatchRequest,
} from "@/types/admin";
import { PlatformAdminGate } from "@/components/auth/PlatformAdminGate";
import {
  ApiError,
  createAdminEpisode,
  getAnimeList,
  updateAdminEpisode,
} from "@/lib/api";
import { useAuthSession } from "@/lib/useAuthSession";
import { getCoverUrl } from "@/lib/utils";

import sharedStyles from "../admin.module.css";
import browserStyles from "../anime/components/AnimeBrowser/AnimeBrowser.module.css";

const styles = { ...sharedStyles, ...browserStyles };

const EPISODE_STATUSES: EpisodeStatus[] = ["disabled", "private", "public"];
const ANIME_SEARCH_PER_PAGE = 20;

function parsePositiveInt(value: string): number | null {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
}

function normalizeOptionalString(value: string): string | undefined {
  const trimmed = value.trim();
  return trimmed ? trimmed : undefined;
}

function resolveAnimeStatusClass(status: AnimeStatus): string {
  switch (status) {
    case "ongoing":
      return "statusOngoing";
    case "done":
      return "statusDone";
    case "aborted":
      return "statusAborted";
    case "licensed":
      return "statusLicensed";
    case "disabled":
    default:
      return "statusDisabled";
  }
}

function handleCoverImgError(event: React.SyntheticEvent<HTMLImageElement>) {
  const img = event.currentTarget;
  if (img.dataset.fallbackApplied === "true") return;
  img.dataset.fallbackApplied = "true";
  img.alt = "";
  img.src = "/covers/placeholder.jpg";
}

function AdminEpisodesContent() {
  const { hasAccessToken, isClientInitialized } = useAuthSession();
  const [isSubmittingCreate, setIsSubmittingCreate] = useState(false);
  const [isSubmittingUpdate, setIsSubmittingUpdate] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [lastRequest, setLastRequest] = useState<string | null>(null);
  const [lastResponse, setLastResponse] = useState<string | null>(null);

  const [createAnimeID, setCreateAnimeID] = useState("");
  const [createEpisodeNumber, setCreateEpisodeNumber] = useState("");
  const [createTitle, setCreateTitle] = useState("");
  const [createStatus, setCreateStatus] = useState<EpisodeStatus>("private");
  const [selectedAnime, setSelectedAnime] = useState<AnimeListItem | null>(
    null,
  );
  const [animeSearchInput, setAnimeSearchInput] = useState("");
  const [animeSearchQuery, setAnimeSearchQuery] = useState("");
  const [animeSearchResults, setAnimeSearchResults] = useState<AnimeListItem[]>(
    [],
  );
  const [animeSearchTotal, setAnimeSearchTotal] = useState(0);
  const [isSearchingAnime, setIsSearchingAnime] = useState(false);
  const [animeSearchError, setAnimeSearchError] = useState<string | null>(null);

  const [updateEpisodeID, setUpdateEpisodeID] = useState("");
  const [updateEpisodeNumber, setUpdateEpisodeNumber] = useState("");
  const [updateTitle, setUpdateTitle] = useState("");
  const [updateStatus, setUpdateStatus] = useState("");
  const [clearUpdateTitle, setClearUpdateTitle] = useState(false);

  const hasAuthToken = isClientInitialized && hasAccessToken;

  useEffect(() => {
    const id = parsePositiveInt(createAnimeID);
    if (!id) {
      if (selectedAnime) setSelectedAnime(null);
      return;
    }
    if (selectedAnime && selectedAnime.id !== id) {
      setSelectedAnime(null);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [createAnimeID]);

  function clearMessages() {
    setErrorMessage(null);
    setSuccessMessage(null);
  }

  function formatError(error: unknown, fallback: string): string {
    if (error instanceof ApiError) {
      return `(${error.status}) ${error.message}`;
    }
    return fallback;
  }

  async function runAnimeSearch(query: string) {
    clearMessages();
    setAnimeSearchError(null);

    const normalized = query.trim();
    setAnimeSearchQuery(normalized);
    if (normalized.length < 2) {
      setAnimeSearchResults([]);
      setAnimeSearchTotal(0);
      if (normalized.length > 0) {
        setAnimeSearchError(
          "Bitte mindestens 2 Zeichen für die Suche eingeben.",
        );
      }
      return;
    }

    try {
      setIsSearchingAnime(true);
      const response = await getAnimeList({
        page: 1,
        per_page: ANIME_SEARCH_PER_PAGE,
        q: normalized,
        include_disabled: true,
      });
      setAnimeSearchResults(response.data);
      setAnimeSearchTotal(response.meta.total);
    } catch (error) {
      console.error("admin/episodes: anime search failed", error);
      if (error instanceof ApiError)
        setAnimeSearchError(`(${error.status}) ${error.message}`);
      else setAnimeSearchError("Anime-Suche fehlgeschlagen.");
    } finally {
      setIsSearchingAnime(false);
    }
  }

  function handleSelectAnime(anime: AnimeListItem) {
    setSelectedAnime(anime);
    setCreateAnimeID(String(anime.id));
    setSuccessMessage(`Anime #${anime.id} ausgewählt: ${anime.title}`);
  }

  async function handleCreateSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    clearMessages();
    setLastRequest(null);
    setLastResponse(null);

    if (!hasAuthToken) {
      setErrorMessage(
        "Anmeldung erforderlich. Bitte zuerst anmelden.",
      );
      return;
    }

    const animeID = parsePositiveInt(createAnimeID);
    if (!animeID) {
      setErrorMessage("anime_id ist ungültig");
      return;
    }

    const episodeNumber = createEpisodeNumber.trim();
    if (!episodeNumber) {
      setErrorMessage("episode_number ist erforderlich");
      return;
    }

    const payload: AdminEpisodeCreateRequest = {
      anime_id: animeID,
      episode_number: episodeNumber,
      status: createStatus,
    };

    const title = normalizeOptionalString(createTitle);
    if (title) {
      payload.title = title;
    }

    try {
      setIsSubmittingCreate(true);
      setLastRequest(JSON.stringify(payload, null, 2));
      const response = await createAdminEpisode(payload);
      setSuccessMessage(`Episode #${response.data.id} wurde erstellt.`);
      setLastResponse(JSON.stringify(response, null, 2));
      setCreateAnimeID("");
      setSelectedAnime(null);
      setCreateEpisodeNumber("");
      setCreateTitle("");
      setCreateStatus("private");
    } catch (error) {
      console.error("admin/episodes: create failed", error);
      setErrorMessage(
        formatError(error, "Episode konnte nicht erstellt werden."),
      );
    } finally {
      setIsSubmittingCreate(false);
    }
  }

  async function handleUpdateSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    clearMessages();
    setLastRequest(null);
    setLastResponse(null);

    if (!hasAuthToken) {
      setErrorMessage(
        "Anmeldung erforderlich. Bitte zuerst anmelden.",
      );
      return;
    }

    const episodeID = parsePositiveInt(updateEpisodeID);
    if (!episodeID) {
      setErrorMessage("Episode-ID ist ungültig.");
      return;
    }

    const payload: AdminEpisodePatchRequest = {};
    const episodeNumber = normalizeOptionalString(updateEpisodeNumber);
    const title = normalizeOptionalString(updateTitle);

    if (episodeNumber) {
      payload.episode_number = episodeNumber;
    }
    if (clearUpdateTitle) payload.title = null;
    else if (title) payload.title = title;
    if (updateStatus) {
      payload.status = updateStatus as EpisodeStatus;
    }

    if (Object.keys(payload).length === 0) {
      setErrorMessage("Mindestens ein Feld für das Update ausfuellen.");
      return;
    }

    try {
      setIsSubmittingUpdate(true);
      setLastRequest(JSON.stringify(payload, null, 2));
      const response = await updateAdminEpisode(episodeID, payload);
      setSuccessMessage(`Episode #${response.data.id} wurde aktualisiert.`);
      setLastResponse(JSON.stringify(response, null, 2));
    } catch (error) {
      console.error("admin/episodes: update failed", error);
      setErrorMessage(
        formatError(error, "Episode konnte nicht aktualisiert werden."),
      );
    } finally {
      setIsSubmittingUpdate(false);
    }
  }

  return (
    <main className={styles.page}>
      <p className={styles.backLinks}>
        <Link href="/admin">Admin</Link>
        <span> | </span>
        <Link href="/login">Anmeldung</Link>
        <span> | </span>
        <Link href="/admin/anime">Studio</Link>
        <span> | </span>
        <Link href="/anime">Anime</Link>
      </p>

      <header className={styles.header}>
        <h1 className={styles.title}>Admin Episoden</h1>
        <p className={styles.subtitle}>
          Episoden erstellen und bearbeiten (separater Modus).
        </p>
        <p className={styles.hint}>
          Für den verbundenen Workflow mit Anime-Kontext:{" "}
          <Link href="/admin/anime">/admin/anime</Link>
        </p>
        <p className={styles.tokenPreview}>
          Auth:{" "}
          {isClientInitialized
            ? hasAuthToken
              ? "angemeldet"
              : "nicht vorhanden"
            : "wird geprüft"}
        </p>
      </header>

      {!hasAuthToken ? (
        <div className={styles.errorBox}>
          Kein aktiver Login gefunden. Bitte zuerst anmelden.
        </div>
      ) : null}

      <section className={styles.panel}>
        <h2>Episode erstellen</h2>
        <form className={styles.form} onSubmit={handleCreateSubmit}>
          <div className={styles.grid}>
            <div className={styles.field}>
              <label htmlFor="anime-search">Anime suchen (Server)</label>
              <div className={styles.inputRow}>
                <input
                  id="anime-search"
                  value={animeSearchInput}
                  onChange={(event) => setAnimeSearchInput(event.target.value)}
                  disabled={isSubmittingCreate || isSearchingAnime}
                  placeholder="z. B. attack, komödie, yamato"
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      event.preventDefault();
                      runAnimeSearch(animeSearchInput);
                    }
                  }}
                />
                <button
                  className={styles.buttonSecondary}
                  type="button"
                  disabled={
                    isSubmittingCreate ||
                    isSearchingAnime ||
                    animeSearchInput.trim().length < 2
                  }
                  onClick={() => runAnimeSearch(animeSearchInput)}
                >
                  Suchen
                </button>
                <button
                  className={styles.buttonSecondary}
                  type="button"
                  disabled={
                    isSubmittingCreate ||
                    isSearchingAnime ||
                    animeSearchInput.length === 0
                  }
                  onClick={() => {
                    setAnimeSearchInput("");
                    setAnimeSearchQuery("");
                    setAnimeSearchResults([]);
                    setAnimeSearchTotal(0);
                    setAnimeSearchError(null);
                  }}
                  aria-label="Suche leeren"
                  title="Suche leeren"
                >
                  X
                </button>
              </div>
              {animeSearchQuery ? (
                <p className={styles.hint}>
                  Suche: {animeSearchQuery} | Treffer:{" "}
                  {animeSearchResults.length} (gesamt: {animeSearchTotal})
                </p>
              ) : (
                <p className={styles.hint}>
                  Tip: Suche reduziert die Notwendigkeit, Anime-IDs manuell zu
                  kennen.
                </p>
              )}
              {isSearchingAnime ? (
                <p className={styles.hint}>Suche läuft...</p>
              ) : null}
              {animeSearchError ? (
                <div className={styles.errorBox}>{animeSearchError}</div>
              ) : null}
              {!isSearchingAnime &&
              animeSearchQuery &&
              animeSearchResults.length === 0 &&
              !animeSearchError ? (
                <p className={styles.hint}>Keine Anime gefunden.</p>
              ) : null}
              {!isSearchingAnime && animeSearchResults.length > 0 ? (
                <div
                  className={styles.episodeList}
                  aria-label="Anime Suchergebnisse"
                >
                  {animeSearchResults.map((anime) => (
                    <div
                      key={anime.id}
                      className={`${styles.animeRow} ${selectedAnime?.id === anime.id ? styles.animeRowActive : ""}`}
                    >
                      <Image
                        className={styles.animeThumb}
                        src={getCoverUrl(anime.cover_image)}
                        alt=""
                        width={44}
                        height={58}
                        unoptimized
                        onError={handleCoverImgError}
                      />
                      <div className={styles.animeMeta}>
                        <div className={styles.animeTitleLine}>
                          <p className={styles.animeTitleText}>
                            #{anime.id} | {anime.title}
                          </p>
                          <span
                            className={`${styles.statusBadge} ${styles[resolveAnimeStatusClass(anime.status)]}`}
                          >
                            {anime.status}
                          </span>
                        </div>
                        <p className={styles.hint}>
                          Typ: {anime.type} | Jahr: {anime.year ?? "-"} | Max
                          Episoden: {anime.max_episodes ?? "-"}
                        </p>
                        <div className={styles.actions}>
                          <button
                            className={styles.button}
                            type="button"
                            onClick={() => handleSelectAnime(anime)}
                            disabled={isSubmittingCreate}
                          >
                            Auswählen
                          </button>
                          <a
                            className={styles.buttonSecondary}
                            href={`/anime/${anime.id}`}
                            target="_blank"
                            rel="noreferrer"
                          >
                            Öffnen
                          </a>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : null}
            </div>
          </div>
          <div className={styles.gridTwo}>
            <div className={styles.field}>
              <label htmlFor="create-anime-id">Anime ID *</label>
              <input
                id="create-anime-id"
                value={createAnimeID}
                onChange={(event) => setCreateAnimeID(event.target.value)}
                disabled={isSubmittingCreate}
                placeholder="z. B. 13394"
              />
              {selectedAnime ? (
                <p className={styles.hint}>
                  Ausgewählt: #{selectedAnime.id} | {selectedAnime.title}
                </p>
              ) : null}
            </div>
            <div className={styles.field}>
              <label htmlFor="create-episode-number">Episode Number *</label>
              <input
                id="create-episode-number"
                value={createEpisodeNumber}
                onChange={(event) => setCreateEpisodeNumber(event.target.value)}
                disabled={isSubmittingCreate}
                placeholder="z. B. 01"
              />
            </div>
            <div className={styles.field}>
              <label htmlFor="create-status">Status *</label>
              <select
                id="create-status"
                value={createStatus}
                onChange={(event) =>
                  setCreateStatus(event.target.value as EpisodeStatus)
                }
                disabled={isSubmittingCreate}
              >
                {EPISODE_STATUSES.map((value) => (
                  <option key={value} value={value}>
                    {value}
                  </option>
                ))}
              </select>
            </div>
            <div className={styles.field}>
              <label htmlFor="create-title">Title</label>
              <input
                id="create-title"
                value={createTitle}
                onChange={(event) => setCreateTitle(event.target.value)}
                disabled={isSubmittingCreate}
              />
            </div>
          </div>

          <div className={styles.actions}>
            <button
              className={styles.button}
              type="submit"
              disabled={isSubmittingCreate}
            >
              {isSubmittingCreate ? "Speichern..." : "Episode erstellen"}
            </button>
            {parsePositiveInt(createAnimeID) ? (
              <Link
                href={`/anime/${createAnimeID}`}
                className={styles.buttonSecondary}
              >
                Anime öffnen
              </Link>
            ) : null}
          </div>
        </form>
      </section>

      <section className={styles.panel}>
        <h2>Episode bearbeiten (Patch)</h2>
        <p className={styles.hint}>
          Nur ausgewählte Felder werden gesendet. Für nullable Felder kannst du
          explizit Wert löschen (null) wählen.
        </p>
        <form className={styles.form} onSubmit={handleUpdateSubmit}>
          <div className={styles.gridTwo}>
            <div className={styles.field}>
              <label htmlFor="update-episode-id">Episode ID *</label>
              <input
                id="update-episode-id"
                value={updateEpisodeID}
                onChange={(event) => setUpdateEpisodeID(event.target.value)}
                disabled={isSubmittingUpdate}
                placeholder="z. B. 33336"
              />
            </div>
            <div className={styles.field}>
              <label htmlFor="update-episode-number">Episode Number</label>
              <input
                id="update-episode-number"
                value={updateEpisodeNumber}
                onChange={(event) => setUpdateEpisodeNumber(event.target.value)}
                disabled={isSubmittingUpdate}
              />
            </div>
            <div className={styles.field}>
              <label htmlFor="update-status">Status</label>
              <select
                id="update-status"
                value={updateStatus}
                onChange={(event) => setUpdateStatus(event.target.value)}
                disabled={isSubmittingUpdate}
              >
                <option value="">-- unveraendert --</option>
                {EPISODE_STATUSES.map((value) => (
                  <option key={value} value={value}>
                    {value}
                  </option>
                ))}
              </select>
            </div>
            <div className={styles.field}>
              <label htmlFor="update-title">Title</label>
              <input
                id="update-title"
                value={updateTitle}
                onChange={(event) => setUpdateTitle(event.target.value)}
                disabled={isSubmittingUpdate || clearUpdateTitle}
              />
              <label className={styles.nullToggle}>
                <input
                  type="checkbox"
                  checked={clearUpdateTitle}
                  onChange={(event) =>
                    setClearUpdateTitle(event.target.checked)
                  }
                  disabled={isSubmittingUpdate}
                />
                Wert löschen (null)
              </label>
            </div>
          </div>

          <div className={styles.actions}>
            <button
              className={styles.buttonSecondary}
              type="submit"
              disabled={isSubmittingUpdate}
            >
              {isSubmittingUpdate ? "Speichern..." : "Episode aktualisieren"}
            </button>
            {parsePositiveInt(updateEpisodeID) ? (
              <Link
                href={`/episodes/${updateEpisodeID}`}
                className={styles.buttonSecondary}
              >
                Episode öffnen
              </Link>
            ) : null}
          </div>
        </form>
      </section>

      {errorMessage ? (
        <div className={styles.errorBox}>{errorMessage}</div>
      ) : null}
      {successMessage ? (
        <div className={styles.successBox}>{successMessage}</div>
      ) : null}
      {lastRequest ? (
        <pre className={styles.resultBox}>
          {"LAST REQUEST\n"}
          {lastRequest}
        </pre>
      ) : null}
      {lastResponse ? (
        <pre className={styles.resultBox}>
          {"LAST RESPONSE\n"}
          {lastResponse}
        </pre>
      ) : null}
    </main>
  );
}

