'use client'

import { useEffect, useMemo, useState } from 'react'
import { Pencil, Plus, Trash2, Users } from 'lucide-react'

import {
  Button,
  Drawer,
  EmptyState,
  ErrorState,
  FormField,
  Select,
} from '@/components/ui'
import {
  deleteAnimeContribution,
  upsertAnimeContribution,
} from '@/lib/api'
import type {
  AnimeContribution,
  UnifiedGroupMember,
} from '@/types/fansub'

import { ContributorAvatar } from './ContributorAvatar'
import { normalizeRoleCodes, roleLabels, sameRoleCodes } from './contributionRoles'
import { useRoleCatalog } from '@/providers/RoleCatalogProvider'
import { RoleToggleGroup } from './RoleToggleGroup'
import styles from './FansubEdit.module.css'

type EditableProjectContribution = {
  contribution_id: number
  member_id: number
  member_display_name: string
  member_avatar_url?: string | null
  role_codes: string[]
  isNew?: boolean
}

type Props = {
  fansubId: number
  animeId: number
  animeTitle: string
  members: UnifiedGroupMember[]
  existingContributions: AnimeContribution[]
  focusedRoleCode?: string | null
  onClose: () => void
  onSaved: () => void
}

function toEditableRow(contribution: AnimeContribution, catalog: Parameters<typeof normalizeRoleCodes>[0]): EditableProjectContribution {
  return {
    contribution_id: contribution.id,
    member_id: contribution.member_id,
    member_display_name: contribution.member_display_name,
    member_avatar_url: contribution.member_avatar_url ?? null,
    role_codes: normalizeRoleCodes(catalog, contribution.role_codes ?? []),
  }
}

export default function AnimeContributionModal({
  fansubId,
  animeId,
  animeTitle,
  members,
  existingContributions,
  focusedRoleCode = null,
  onClose,
  onSaved,
}: Props) {
  const { roles: contributionRoles, error: roleCatalogError } = useRoleCatalog('anime_contribution')
  const [stagedRows, setStagedRows] = useState<EditableProjectContribution[]>([])
  const [originalProjectRows, setOriginalProjectRows] = useState<AnimeContribution[]>([])
  const [originalRolesById, setOriginalRolesById] = useState<Record<number, string[]>>({})
  const [removedIds, setRemovedIds] = useState<number[]>([])
  const [addingRow, setAddingRow] = useState(false)
  const [newMemberId, setNewMemberId] = useState<number | null>(null)
  const [newRoleCodes, setNewRoleCodes] = useState<string[]>([])
  const [editingRoleIds, setEditingRoleIds] = useState<Set<number>>(new Set())
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const projectRows = existingContributions
      .filter((contribution) => contribution.release_version_id == null)
      .map((contribution) => ({
        ...contribution,
        role_codes: normalizeRoleCodes(contributionRoles, contribution.role_codes ?? []),
      }))

    const focusedRoleExists = Boolean(
      focusedRoleCode &&
        contributionRoles.some((role) => role.code === focusedRoleCode),
    )

    setStagedRows(projectRows.map((row) => toEditableRow(row, contributionRoles)))
    setOriginalProjectRows(projectRows)
    setOriginalRolesById(
      Object.fromEntries(projectRows.map((row) => [row.id, row.role_codes])),
    )
    setRemovedIds([])
    setAddingRow(focusedRoleExists)
    setNewMemberId(null)
    setNewRoleCodes(focusedRoleExists && focusedRoleCode ? [focusedRoleCode] : [])
    setEditingRoleIds(new Set())
    setError(null)
  }, [existingContributions, focusedRoleCode])

  function handleRemove(row: EditableProjectContribution) {
    setStagedRows((prev) => prev.filter((item) => item.contribution_id !== row.contribution_id))
    if (!row.isNew && row.contribution_id > 0) {
      setRemovedIds((prev) => [...prev, row.contribution_id])
    }
  }

  function handleRoleToggle(contributionId: number, roleCode: string) {
    setStagedRows((prev) =>
      prev.map((row) => {
        if (row.contribution_id !== contributionId) return row
        const selected = new Set(row.role_codes)
        if (selected.has(roleCode)) {
          selected.delete(roleCode)
        } else {
          selected.add(roleCode)
        }
        return { ...row, role_codes: normalizeRoleCodes(contributionRoles, Array.from(selected)) }
      }),
    )
  }

  function toggleRoleEditor(contributionId: number) {
    setEditingRoleIds((prev) => {
      const next = new Set(prev)
      if (next.has(contributionId)) {
        next.delete(contributionId)
      } else {
        next.add(contributionId)
      }
      return next
    })
  }

  function handleNewRoleToggle(roleCode: string) {
    setNewRoleCodes((prev) => {
      const selected = new Set(prev)
      if (selected.has(roleCode)) {
        selected.delete(roleCode)
      } else {
        selected.add(roleCode)
      }
      return normalizeRoleCodes(contributionRoles, Array.from(selected))
    })
  }

  function buildPendingNewRow(): EditableProjectContribution | null {
    if (newMemberId == null || newRoleCodes.length === 0) return null
    const member = members.find((item) => item.member_id === newMemberId)
    if (!member) return null

    return {
      contribution_id: -Date.now(),
      member_id: member.member_id,
      member_display_name: member.display_name,
      member_avatar_url: null,
      role_codes: normalizeRoleCodes(contributionRoles, newRoleCodes),
      isNew: true,
    }
  }

  function handleAddConfirm() {
    const pendingRow = buildPendingNewRow()
    if (!pendingRow) return

    setStagedRows((prev) => [
      ...prev,
      pendingRow,
    ])
    setAddingRow(false)
    setNewMemberId(null)
    setNewRoleCodes([])
  }

  async function handleSave() {
    const pendingRow = addingRow ? buildPendingNewRow() : null

    if (addingRow && (newMemberId != null || newRoleCodes.length > 0) && !pendingRow) {
      setError('Bitte wähle eine Person und mindestens eine Rolle aus.')
      return
    }

    const rowsForSave = pendingRow ? [...stagedRows, pendingRow] : stagedRows

    if (rowsForSave.some((row) => row.role_codes.length === 0)) {
      setError('Jede Person braucht mindestens eine Rolle.')
      return
    }

    setSaving(true)
    setError(null)

    try {
      await Promise.all(removedIds.map((id) => deleteAnimeContribution(fansubId, animeId, id)))

      const originalById = new Map(originalProjectRows.map((row) => [row.id, row]))
      const rowsToWrite = rowsForSave.filter(
        (row) =>
          row.isNew ||
          !sameRoleCodes(contributionRoles, row.role_codes, originalRolesById[row.contribution_id] ?? []) ||
          originalById.get(row.contribution_id)?.is_public_on_anime_page !== true ||
          originalById.get(row.contribution_id)?.is_public_on_member_profile !== true ||
          originalById.get(row.contribution_id)?.status !== 'confirmed',
      )

      await Promise.all(
        rowsToWrite.map((row) => {
          const original = originalById.get(row.contribution_id)
          const status = 'confirmed'
          const defaultPublic = status === 'confirmed'
          return upsertAnimeContribution(fansubId, animeId, {
            member_id: row.member_id,
            role_codes: normalizeRoleCodes(contributionRoles, row.role_codes),
            release_version_id: null,
            started_year: original?.started_year ?? null,
            ended_year: original?.ended_year ?? null,
            note: original?.note ?? null,
            is_public_on_anime_page: defaultPublic,
            is_public_on_member_profile: defaultPublic,
            status,
          })
        }),
      )

      onSaved()
      onClose()
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : 'Speichern fehlgeschlagen. Bitte Eingaben prüfen und erneut versuchen.',
      )
    } finally {
      setSaving(false)
    }
  }

  const assignedMemberIds = useMemo(
    () => new Set(stagedRows.map((row) => row.member_id)),
    [stagedRows],
  )
  const availableMembers = members.filter((member) => !assignedMemberIds.has(member.member_id))
  const canAddRow = newMemberId != null && newRoleCodes.length > 0
  const hasRowsWithoutRoles = stagedRows.some((row) => row.role_codes.length === 0)

  const footer = (
    <>
      <Button variant="ghost" onClick={onClose} disabled={saving}>
        Abbrechen
      </Button>
      <Button
        variant="primary"
        onClick={handleSave}
        loading={saving}
        disabled={hasRowsWithoutRoles}
      >
        Speichern
      </Button>
    </>
  )

  return (
    <Drawer
      open
      onClose={onClose}
      title={`Mitwirkende: ${animeTitle}`}
      description={`Standard-Team für alle Episoden · ${stagedRows.length} Person${stagedRows.length === 1 ? '' : 'en'}`}
      footer={footer}
      variant="responsiveSheet"
    >
      <div className={styles.contributionSheetIntro}>
        <div className={styles.contributionToolbarMeta}>
          <span>Diese Besetzung gilt als Projektteam für alle Episoden.</span>
        </div>
        {!addingRow ? (
          <Button
            variant="ghost"
            leftIcon={<Plus size={16} />}
            onClick={() => setAddingRow(true)}
            disabled={availableMembers.length === 0 || Boolean(roleCatalogError)}
          >
            Person hinzufügen
          </Button>
        ) : null}
      </div>

      {roleCatalogError ? (
        <ErrorState
          title="Rollen konnten nicht geladen werden"
          description="Die Rollen-Auswahl ist vorübergehend nicht verfügbar."
        />
      ) : null}

      {members.length === 0 ? (
        <EmptyState
          title="Keine Fansub-Member"
          description="Lege zuerst Mitglieder in der Fansubgruppe an."
        />
      ) : null}

      {addingRow && members.length > 0 ? (
        <div className={styles.contributionAddPanel}>
          <FormField label="Person" htmlFor="new-project-member-select">
            <Select
              id="new-project-member-select"
              value={newMemberId != null ? String(newMemberId) : ''}
              onChange={(event) =>
                setNewMemberId(event.currentTarget.value ? Number(event.currentTarget.value) : null)
              }
              disabled={availableMembers.length === 0}
            >
              <option value="">
                {availableMembers.length === 0 ? 'Alle Personen sind zugewiesen' : 'Person wählen'}
              </option>
              {availableMembers.map((member) => (
                <option key={member.member_id} value={member.member_id}>
                  {member.display_name}
                </option>
              ))}
            </Select>
          </FormField>
          <div className={styles.contributionRolesCell}>
            <span className={styles.contributionRoleLabel}>Rollen</span>
            <RoleToggleGroup
              selectedCodes={newRoleCodes}
              onToggle={handleNewRoleToggle}
              ariaLabel="Rollen für neue Person"
            />
          </div>
          <div className={styles.contributionAddActions}>
            <Button
              variant="primary"
              size="sm"
              onClick={handleAddConfirm}
              leftIcon={<Users size={16} />}
              disabled={!canAddRow}
            >
              Hinzufügen
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                setAddingRow(false)
                setNewMemberId(null)
                setNewRoleCodes([])
              }}
            >
              Abbrechen
            </Button>
          </div>
        </div>
      ) : null}

      {stagedRows.length === 0 && !addingRow && members.length > 0 ? (
        <EmptyState
          title="Noch keine Mitwirkenden"
          description="Füge bestehende Fansub-Member hinzu und wähle ihre Rollen für dieses Projekt."
        />
      ) : null}

      {stagedRows.length > 0 ? (
        <div className={styles.contributionRows} role="list" aria-label="Mitwirkende dieses Anime-Projekts">
          {stagedRows.map((row) => {
            const labels = roleLabels(contributionRoles, row.role_codes)
            const editing = editingRoleIds.has(row.contribution_id)

            return (
              <div key={row.contribution_id} className={styles.contributionEditRow} role="listitem">
                <div className={styles.contributionPersonCell}>
                  <ContributorAvatar
                    name={row.member_display_name}
                    avatarUrl={row.member_avatar_url ?? null}
                  />
                  <div>
                    <strong>{row.member_display_name}</strong>
                    {row.isNew ? <span>Neu</span> : null}
                  </div>
                </div>
                <div className={styles.contributionRolesCell}>
                  <div className={styles.contributionRoleSummaryLine}>
                    <div className={styles.contributionRoleSummaryChips}>
                      {labels.length > 0 ? (
                        labels.map((label) => (
                          <span key={label} className={styles.contributionRoleSummaryChip}>
                            {label}
                          </span>
                        ))
                      ) : (
                        <span className={styles.contributionRoleSummaryEmpty}>Keine Rolle</span>
                      )}
                    </div>
                  </div>
                  {editing ? (
                    <RoleToggleGroup
                      selectedCodes={row.role_codes}
                      onToggle={(code) => handleRoleToggle(row.contribution_id, code)}
                      ariaLabel={`Rollen für ${row.member_display_name}`}
                    />
                  ) : null}
                </div>
                <div className={styles.contributionRowActions}>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    leftIcon={<Pencil size={15} />}
                    aria-label={`Rollen für ${row.member_display_name} ändern`}
                    onClick={() => toggleRoleEditor(row.contribution_id)}
                  >
                    {editing ? 'Fertig' : 'Rollen ändern'}
                  </Button>
                  <Button
                    variant="ghost"
                    iconOnly
                    size="sm"
                    aria-label={`${row.member_display_name} entfernen`}
                    className={styles.contributionRemoveButton}
                    onClick={() => handleRemove(row)}
                  >
                    <Trash2 size={18} />
                  </Button>
                </div>
              </div>
            )
          })}
        </div>
      ) : null}

      {hasRowsWithoutRoles ? (
        <p className={styles.contributionInlineWarning}>
          Jede Person braucht mindestens eine Rolle.
        </p>
      ) : null}
      {error ? <p className={styles.contributionInlineWarning}>{error}</p> : null}
    </Drawer>
  )
}

'use client'

import { useState } from 'react'
import { Save } from 'lucide-react'

import { RichTextEditor } from '@/components/editor'
import { Button, FormField, Select } from '@/components/ui'
import { ApiError, upsertAnimeFansubProjectNote } from '@/lib/api'
import type { AnimeFansubProjectNote, UpsertAnimeFansubProjectNoteRequest } from '@/types/fansubNotes'

import sharedStyles from '../../../admin.module.css'
import editorScaffoldStyles from '../../../../../components/editor/EditorScaffold.module.css'
import fansubEditStyles from './FansubEdit.module.css'

const styles = { ...sharedStyles, ...fansubEditStyles, ...editorScaffoldStyles }

export const ANIME_PROJECT_NOTE_PLACEHOLDER = `Beschreibe hier das Fansubprojekt dieser Gruppe zu diesem Anime.
Mögliche Fragen als Hilfe: Wie war dieses Fansubprojekt? Warum hat die Gruppe diesen Anime gemacht?
Was war besonders? Wie lief die Arbeit? Gab es Coop? Gab es Re-Releases? Gab es Probleme/Abbrüche?
Welche Rollen waren besonders wichtig? Schöne/schwierige Erinnerungen?`

export const EMPTY_RICH_TEXT_DOC = {
  type: 'doc',
  content: [{ type: 'paragraph' }],
} as const

export type NoteVisibility = 'public' | 'internal'
export type NoteStatus = 'draft' | 'published' | 'archived' | 'deleted'

export interface AnimeEntry {
  id: number
  title: string
}

export interface NoteFormState {
  title: string
  bodyJson: unknown | null
  visibility: NoteVisibility
  status: NoteStatus
}

export const emptyNoteForm = (): NoteFormState => ({
  title: '',
  bodyJson: null,
  visibility: 'internal',
  status: 'draft',
})

export function ensureRichTextValue(value: unknown | null): unknown {
  return value ?? EMPTY_RICH_TEXT_DOC
}

export function noteVisibilityLabel(value: NoteVisibility): string {
  return value === 'public' ? 'Öffentlich' : 'Intern'
}

export function noteStatusLabel(value: NoteStatus): string {
  if (value === 'draft') return 'Entwurf'
  if (value === 'published') return 'Veröffentlicht'
  if (value === 'archived') return 'Archiviert'
  return 'Gelöscht'
}

export function noteToForm(note: AnimeFansubProjectNote): NoteFormState {
  return {
    title: note.title ?? '',
    bodyJson: note.bodyJson ?? null,
    visibility: note.visibility,
    status: note.status,
  }
}

export interface AnimeProjectNoteFormProps {
  fansubId: number
  anime: AnimeEntry
  hasAccessToken: boolean
  initialNote: AnimeFansubProjectNote | null
  onSaved: (note: AnimeFansubProjectNote) => void
}

export function AnimeProjectNoteForm({ fansubId, anime, hasAccessToken, initialNote, onSaved }: AnimeProjectNoteFormProps) {
  const [form, setForm] = useState<NoteFormState>(() => initialNote ? noteToForm(initialNote) : emptyNoteForm())
  const [saving, setSaving] = useState(false)
  const [saveError, setSaveError] = useState<string | null>(null)

  async function handleSave() {
    if (!hasAccessToken) return

    setSaving(true)
    setSaveError(null)

    const payload: UpsertAnimeFansubProjectNoteRequest = {
      title: form.title.trim() || undefined,
      bodyJson: ensureRichTextValue(form.bodyJson),
      visibility: form.visibility,
      status: form.status,
    }

    try {
      const saved = await upsertAnimeFansubProjectNote(fansubId, anime.id, payload)
      setForm(noteToForm(saved))
      setSaving(false)
      onSaved(saved)
    } catch (err: unknown) {
      setSaveError(err instanceof ApiError ? err.message : 'Fehler beim Speichern des Projekttexts.')
      setSaving(false)
    }
  }

  return (
    <section className={styles.editorCard}>
      <div className={styles.editorCardHeader}>
        <div className={styles.editorCardHeading}>
          <p className={styles.editorEyebrow}>Anime-Projekttext</p>
          <h3 className={styles.editorTitle}>Projekttext für {anime.title}</h3>
        </div>
        <div className={styles.editorBadgeRow}>
          <span className={styles.editorBadge}>{noteVisibilityLabel(form.visibility)}</span>
          <span className={styles.editorBadge}>{noteStatusLabel(form.status)}</span>
        </div>
      </div>

      <div className={styles.editorMain}>
        <div className={styles.field}>
          <label htmlFor={`note-title-${anime.id}`}>Titel</label>
          <input
            id={`note-title-${anime.id}`}
            type="text"
            value={form.title}
            onChange={(e) => setForm((current) => ({ ...current, title: e.target.value }))}
            placeholder="Titel des Projekttexts (optional)"
          />
        </div>

        <div className={styles.field}>
          <label htmlFor={`note-body-${anime.id}`}>Projekttext</label>
          <RichTextEditor
            value={ensureRichTextValue(form.bodyJson)}
            onChange={(next) => setForm((current) => ({ ...current, bodyJson: next }))}
            placeholder={ANIME_PROJECT_NOTE_PLACEHOLDER}
            mode="longform"
            minHeight={240}
          />
        </div>
      </div>

      <div className={styles.editorMetaCard}>
        <div className={styles.editorMetaHeader}>
          <div>
            <p className={styles.fansubEditorEyebrow}>Optionen</p>
            <h4 className={styles.fansubEditorMetaTitle}>Steuerung für Sichtbarkeit und Status</h4>
          </div>
        </div>

        <div className={styles.editorMetaGrid}>
          <FormField label="Sichtbarkeit">
            <Select
              value={form.visibility}
              onChange={(e) => setForm((current) => ({ ...current, visibility: e.target.value as NoteVisibility }))}
            >
              <option value="internal">Intern</option>
              <option value="public">Öffentlich</option>
            </Select>
          </FormField>

          <FormField label="Status">
            <Select
              value={form.status}
              onChange={(e) => setForm((current) => ({ ...current, status: e.target.value as NoteStatus }))}
            >
              <option value="draft">Entwurf</option>
              <option value="published">Veröffentlicht</option>
              <option value="archived">Archiviert</option>
              <option value="deleted">Gelöscht</option>
            </Select>
          </FormField>
        </div>
      </div>

      {saveError ? <div className={styles.errorBox}>{saveError}</div> : null}

      <div className={styles.editorActionBar}>
        <div className={styles.editorActionMeta} />
        <Button
          type="button"
          variant="success"
          className={styles.editorPrimaryAction}
          leftIcon={<Save size={14} />}
          onClick={() => void handleSave()}
          disabled={saving || !hasAccessToken}
        >
          {saving ? 'Speichern...' : 'Speichern'}
        </Button>
      </div>
    </section>
  )
}

