  const [snapshotMode, setSnapshotMode] = useState<ReleaseCrewSnapshotMode>('inherited')
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [addingRow, setAddingRow] = useState(false)
  const [newMemberId, setNewMemberId] = useState<number | null>(null)
  const [newRoleCodes, setNewRoleCodes] = useState<string[]>([])
  const [editingRoleIds, setEditingRoleIds] = useState<Set<number>>(new Set())

  useEffect(() => {
    if (!open) return

    let cancelled = false
    setLoading(true)
    setError(null)
    setStagedRows([])
    setAddingRow(false)
    setNewMemberId(null)
    setNewRoleCodes([])
    setEditingRoleIds(new Set())
    setSnapshotMode('inherited')

    void (async () => {
      try {
        const membersResult = await listUnifiedGroupMembers(fansubId)
        const contributionsResult = await listEffectiveContributionsForVersion(
          releaseVersionId,
          fansubId,
        )
        if (cancelled) return
        const rows = (contributionsResult.data ?? []).map((row) => ({
          ...row,
          role_codes: normalizeRoleCodes(contributionRoles, row.role_codes),
        }))

        setMembers(membersResult ?? [])
        setStagedRows(rows)
        setSnapshotMode(contributionsResult.meta.snapshot_mode)
      } catch (err: unknown) {
        if (cancelled) return
        setError(err instanceof Error ? err.message : 'Laden fehlgeschlagen.')
      } finally {
        if (!cancelled) setLoading(false)
      }
    })()

    return () => {
      cancelled = true
    }
  }, [open, fansubId, releaseVersionId])

  function handleRemove(row: EditableContributionRow) {
    setStagedRows((prev) => prev.filter((r) => r.contribution_id !== row.contribution_id))
  }

  function handleRoleToggle(contributionId: number, roleCode: string) {
    setStagedRows((prev) =>
      prev.map((row) => {
        if (row.contribution_id !== contributionId) return row
        const selected = new Set(row.role_codes)
        if (selected.has(roleCode)) {
          selected.delete(roleCode)
        } else {
          selected.add(roleCode)
        }
        return { ...row, role_codes: normalizeRoleCodes(contributionRoles, Array.from(selected)) }
      }),
    )
  }

  function toggleRoleEditor(contributionId: number) {
    setEditingRoleIds((prev) => {
      const next = new Set(prev)
      if (next.has(contributionId)) {
        next.delete(contributionId)
      } else {
        next.add(contributionId)
      }
      return next
    })
  }

  function handleNewRoleToggle(roleCode: string) {
    setNewRoleCodes((prev) => {
      const selected = new Set(prev)
      if (selected.has(roleCode)) {
        selected.delete(roleCode)
      } else {
        selected.add(roleCode)
      }
      return normalizeRoleCodes(contributionRoles, Array.from(selected))
    })
  }

  function handleAddConfirm() {
    if (newMemberId == null || newRoleCodes.length === 0) return
    const member = members.find((m) => m.member_id === newMemberId)
    if (!member) return

    const tempId = -Date.now()
    setStagedRows((prev) => [
      ...prev,
      {
        contribution_id: tempId,
        member_id: member.member_id,
        member_display_name: member.display_name,
        member_avatar_url: null,
        role_codes: normalizeRoleCodes(contributionRoles, newRoleCodes),
        isNew: true,
      },
    ])
    setAddingRow(false)
    setNewMemberId(null)
    setNewRoleCodes([])
  }

  async function handleSave() {
    setSaving(true)
    setError(null)
    try {
      if (stagedRows.some((row) => row.role_codes.length === 0)) {
        setError('Jede Person braucht mindestens eine Rolle.')
        return
      }

      await replaceReleaseCrew(releaseVersionId, fansubId, {
        rows: stagedRows
          .map((row) => ({
            member_id: row.member_id,
            role_codes: normalizeRoleCodes(contributionRoles, row.role_codes),
          }))
          .sort((left, right) => left.member_id - right.member_id),
      })

      onSaved()
      onClose()
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : 'Speichern fehlgeschlagen. Bitte Eingaben prüfen und erneut versuchen.',
      )
    } finally {
      setSaving(false)
    }
  }

  const assignedMemberIds = new Set(stagedRows.map((r) => r.member_id))
  const availableMembers = members.filter((m) => !assignedMemberIds.has(m.member_id))
  const hasRowsWithoutRoles = stagedRows.some((row) => row.role_codes.length === 0)
  const canAddRow = newMemberId != null && newRoleCodes.length > 0
  const isIndependent = snapshotMode === 'independent'
  const isUninitialized = snapshotMode === 'uninitialized'
  const statusLabel = isUninitialized
    ? 'Besetzung noch nicht initialisiert'
    : isIndependent
      ? 'Eigene Release-Besetzung'
      : 'Projektbesetzung geerbt'
  const statusVariant = isIndependent ? 'info' : 'muted'
  const changeHint = isUninitialized
    ? 'Diese ältere Release-Version besitzt noch keine gespeicherte Besetzung. Beim Speichern wird die sichtbare Auswahl als eigene Release-Besetzung angelegt.'
    : isIndependent
      ? 'Diese Besetzung bleibt unabhängig von späteren Änderungen am Projektteam.'
      : 'Beim ersten Speichern wird diese vollständige Besetzung dauerhaft unabhängig.'

  const footer = (
    <>
      <Button variant="ghost" onClick={onClose} disabled={saving}>
        Abbrechen
      </Button>
      <Button
        variant="primary"
        onClick={handleSave}
        loading={saving}
        disabled={loading || hasRowsWithoutRoles}
      >
        Speichern
      </Button>
    </>
  )

  return (
    <Drawer
      open={open}
      onClose={onClose}
      title={`Besetzung: ${releaseTitle}`}
      description={`${stagedRows.length} Person${stagedRows.length === 1 ? '' : 'en'} — vollständige Besetzung dieser Version`}
      footer={footer}
      variant="responsiveSheet"
    >
      {loading ? (
        <LoadingState />
      ) : error ? (
        <ErrorState title="Fehler" description={error} />
      ) : (
        <>
          <div className={styles.contributionSheetIntro}>
            <div className={styles.contributionToolbarMeta}>
              <Badge variant={statusVariant}>{statusLabel}</Badge>
              <span>{changeHint}</span>
            </div>
            {!addingRow ? (
              <Button
                variant="secondary"
                leftIcon={<Plus size={16} />}
                onClick={() => setAddingRow(true)}
              >
                Person hinzufügen
              </Button>
            ) : null}
          </div>

          {addingRow ? (
            <div className={styles.contributionAddPanel}>
              <FormField label="Person" htmlFor="new-member-select">
                <Select
                  id="new-member-select"
                  value={newMemberId != null ? String(newMemberId) : ''}
                  onChange={(event) =>
                    setNewMemberId(event.currentTarget.value ? Number(event.currentTarget.value) : null)
                  }
                >
                  <option value="">Person wählen</option>
                  {availableMembers.map((member) => (
                    <option key={member.member_id} value={member.member_id}>
                      {member.display_name}
                    </option>
                  ))}
                </Select>
              </FormField>
              <div className={styles.contributionRolesCell}>
                <span className={styles.contributionRoleLabel}>Rollen</span>
                <RoleToggleGroup
                  selectedCodes={newRoleCodes}
                  onToggle={handleNewRoleToggle}
                  ariaLabel="Rollen für neue Person"
                />
              </div>
              <div className={styles.contributionAddActions}>
                <Button
                  variant="primary"
                  size="sm"
                  onClick={handleAddConfirm}
                  leftIcon={<Users size={16} />}
                  disabled={!canAddRow}
                >
                  Hinzufügen
                </Button>
                <Button variant="ghost" size="sm" onClick={() => setAddingRow(false)}>
                  Abbrechen
                </Button>
              </div>
            </div>
          ) : null}

          {stagedRows.length === 0 && !addingRow ? (
            <EmptyState
              title={isUninitialized ? 'Besetzung noch nicht initialisiert' : 'Noch keine Rollen vergeben'}
              description={
                isUninitialized
                  ? 'Füge die bestätigten Personen und Rollen dieser älteren Release-Version bewusst hinzu oder speichere eine leere eigene Besetzung.'
                  : 'Füge Personen aus dieser Fansubgruppe hinzu und wähle ihre Rollen für diese Folge.'
              }
            />
          ) : (
            <div className={styles.contributionRows} role="list" aria-label="Besetzung dieser Folge">
              {stagedRows.map((row) => {
                const labels = roleLabels(contributionRoles, row.role_codes)
                return (
                  <div key={row.contribution_id} className={styles.contributionEditRow} role="listitem">
                    <div className={styles.contributionPersonCell}>
                      <ContributorAvatar
                        name={row.member_display_name}
                        avatarUrl={row.member_avatar_url}
                      />
                      <div>
                        <strong>{row.member_display_name}</strong>
                        {row.isNew ? <span>Neu</span> : null}
                      </div>
                    </div>
                    <div className={styles.contributionRolesCell}>
                      <div className={styles.contributionRoleSummaryLine}>
                        <div className={styles.contributionRoleSummaryChips}>
                          {labels.length > 0 ? (
                            labels.map((label) => (
                              <span key={label} className={styles.contributionRoleSummaryChip}>
                                {label}
                              </span>
                            ))
                          ) : (
                            <span className={styles.contributionRoleSummaryEmpty}>Keine Rolle</span>
                          )}
                        </div>
                      </div>
                      {editingRoleIds.has(row.contribution_id) ? (
                        <RoleToggleGroup
                          selectedCodes={row.role_codes}
                          onToggle={(code) => handleRoleToggle(row.contribution_id, code)}
                          ariaLabel={`Rollen für ${row.member_display_name}`}
                        />
                      ) : null}
                    </div>
                    <div className={styles.contributionRowActions}>
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        leftIcon={<Pencil size={15} />}
                        aria-label={`Rollen für ${row.member_display_name} ändern`}
                        onClick={() => toggleRoleEditor(row.contribution_id)}
                      >
                        {editingRoleIds.has(row.contribution_id) ? 'Fertig' : 'Rollen ändern'}
                      </Button>
                      <Button
                        variant="ghost"
                        iconOnly
                        size="sm"
                        aria-label={`${row.member_display_name} entfernen`}
                        className={styles.contributionRemoveButton}
                        onClick={() => handleRemove(row)}
                      >
                        <Trash2 size={18} />
                      </Button>
                    </div>
                  </div>
                )
              })}
            </div>
          )}

          {hasRowsWithoutRoles ? (
            <p className={styles.contributionInlineWarning}>
              Jede Person braucht mindestens eine Rolle.
            </p>
          ) : null}
        </>
      )}
    </Drawer>
  )
}

'use client'

import { useEffect, useState } from 'react'

import { FormField, Select } from '@/components/ui'
import {
  deleteAdminReleaseThemeAsset,
  getAdminCanonicalFansubRelease,
  getAdminReleaseThemeAssets,
  uploadAdminReleaseThemeAsset,
} from '@/lib/api'
import { MediaOwnershipContext } from '@/components/admin/media/MediaOwnershipContext'
import type { MediaOwnershipContextValue } from '@/components/admin/media/MediaOwnershipContext'
import { AdminAnimeTheme, AdminReleaseThemeAsset } from '@/types/admin'

import sharedStyles from '../../../admin.module.css'
import opEdStyles from './FansubOpEdSection.module.css'

const styles = { ...sharedStyles, ...opEdStyles }

interface ReleaseThemeAssetsSectionProps {
  fansubID: number
  animeID: number
  hasAccessToken?: boolean
  themes: AdminAnimeTheme[]
  [legacyProp: string]: unknown
}

export function ReleaseThemeAssetsSection({
  fansubID,
  animeID,
  hasAccessToken = false,
  themes,
}: ReleaseThemeAssetsSectionProps) {
  const [themeID, setThemeID] = useState<number>(themes[0]?.id ?? 0)
  const [file, setFile] = useState<File | null>(null)
  const [progress, setProgress] = useState(0)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [releaseID, setReleaseID] = useState<number | null>(null)
  const [assets, setAssets] = useState<AdminReleaseThemeAsset[]>([])
  const [ownerCtx, setOwnerCtx] = useState<MediaOwnershipContextValue | null>(null)

  useEffect(() => {
    setThemeID(themes[0]?.id ?? 0)
  }, [themes])

  // Load release context explicitly from the dedicated canonical release endpoint.
  // This replaces the old pattern of inferring release_id from theme-asset responses.
  useEffect(() => {
    if (!hasAccessToken) return
    let active = true
    getAdminCanonicalFansubRelease(fansubID, animeID)
      .then((releaseCtx) => {
        if (!active) return
        setReleaseID(releaseCtx.release?.release_id ?? null)
      })
      .catch((loadError) => {
        if (active) {
          setError(loadError instanceof Error ? loadError.message : 'Release-Kontext konnte nicht geladen werden.')
        }
      })

    return () => {
      active = false
    }
  }, [animeID, hasAccessToken, fansubID])

  // Load theme assets separately — theme-asset endpoint is now purely about theme assets,
  // not the source of release identity.
  useEffect(() => {
    if (!hasAccessToken || releaseID === null) return
    let active = true
    getAdminReleaseThemeAssets(releaseID)
      .then((response) => {
        if (!active) return
        setAssets(response.data)
      })
      .catch((loadError) => {
        if (active) {
          setError(loadError instanceof Error ? loadError.message : 'Theme-Videos konnten nicht geladen werden.')
        }
      })

    return () => {
      active = false
    }
  }, [hasAccessToken, releaseID])

  async function reloadAssets() {
    if (releaseID === null) return
    const response = await getAdminReleaseThemeAssets(releaseID)
    setAssets(response.data)
  }

  async function handleUpload() {
    if (!file || !themeID || !hasAccessToken) return

    // D-06: Upload blockieren wenn fansubID/animeID fehlt oder Owner nicht auflösbar
    if (!fansubID || !animeID) {
      setError('Upload nicht möglich: Kein gültiger Owner-Kontext.')
      return
    }
    if (!ownerCtx?.ownerResolved) {
      setError('Upload nicht möglich: Kein gültiger Owner-Kontext.')
      return
    }

    setBusy(true)
    setError(null)
    try {
      await uploadAdminReleaseThemeAsset({
        fansubID,
        animeID,
        themeID,
        file,
        onProgress: setProgress,
        visibilityCode: ownerCtx.visibilityCode,
        reviewStatusCode: ownerCtx.reviewStatusCode,
      })
      await reloadAssets()
      setFile(null)
      setProgress(100)
    } catch (uploadError) {
      setError(uploadError instanceof Error ? uploadError.message : 'Upload fehlgeschlagen.')
    } finally {
      setBusy(false)
    }
  }

  // Aktuell gewähltes Theme-Label für categoryValue (slot-Anzeige)
  const selectedTheme = themes.find((t) => t.id === themeID)
  const categoryValue = selectedTheme
    ? `${selectedTheme.theme_type_name}${selectedTheme.title ? ` - ${selectedTheme.title}` : ''}`
    : 'Release-Theme'

  return (
    <div className={styles.uploadForm}>
      {/* D-07: Surface 3 — Release-Theme-Assets (ownerType=release_theme, statusPolicy=immediate) */}
      <MediaOwnershipContext
        ownerType="release_theme"
        ownerID={fansubID}
        ownerLabel={`Release «Anime ${animeID} · Fansub ${fansubID}»`}
        categoryMode="slot"
        categoryValue={categoryValue}
        statusPolicy="immediate"
        disabled={busy}
        onContextChange={setOwnerCtx}
      />

      <div className={styles.formRow}>
        <FormField label="Theme" htmlFor="release-theme-select">
          <Select
            id="release-theme-select"
            value={String(themeID)}
            onChange={(event) => setThemeID(Number(event.target.value))}
          >
            <option value="0">Bitte wählen</option>
            {themes.map((theme) => (
              <option key={theme.id} value={String(theme.id)}>
                {theme.theme_type_name}{theme.title ? ` - ${theme.title}` : ''}
              </option>
            ))}
          </Select>
        </FormField>

        <label className={styles.field}>
          <span>Video-Datei</span>
          {/* hidden file input bleibt nativ — kein @/components/ui-Primitive für file inputs */}
          <input type="file" accept="video/*" onChange={(event) => setFile(event.target.files?.[0] ?? null)} />
        </label>

        <div className={styles.progressWrap}>
          <span>Upload</span>
          <progress value={progress} max={100} />
        </div>

        <button type="button" className={styles.button} onClick={() => void handleUpload()} disabled={!file || !themeID || busy || !hasAccessToken || !ownerCtx?.ownerResolved}>
          {busy ? 'Lade hoch...' : 'Video hochladen'}
        </button>
      </div>

      {error ? <p className={styles.errorBox}>{error}</p> : null}

      {releaseID && assets.length === 0 ? <p className={styles.fansubEditHint}>Keine Videos vorhanden.</p> : null}

      {assets.length > 0 ? (
        <div className={styles.assetList}>
          {assets.map((asset) => (
            <div key={`${asset.release_id}-${asset.theme_id}-${asset.media_id}`} className={styles.assetRow}>
              <div className={styles.assetMeta}>
                <strong>{asset.theme_type_name}{asset.theme_title ? ` - ${asset.theme_title}` : ''}</strong>
                <span>{asset.mime_type} | {Math.round(asset.size_bytes / 1024 / 1024)} MB</span>
                <a href={asset.public_url} target="_blank" rel="noreferrer">Video öffnen</a>
              </div>
              <button
                type="button"
                className={styles.buttonSecondary}
                onClick={async () => {
                  await deleteAdminReleaseThemeAsset(asset.release_id, asset.theme_id, asset.media_id)
                  await reloadAssets()
                }}
              >
                Löschen
              </button>
            </div>
          ))}
        </div>
      ) : null}
    </div>
  )
}

"use client";

import { type MutableRefObject } from "react";
import { ExternalLink, X } from "lucide-react";

import { resolveApiUrl } from "@/lib/api";
import { Button, Modal } from "@/components/ui";
import {
  episodeReleaseTitle,
  themeSegmentEpisodeRange,
  themeSegmentTimeRange,
  timelineLabelFor,
} from "./fansubEditFormatters";
import { isJellyfinLocked } from "./fansubEditReleaseHelpers";
import type { SelectedReleaseSegment } from "./fansubEditTypes";

type ReleaseThemeDrawerSectionProps = {
  styles: Record<string, string>;
  themeDrawerOpen: boolean;
  selectedReleaseSegment: SelectedReleaseSegment | null;
  hasAuthSession: boolean;
  canManageReleaseThemeAssets: boolean;
  drawerError: string | null;
  drawerBusy: boolean;
  drawerUploadProgress: number | null;
  themeUploadName: string;
  themePreviewOpen: boolean;
  setThemePreviewOpen: (open: boolean) => void;
  themeUploadInputRef: MutableRefObject<HTMLInputElement | null>;
  closeThemeDrawer: () => void;
  handleThemeUploadInputChange: () => void;
  handleDrawerUploadClick: () => Promise<void>;
  handleDrawerDelete: () => Promise<void>;
};

export function ReleaseThemeDrawerSection({
  styles,
  themeDrawerOpen,
  selectedReleaseSegment,
  hasAuthSession,
  canManageReleaseThemeAssets,
  drawerError,
  drawerBusy,
  drawerUploadProgress,
  themeUploadName,
  themePreviewOpen,
  setThemePreviewOpen,
  themeUploadInputRef,
  closeThemeDrawer,
  handleThemeUploadInputChange,
  handleDrawerUploadClick,
  handleDrawerDelete,
}: ReleaseThemeDrawerSectionProps) {
  const themeSelectedCard = selectedReleaseSegment?.card ?? null;
  const themeSelectedLocked = themeSelectedCard
    ? themeSelectedCard.status === "global" ||
      isJellyfinLocked(themeSelectedCard) ||
      Boolean(themeSelectedCard.release_asset_upload_locked)
    : false;
  const themePrimarySegment = themeSelectedCard?.segments[0] ?? null;
  const themeAssetPreviewUrl = themeSelectedCard?.public_url
    ? resolveApiUrl(themeSelectedCard.public_url)
    : null;
  const themePreviewDescription =
    selectedReleaseSegment && themeSelectedCard
      ? `${episodeReleaseTitle(selectedReleaseSegment.release)} · ${timelineLabelFor(themeSelectedCard.theme_type_name)}`
      : undefined;
  const drawerUploadStatusLabel =
    drawerUploadProgress === null
      ? null
      : drawerUploadProgress >= 100
        ? "Upload angekommen, wird gespeichert..."
        : `Upload: ${drawerUploadProgress}%`;

  return (
    <>
      {themeDrawerOpen && selectedReleaseSegment && themeSelectedCard ? (
        <div
          className={styles.fansubEditReleaseDrawerOverlay}
          onClick={closeThemeDrawer}
        >
          <aside
            className={`${styles.fansubEditReleaseDrawer} ${styles.fansubEditThemeDrawer}`}
            aria-label="Theme bearbeiten"
            onClick={(event) => event.stopPropagation()}
          >
            <header className={styles.fansubEditReleaseDrawerHeader}>
              <div>
                <p className={styles.fansubEditHint}>
                  {episodeReleaseTitle(selectedReleaseSegment.release)}
                </p>
                <h2>
                  {timelineLabelFor(themeSelectedCard.theme_type_name)}{" "}
                  bearbeiten
                </h2>
                <p>{themeSelectedCard.theme_title || "Ohne Titel"}</p>
              </div>
              <button
                type="button"
                className={styles.fansubEditReleaseExpandButton}
                onClick={closeThemeDrawer}
                aria-label="Theme Drawer schließen"
              >
                <X size={16} />
              </button>
            </header>
            <div className={styles.fansubEditReleaseDrawerBody}>
              <div
                className={`${styles.fansubEditReleaseDrawerPanel} ${styles.fansubEditThemeDrawerPanel}`}
              >
                {drawerError ? (
                  <div className={styles.errorBox}>{drawerError}</div>
                ) : null}
                <div className={styles.fansubEditReleaseDrawerAssetBox}>
                  <div className={styles.fansubEditSegmentEditorGrid}>
                    <div>
                      <span className={styles.fansubEditSegmentEditorLabel}>
                        Status
                      </span>
                      <strong>
                        {themeSelectedCard.status === "global"
                          ? "Global gesetzt"
                          : themeSelectedCard.status === "release"
                            ? "Uploadet"
                            : "Fehlt noch"}
                      </strong>
                    </div>
                    <div>
                      <span className={styles.fansubEditSegmentEditorLabel}>
                        Theme
                      </span>
                      <strong>
                        {themeSelectedCard.theme_title || "Ohne Titel"}
                      </strong>
                    </div>
                    <div>
                      <span className={styles.fansubEditSegmentEditorLabel}>
                        Quelle
                      </span>
                      <strong>
                        {themeSelectedCard.source_label || "Keine Quelle"}
                      </strong>
                    </div>
                    <div>
                      <span className={styles.fansubEditSegmentEditorLabel}>
                        Release
                      </span>
                      <strong>
                        #{selectedReleaseSegment.release.release_id}
                      </strong>
                    </div>
                    <div>
                      <span className={styles.fansubEditSegmentEditorLabel}>
                        Episode
                      </span>
                      <strong>
                        {themeSegmentEpisodeRange(themePrimarySegment)}
                      </strong>
                    </div>
                    <div>
                      <span className={styles.fansubEditSegmentEditorLabel}>
                        Zeitbereich
                      </span>
                      <strong>
                        {themeSegmentTimeRange(themePrimarySegment)}
                      </strong>
                    </div>
                  </div>
                  {themeAssetPreviewUrl ? (
                    <Button
                      type="button"
                      variant="secondary"
                      size="sm"
                      leftIcon={<ExternalLink size={16} />}
                      className={styles.fansubEditReleaseDrawerMediaLink}
                      onClick={() => setThemePreviewOpen(true)}
                    >
                      Aktuelles Asset ansehen
                    </Button>
                  ) : null}
                  {themeSelectedLocked ? (
                    <p className={styles.fansubEditHint}>
                      {themeSelectedCard.release_asset_upload_locked
                        ? "Dieses Theme gilt für einen Episodenbereich. Der Upload wird am Segmentstart verwaltet, nicht an dieser Folge."
                        : "Global/Jellyfin gesetzt - keine Fansub-Überschreibung in diesem Schritt."}
                    </p>
                  ) : !canManageReleaseThemeAssets ? (
                    <p className={styles.fansubEditHint}>
                      Du kannst die Theme-Zuordnung ansehen. Hochladen oder
                      Entfernen ist nur mit Release-Media-Recht möglich.
                    </p>
                  ) : (
                    <div className={styles.fansubEditReleaseDrawerDropzone}>
                      <div className={styles.fansubEditThemeUploadHeader}>
                        <strong>Theme-Video hochladen</strong>
                        {drawerUploadStatusLabel ? (
                          <span className={styles.fansubEditThemeUploadMeta}>
                            {drawerUploadStatusLabel}
                          </span>
                        ) : null}
                      </div>
                      <input
                        ref={themeUploadInputRef}
                        className={styles.fansubEditThemeUploadInput}
                        type="file"
                        accept="video/*"
                        disabled={drawerBusy || !hasAuthSession}
                        onChange={handleThemeUploadInputChange}
                      />
