import { useMemo } from 'react'
import { Lock } from 'lucide-react'
import { Accordion } from '@/components/ui/Accordion'
import { Badge } from '@/components/ui/Badge'
import { Button } from '@/components/ui/Button'
import { Switch } from '@/components/ui/Switch'
import type { RoleEntry } from '@/types/admin-capability'
import { categoryDisplayLabel, sortCategories } from './capabilityCategories'

const membershipBaselineCodes = new Set([
  "fansub_group.members.view",
  "fansub_group_media.view",
  "fansub_group_media.upload",
])

// Exportiert ausschließlich für den Auseinanderdriften-Test gegen
// permissions.MembershipBaselineActionCodes (146-VERIFICATION.md, Kriterium 4-Nachtrag) --
// kein Produktionsverwendungszweck außerhalb dieser Datei.
export const membershipBaselineCodesForTest = membershipBaselineCodes

export interface RoleCapabilityDetailProps {
  role: RoleEntry
  /**
   * Ersetzt die vormals direkten onGrant/onRevoke-Mutationsaufrufe (Plan 138-13, D-18): ein
   * Switch-Toggle löst NIEMALS mehr eine sofortige Mutation aus, sondern fordert nur an, dass
   * der Parent (RoleCapabilityClient.tsx) den RoleCapabilityImpactPreviewModal für
   * (actionCode, add) öffnet -- die eigentliche Vergabe/Entziehung passiert erst nach einer
   * im Dialog bestätigten, resolver-gestützten Vorschau.
   */
  onRequestChange: (actionCode: string, add: boolean) => void
  /** Inline-Fehler (z.B. 422 role_not_assignable oder 409 lockout_guard). */
  inlineError: string | null
  /**
   * Controlled Accordion-Open-Zustand (Kategorie-IDs). Vom Parent gehalten,
   * damit eine aufgeklappte Kategorie nach einem Switch-Toggle / Daten-Refresh
   * offen bleibt.
   */
  openCategories: Set<string>
  onOpenCategoriesChange: (next: Set<string>) => void
}

/**
 * Kategorisierte Detail-Ansicht für eine Rolle (D-11/D-12).
 *
 * - Gruppiert actions nach category → je Kategorie ein Accordion-Item.
 * - Pro Capability eine Row mit Switch (checked = granted).
 * - Die historische Gründerrolle erhält keine konfigurierbaren Standardrechte.
 */
export function RoleCapabilityDetail({
  role,
  onRequestChange,
  inlineError,
  openCategories,
  onOpenCategoriesChange,
}: RoleCapabilityDetailProps) {
  const isEditable = role.capability_editable !== false
  const isReservedBaseline = role.role_kind === 'reserved_baseline'
  const configurableActions = isReservedBaseline
    ? role.actions.filter((action) => membershipBaselineCodes.has(action.code))
    : role.actions.filter((action) => !membershipBaselineCodes.has(action.code))

  const accordionItems = useMemo(() => {
    // Aktionen nach Kategorie gruppieren
    const byCategory = new Map<string, typeof role.actions>()
    for (const action of configurableActions) {
      const existing = byCategory.get(action.category) ?? []
      existing.push(action)
      byCategory.set(action.category, existing)
    }

    // Deterministische Reihenfolge (kanonische Kopie in capabilityCategories.ts, Quick 260824-ek3)
    const sortedCats = sortCategories([...byCategory.keys()])

    return sortedCats.map((cat) => {
      const actions = byCategory.get(cat) ?? []
      return {
        id: cat,
        title: categoryDisplayLabel(cat),
        children: (
          <div>
            {actions.map((action) => (
              <div
                key={action.code}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--space-3)',
                  padding: 'var(--space-2) var(--space-3)',
                  borderBottom: '1px solid var(--color-border)',
                  minHeight: '44px',
                }}
              >
                <span
                  style={{
                    fontSize: '0.875rem',
                    color: 'var(--color-text-primary)',
                    flex: 1,
                  }}
                >
                  {action.label_de}
                </span>
                {isReservedBaseline && membershipBaselineCodes.has(action.code) && (
                  <Badge variant="info" id={`baseline-protected-${action.code}`}>
                    <Lock size={16} aria-hidden="true" />
                    {' '}Geschützt
                    <span className="visually-hidden">
                      {' '}– Teil der Mitgliedschafts-Grundausstattung. Entziehen wird serverseitig abgelehnt,
                      da jedes aktive Mitglied dieses Recht automatisch benötigt.
                    </span>
                  </Badge>
                )}
                {action.standalone ? (
                  <span
                    style={{
                      fontSize: '0.75rem',
                      color: 'var(--color-text-secondary)',
                      fontStyle: 'italic',
                    }}
                  >
                    Systemaktion
                  </span>
                ) : (
                  <Switch
                    checked={action.granted}
                    disabled={!isEditable}
                    aria-label={action.label_de}
                    aria-describedby={
                      isReservedBaseline && membershipBaselineCodes.has(action.code)
                        ? `baseline-protected-${action.code}`
                        : undefined
                    }
                    onCheckedChange={(next) => {
                      if (!isEditable) return
                      // Kein sofortiges Speichern (D-18): nur den Impact-Preview-Dialog
                      // anfordern; `checked` bleibt bis zur bestätigten Mutation + Refresh
                      // unverändert (keine optimistische Vorab-Änderung, T-138-24).
                      onRequestChange(action.code, next)
                    }}
                  />
                )}
              </div>
            ))}
          </div>
        ),
      }
    })
  }, [configurableActions, isEditable, onRequestChange])

  return (
    <div>
      {/* Rollenüberschrift */}
      <div
        style={{
          marginBottom: 'var(--space-3)',
          paddingBottom: 'var(--space-2)',
          borderBottom: '1px solid var(--color-border)',
        }}
      >
        <h3
          style={{
            fontSize: '1rem',
            fontWeight: 600,
            color: 'var(--color-text-primary)',
            margin: 0,
          }}
        >
          {role.label_de}
        </h3>
        {!isEditable && (
          <p
            style={{
              fontSize: '0.8125rem',
              color: 'var(--color-text-secondary)',
              marginTop: 'var(--space-1)',
            }}
          >
            Keine Standardrechte: Beitrags- und historische Rollen sind Credits/Dokumentation. Zusatzrechte werden individuell je Mitglied vergeben.
          </p>
        )}
      </div>

      {isEditable && isReservedBaseline && (
        <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.8125rem', margin: '0 0 var(--space-3)' }}>
          Diese drei Rechte erhält jedes aktive Gruppenmitglied automatisch, unabhängig von seiner
          Rolle. Änderungen hier wirken sich sofort auf alle aktiven Mitglieder aller
          Fansub-Gruppen aus.
        </p>
      )}

      {isEditable && !isReservedBaseline && (
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 'var(--space-3)',
            flexWrap: 'wrap',
            margin: '0 0 var(--space-3)',
          }}
        >
          <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.8125rem', margin: 0 }}>
            Die Grundrechte aller aktiven Mitglieder (Mitglieder anzeigen, Gruppenmedien ansehen
            und hochladen) werden zentral über die Rolle „Mitgliedschafts-Grundausstattung“
            verwaltet.
          </p>
          <Button variant="ghost" size="sm" href="/admin/roles?role=group_member&tab=caps">
            Grundausstattung öffnen
          </Button>
        </div>
      )}

      {/* Inline-Fehler */}
      {inlineError && (
        <div
          role="alert"
          style={{
            padding: 'var(--space-3)',
            marginBottom: 'var(--space-3)',
            background: 'var(--color-danger-bg, #fef2f2)',
            border: '1px solid var(--color-danger-border, #fca5a5)',
            borderRadius: 'var(--radius-sm)',
            color: 'var(--color-danger, #dc2626)',
            fontSize: '0.875rem',
          }}
        >
          {inlineError}
        </div>
      )}

      {!isEditable ? (
        <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.875rem' }}>
          Für diese Rolle gibt es keine konfigurierbaren Standardrechte.
        </p>
      ) : accordionItems.length === 0 ? (
        <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.875rem' }}>
          Keine Capabilities für diese Rolle.
        </p>
      ) : (
        <Accordion
          items={accordionItems}
          mode="multi"
          openIds={openCategories}
          onOpenChange={onOpenCategoriesChange}
        />
      )}
    </div>
  )
}

import { Button, TableCell, TableRow } from '@/components/ui'
import type { EffectiveRightState, RoleCapabilityMatrix } from '@/types/admin-capability'
import { CapabilityHistoryPanel } from './CapabilityHistoryPanel'
import { isReviewDelegationAction, roleLabelFor } from './userGroupRightsHelpers'

export function CapabilityDetailRow({
  groupId,
  appUserId,
  label,
  state,
  matrix,
  onOpenRevoke,
  onOpenGrant,
}: {
  groupId: number
  appUserId: number
  label: string
  state: EffectiveRightState
  matrix: RoleCapabilityMatrix | null
  onOpenRevoke: (state: EffectiveRightState, label: string) => void
  onOpenGrant: (state: EffectiveRightState, label: string) => void
}) {
  // D-15/D-16: nur die vier gesperrten Business-Verben, nie ein rohes Allow/Deny-Switch.
  const showRevoke = state.allowed && !state.non_deniable
  const showGrant = !state.allowed && !isReviewDelegationAction(state.action_code)
  const showRemoveOverride = state.user_allow || state.user_deny

  return (
    <TableRow>
      <TableCell colSpan={3}>
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--space-2)',
            padding: 'var(--space-2) 0',
            fontSize: '0.8125rem',
            color: 'var(--color-text-secondary)',
          }}
        >
          <div>
            <strong>Rollenquellen:</strong>{' '}
            {state.granting_roles.length > 0
              ? state.granting_roles.map((role) => roleLabelFor(role, matrix)).join(', ')
              : '–'}
          </div>
          <div>
            <strong>Spezialisierte Grants:</strong>{' '}
            {state.specialized_grants.length > 0 ? state.specialized_grants.join(', ') : '–'}
          </div>
          <div>
            <strong>Persönlich zusätzlich erlaubt:</strong> {state.user_allow ? 'Ja' : 'Nein'}
          </div>
          <div>
            <strong>Persönlich entzogen:</strong> {state.user_deny ? 'Ja' : 'Nein'}
          </div>
          <div>
            <strong>Nicht entziehbar (non-deniable):</strong> {state.non_deniable ? 'Ja' : 'Nein'}
          </div>
          <div>
            <strong>Reason-Code:</strong> {state.reason_code || '–'}
          </div>

          <div style={{ display: 'flex', gap: 'var(--space-2)', flexWrap: 'wrap' }}>
            {showRevoke && (
              <Button variant="secondary" size="sm" onClick={() => onOpenRevoke(state, label)}>
                Recht entziehen
              </Button>
            )}
            {showGrant && (
              <Button variant="secondary" size="sm" onClick={() => onOpenGrant(state, label)}>
                Recht zusätzlich erlauben
              </Button>
            )}
            {!state.allowed && isReviewDelegationAction(state.action_code) && (
              <div style={{ fontSize: '0.8125rem', color: 'var(--color-text-secondary)' }}>
                Gewähren nur über „Prüf-/Freigabe-Rechte" oben.
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => document.getElementById('review-delegation-section')?.scrollIntoView({ behavior: 'smooth' })}
                >
                  Zu Prüf-/Freigabe-Rechte springen
                </Button>
              </div>
            )}
            {showRemoveOverride &&
              (state.user_deny ? (
                <Button variant="ghost" size="sm" onClick={() => onOpenRevoke(state, label)}>
                  Abweichung entfernen
                </Button>
              ) : (
                <Button variant="ghost" size="sm" onClick={() => onOpenGrant(state, label)}>
                  Abweichung entfernen
                </Button>
              ))}
          </div>

          <div style={{ marginTop: 'var(--space-2)' }}>
            <CapabilityHistoryPanel
              fansubGroupId={groupId}
              appUserId={appUserId}
              actionCode={state.action_code}
            />
          </div>
        </div>
      </TableCell>
    </TableRow>
  )
}

'use client'

import { useEffect, useState } from 'react'

import { EmptyState, ErrorState, LoadingState, Table, TableBody, TableCell, TableHead, TableHeaderCell, TableRow } from '@/components/ui'
import { ApiError, listOverrideHistory as fetchOverrideHistory } from '@/lib/api'
import type { CapabilityOverrideAuditItem } from '@/types/admin-capability'

/**
 * Inline per-capability override history (D-13b, CAP-08 companion): a compact list scoped to
 * ONE capability in ONE group's context, rendered directly in the row-expansion area next to
 * the guided grant/revoke actions. This supplements, never replaces, the later central
 * "Änderungen" workspace (D-13b) -- fetches a small page only.
 */

const REASON_CATEGORY_LABEL: Record<string, string> = {
  task_delegation: 'Aufgabenübertragung',
  security_measure: 'Sicherheitsmaßnahme',
  role_gap: 'Rollen-Lücke',
}

function reasonLabel(item: CapabilityOverrideAuditItem): string {
  if (!item.reason) return '–'
  if (item.reason.category === 'other') {
    return item.reason.text || 'Sonstiger Grund'
  }
  return REASON_CATEGORY_LABEL[item.reason.category] ?? item.reason.category
}

function effectLabel(state: CapabilityOverrideAuditItem['before' | 'after']): string {
  if (!state) return '–'
  return state.effect === 'allow' ? 'Erlaubt' : 'Entzogen'
}

function formatOccurredAt(value: string): string {
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) return value
  return parsed.toLocaleString('de-DE')
}

export interface CapabilityHistoryPanelProps {
  fansubGroupId: number
  appUserId: number
  actionCode: string
}

export function CapabilityHistoryPanel({ fansubGroupId, appUserId, actionCode }: CapabilityHistoryPanelProps) {
  const [entries, setEntries] = useState<CapabilityOverrideAuditItem[] | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    setIsLoading(true)
    setError(null)
    fetchOverrideHistory(fansubGroupId, appUserId, 10, 0)
      .then((result) => {
        if (cancelled) return
        // Eine gruppen-weite Historie-Seite kann auch Einträge anderer Capabilities enthalten --
        // dieses Panel ist strikt auf EINE Capability skopiert (D-13b).
        setEntries(result.filter((entry) => entry.action_code === actionCode))
      })
      .catch((err) => {
        if (cancelled) return
        setError(err instanceof ApiError ? err.message : 'Historie konnte nicht geladen werden.')
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [fansubGroupId, appUserId, actionCode])

  if (isLoading) {
    return <LoadingState title="Historie wird geladen …" description="" />
  }
  if (error) {
    return <ErrorState title="Fehler beim Laden der Historie" description={error} />
  }
  if (!entries || entries.length === 0) {
    return <EmptyState variant="compact" title="Keine Änderungen für dieses Recht." description="" />
  }

  return (
    <Table variant="compact">
      <TableHead>
        <TableRow>
          <TableHeaderCell>Vorher</TableHeaderCell>
          <TableHeaderCell>Nachher</TableHeaderCell>
          <TableHeaderCell>Grund</TableHeaderCell>
          <TableHeaderCell>Zeitpunkt</TableHeaderCell>
          <TableHeaderCell>Akteur</TableHeaderCell>
        </TableRow>
      </TableHead>
      <TableBody>
        {entries.map((entry) => (
          <TableRow key={entry.id}>
            <TableCell>{effectLabel(entry.before)}</TableCell>
            <TableCell>{effectLabel(entry.after)}</TableCell>
            <TableCell>{reasonLabel(entry)}</TableCell>
            <TableCell>{formatOccurredAt(entry.occurred_at)}</TableCell>
            <TableCell>{entry.actor_user_id}</TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  )
}

'use client'

import { useEffect, useId, useMemo, useState } from 'react'

import { ActivationStatusIndicator, Button, FormField, Modal, Select, Textarea } from '@/components/ui'
import { ApiError, mutateCapabilityOverride } from '@/lib/api'
import type {
  CapabilityOverrideMutationResult,
  CapabilityOverrideReason,
  EffectiveRightState,
  RoleCapabilityMatrix,
} from '@/types/admin-capability'
import { roleLabelFor } from './userGroupRightsHelpers'

/**
 * Guided "Recht entziehen" flow (CAP-08, D-16, D-17, UI-SPEC.md Section E).
 *
 * Honestly explains every granting source BEFORE recommending a scoped deny override, never
 * offers a fake action for a non-deniable capability (D-17: explanation replaces the action,
 * never a disabled button), and reuses the same component for the simpler "Abweichung
 * entfernen" reversion path when a personal deny override already exists (D-16) -- no fourth
 * file, per 138-08-PLAN.md's binding scope note.
 */

type ReasonCategory = 'task_delegation' | 'security_measure' | 'role_gap' | 'other'

const REASON_OPTIONS: { value: ReasonCategory; label: string }[] = [
  { value: 'task_delegation', label: 'Aufgabenübertragung' },
  { value: 'security_measure', label: 'Sicherheitsmaßnahme' },
  { value: 'role_gap', label: 'Rollen-Lücke' },
  { value: 'other', label: 'Sonstiger Grund' },
]

type FlowStep = 'sources' | 'confirm' | 'status'

export interface GuidedRevokeFlowProps {
  open: boolean
  onClose: () => void
  fansubGroupId: number
  fansubGroupName: string
  appUserId: number
  appUserDisplayName: string
  actionCode: string
  actionLabel: string
  state: EffectiveRightState
  /** Bereits geladene Capability-Matrix (kein zusätzlicher Fetch, Pattern aus 138-08-PLAN.md). */
  matrix: RoleCapabilityMatrix | null
  onMutated: (result: CapabilityOverrideMutationResult) => void
}

/**
 * Ob eine Rolle im bekannten, aktiven fansub_group-Rollenkatalog steht (Frontend-Spiegel von
 * permissions.IsKnownFansubGroupRole, gegen die bereits geladene Matrix statt eines neuen
 * Backend-Calls). Alles andere (z. B. eine reine anime_contribution-Rolle wie encoder) kann
 * durch eine persönliche Abweichung dieses Users NICHT entzogen werden (138-RESEARCH.md
 * Pitfall 5) -- ohne Matrix wird konservativ "bekannt" angenommen, um keine falschen
 * Warnungen zu erzeugen.
 */
function isFansubGroupCatalogRole(roleCode: string, matrix: RoleCapabilityMatrix | null): boolean {
  if (!matrix) return true
  return matrix.roles.some(
    (role) =>
      role.role_code === roleCode &&
      role.role_kind !== 'global_app_role' &&
      (role.contexts ?? []).includes('fansub_group'),
  )
}

export function GuidedRevokeFlow({
  open,
  onClose,
  fansubGroupId,
  fansubGroupName,
  appUserId,
  appUserDisplayName,
  actionCode,
  actionLabel,
  state,
  matrix,
  onMutated,
}: GuidedRevokeFlowProps) {
  const reasonCategoryId = useId()
  const reasonTextId = useId()

  const isRemoveMode = state.user_deny === true
  const isNonDeniable = state.non_deniable === true

  const [step, setStep] = useState<FlowStep>(isRemoveMode ? 'confirm' : 'sources')
  const [reasonCategory, setReasonCategory] = useState<ReasonCategory>('task_delegation')
  const [reasonText, setReasonText] = useState('')
  const [isMutating, setIsMutating] = useState(false)
  const [mutationError, setMutationError] = useState<string | null>(null)
  const [mutationResult, setMutationResult] = useState<CapabilityOverrideMutationResult | null>(null)

  useEffect(() => {
    if (!open) return
    setStep(isRemoveMode ? 'confirm' : 'sources')
    setReasonCategory('task_delegation')
    setReasonText('')
    setIsMutating(false)
    setMutationError(null)
    setMutationResult(null)
    // Re-initialisieren, wenn ein anderes (Gruppe, Aktion, Nutzer)-Tripel geöffnet wird.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, actionCode, fansubGroupId, appUserId, isRemoveMode])

  const flaggedSources = useMemo(
    () =>
      state.granting_roles.map((role) => ({
        role,
        contributionRoleOnly: !isFansubGroupCatalogRole(role, matrix),
      })),
    [state.granting_roles, matrix],
  )

  const reasonValid = reasonCategory !== 'other' || reasonText.trim().length > 0

  async function handleConfirm() {
    setIsMutating(true)
    setMutationError(null)
    try {
      const reason: CapabilityOverrideReason =
        reasonCategory === 'other'
          ? { category: 'other', text: reasonText.trim() }
          : { category: reasonCategory, text: reasonText.trim() || null }

      const result = await mutateCapabilityOverride(fansubGroupId, appUserId, {
        group_id: fansubGroupId,
        target_user_id: appUserId,
        action_code: actionCode,
        effect: isRemoveMode ? null : 'deny',
        reason,
      })

      setMutationResult(result)
      onMutated(result)
      setStep('status')
    } catch (err) {
      setMutationError(
        err instanceof ApiError ? err.message : 'Änderung konnte nicht gespeichert werden.',
      )
    } finally {
      setIsMutating(false)
    }
  }

  const title = isRemoveMode
    ? `Abweichung entfernen: ${actionLabel}`
    : `Recht entziehen: ${actionLabel}`

  // D-17: für ein nicht entziehbares Recht ersetzt die Erklärung die gesamte Aktion -- es wird
  // gar kein Bestätigungs-Button gerendert (auch kein deaktivierter), Modal.tsx's Standard-
  // "Schließen"-Footer bleibt die einzige Aktion. Ausnahme (D-16): existiert bereits ein
  // persönlicher user_deny (isRemoveMode), bleibt der Entfernungs-Pfad erreichbar, auch wenn
  // das Recht aktuell über eine nicht überschreibbare Quelle gewährt wird -- das Entfernen der
  // veralteten Abweichung ist eine andere Operation als ein neues Entziehen.
  if (isNonDeniable && !isRemoveMode) {
    return (
      <Modal open={open} onClose={onClose} title={title} size="md">
        <p>
          Dieses Recht kann für {appUserDisplayName} nicht persönlich entzogen werden. Es wird
          direkt durch{' '}
          {state.granting_roles.map((role) => roleLabelFor(role, matrix)).join(', ') ||
            decisiveSourceFallback(state)}{' '}
          gewährt und ist nicht überschreibbar.
        </p>
      </Modal>
    )
  }

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={title}
      size="md"
      footer={
        step === 'sources' ? (
          <div style={{ display: 'flex', gap: 'var(--space-2)', justifyContent: 'flex-end' }}>
            <Button variant="secondary" onClick={onClose}>
              Abbrechen
            </Button>
            <Button variant="primary" onClick={() => setStep('confirm')}>
              Weiter
            </Button>
          </div>
        ) : step === 'confirm' ? (
          <div style={{ display: 'flex', gap: 'var(--space-2)', justifyContent: 'flex-end' }}>
            <Button variant="secondary" onClick={onClose} disabled={isMutating}>
              Abbrechen
            </Button>
            <Button
              variant={isRemoveMode ? 'primary' : 'danger'}
              onClick={handleConfirm}
              disabled={isMutating || !reasonValid}
            >
              {isMutating
                ? 'Wird verarbeitet …'
                : isRemoveMode
                  ? 'Abweichung entfernen'
                  : 'Recht entziehen'}
            </Button>
          </div>
        ) : (
          <Button variant="secondary" onClick={onClose}>
            Schließen
          </Button>
        )
      }
    >
      {step === 'sources' && (
        <p>
          Dieses Recht wird aktuell gewährt durch:{' '}
          {flaggedSources.length > 0
            ? flaggedSources
                .map(({ role, contributionRoleOnly }) =>
                  contributionRoleOnly
                    ? `${roleLabelFor(role, matrix)} (kann durch eine persönliche Abweichung nicht entzogen werden)`
                    : roleLabelFor(role, matrix),
                )
                .join(', ')
            : '–'}
          . Das Entfernen nur einer dieser Rollen würde das Recht nicht vollständig entziehen.
          Empfohlen: Persönliche Abweichung für diesen Benutzer in {fansubGroupName} setzen.
        </p>
      )}

      {step === 'confirm' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
          {isRemoveMode ? (
            <p>
              Die persönliche Abweichung für {actionLabel} wird entfernt -- danach gilt wieder das
              normale Ergebnis aus Rollen und sonstigen Quellen.
            </p>
          ) : (
            <p>
              Empfohlen: Persönliche Abweichung für diesen Benutzer in {fansubGroupName} setzen.
              Nachher: {actionLabel} nicht mehr erlaubt.
            </p>
          )}

          <FormField label="Grund" htmlFor={reasonCategoryId} required>
            <Select
              id={reasonCategoryId}
              value={reasonCategory}
              onChange={(event) => setReasonCategory(event.target.value as ReasonCategory)}
            >
              {REASON_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </Select>
          </FormField>

          {reasonCategory === 'other' && (
            <FormField label="Begründung" htmlFor={reasonTextId} required>
              <Textarea
                id={reasonTextId}
                value={reasonText}
                onChange={(event) => setReasonText(event.target.value)}
                rows={3}
              />
            </FormField>
          )}

          {mutationError && (
            <p role="alert" style={{ color: 'var(--color-error)' }}>
              {mutationError}
            </p>
          )}
        </div>
      )}

      {step === 'status' && mutationResult && (
        <ActivationStatusIndicator path="override" activationStatus={mutationResult.activation_status} />
      )}
    </Modal>
  )
}

function decisiveSourceFallback(state: EffectiveRightState): string {
  switch (state.decisive_source) {
    case 'platform_admin':
      return 'Plattform-Admin'
    case 'membership_baseline':
      return 'dem Mitglieds-Grundrecht'
    case 'specialized_grant':
      return state.specialized_grants.join(', ') || 'einer spezialisierten Vergabe'
    default:
      return state.decisive_source
  }
}

