'use client'

import Link from 'next/link'
import Image from 'next/image'
import { notFound, useRouter, useSearchParams } from 'next/navigation'
import { Play, X } from 'lucide-react'
import { useEffect, useState, useCallback } from 'react'

import { Breadcrumbs } from '@/components/navigation/Breadcrumbs'
import { GroupEdgeNavigation } from '@/components/groups/GroupEdgeNavigation'
import { Pagination } from '@/components/anime/Pagination'
import { buildGroupNavigationGroups } from '@/lib/groupNavigation'
import { getGroupReleases, getAnimeByID, getAnimeFansubs, ApiError } from '@/lib/api'

import styles from './page.module.css'

interface GroupReleasesPageProps {
  params:
    | {
        id: string
        groupId: string
      }
    | Promise<{
        id: string
        groupId: string
      }>
  searchParams?:
    | {
        page?: string | string[]
        per_page?: string | string[]
        has_op?: string | string[]
        has_ed?: string | string[]
        has_karaoke?: string | string[]
        q?: string | string[]
      }
    | Promise<{
        page?: string | string[]
        per_page?: string | string[]
        has_op?: string | string[]
        has_ed?: string | string[]
        has_karaoke?: string | string[]
        q?: string | string[]
      }>
}

type Anime = {
  id: number
  title: string
}

type Group = {
  fansub: {
    id: number
    name: string
    slug: string
    logo_url?: string | null
  }
}

type Episode = {
  id: number
  episode_id?: number | null
  episode_number: number
  title?: string | null
  version_label?: string | null
  thumbnail_url?: string | null
  has_op: boolean
  has_ed: boolean
  karaoke_count: number
  insert_count: number
  screenshot_count: number
  released_at?: string | null
}

type OtherGroup = {
  id: number
  name: string
  slug: string
  logo_url?: string | null
  episode_count?: number
}

type Meta = {
  page: number
  per_page: number
  total: number
  total_pages: number
}

export default function GroupReleasesPage({ params }: GroupReleasesPageProps) {
  const router = useRouter()
  const urlSearchParams = useSearchParams()

  const [animeID, setAnimeID] = useState<number | null>(null)
  const [groupID, setGroupID] = useState<number | null>(null)
  const [anime, setAnime] = useState<Anime | null>(null)
  const [group, setGroup] = useState<Group | null>(null)
  const [episodes, setEpisodes] = useState<Episode[]>([])
  const [navigationGroups, setNavigationGroups] = useState<OtherGroup[]>([])
  const [meta, setMeta] = useState<Meta | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)

  const [searchTerm, setSearchTerm] = useState('')
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('')
  const [isSticky, setIsSticky] = useState(false)

  const hasOpParam = urlSearchParams.get('has_op') === 'true'
  const hasEdParam = urlSearchParams.get('has_ed') === 'true'
  const hasKaraokeParam = urlSearchParams.get('has_karaoke') === 'true'
  const queryParam = urlSearchParams.get('q') || ''
  const pageParam = Number.parseInt(urlSearchParams.get('page') || '1', 10)

  const [filterOp, setFilterOp] = useState(hasOpParam)
  const [filterEd, setFilterEd] = useState(hasEdParam)
  const [filterKaraoke, setFilterKaraoke] = useState(hasKaraokeParam)

  const otherGroups = navigationGroups.filter((item) => item.id !== groupID)

  useEffect(() => {
    async function resolveParams() {
      const resolvedParams = await params
      const id = Number.parseInt(resolvedParams.id, 10)
      const gid = Number.parseInt(resolvedParams.groupId, 10)

      if (Number.isNaN(id) || id <= 0 || Number.isNaN(gid) || gid <= 0) {
        notFound()
      }

      setAnimeID(id)
      setGroupID(gid)
    }
    resolveParams()
  }, [params])

  useEffect(() => {
    setSearchTerm(queryParam)
    setDebouncedSearchTerm(queryParam)
  }, [queryParam])

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearchTerm(searchTerm)
    }, 300)
    return () => clearTimeout(timer)
  }, [searchTerm])

  const updateURL = useCallback(
    (updates: Record<string, string | boolean | undefined>) => {
      if (!animeID || !groupID) return

      const params = new URLSearchParams(urlSearchParams.toString())

      Object.entries(updates).forEach(([key, value]) => {
        if (value === undefined || value === false || value === '') {
          params.delete(key)
        } else {
          params.set(key, String(value))
        }
      })

      params.delete('page')

      const queryString = params.toString()
      const newURL = `/anime/${animeID}/group/${groupID}/releases${queryString ? `?${queryString}` : ''}`
      router.push(newURL)
    },
    [animeID, groupID, router, urlSearchParams]
  )

  useEffect(() => {
    if (debouncedSearchTerm !== queryParam) {
      updateURL({ q: debouncedSearchTerm || undefined })
    }
  }, [debouncedSearchTerm, queryParam, updateURL])

  const toggleFilter = useCallback(
    (filter: 'op' | 'ed' | 'karaoke') => {
      const updates: Record<string, boolean | undefined> = {}

      switch (filter) {
        case 'op':
          updates.has_op = !filterOp || undefined
          setFilterOp(!filterOp)
          break
        case 'ed':
          updates.has_ed = !filterEd || undefined
          setFilterEd(!filterEd)
          break
        case 'karaoke':
          updates.has_karaoke = !filterKaraoke || undefined
          setFilterKaraoke(!filterKaraoke)
          break
      }

      updateURL(updates)
    },
    [filterOp, filterEd, filterKaraoke, updateURL]
  )

  const resetFilters = useCallback(() => {
    setFilterOp(false)
    setFilterEd(false)
    setFilterKaraoke(false)
    setSearchTerm('')
    setDebouncedSearchTerm('')
    router.push(`/anime/${animeID}/group/${groupID}/releases`)
  }, [animeID, groupID, router])

  const anyFilterActive = filterOp || filterEd || filterKaraoke || debouncedSearchTerm

  const toggleAll = useCallback(() => {
    setFilterOp(false)
    setFilterEd(false)
    setFilterKaraoke(false)
    updateURL({ has_op: undefined, has_ed: undefined, has_karaoke: undefined, q: debouncedSearchTerm || undefined })
  }, [debouncedSearchTerm, updateURL])

  useEffect(() => {
    async function fetchData() {
      if (!animeID || !groupID) return

      setIsLoading(true)
      setErrorMessage(null)

      try {
        const [releasesResponse, animeResponse, animeFansubsResponse] = await Promise.all([
          getGroupReleases(animeID, groupID, {
            page: pageParam,
            per_page: 20,
            has_op: filterOp || undefined,
            has_ed: filterEd || undefined,
            has_karaoke: filterKaraoke || undefined,
            q: debouncedSearchTerm || undefined,
          }),
          getAnimeByID(animeID),
          getAnimeFansubs(animeID).catch(() => null),
        ])

        setGroup(releasesResponse.data.group)
        setEpisodes(releasesResponse.data.episodes)
        setNavigationGroups(
          buildGroupNavigationGroups({
            currentGroup: releasesResponse.data.group.fansub,
            fallbackOtherGroups: releasesResponse.data.other_groups,
            animeFansubRelations: animeFansubsResponse?.data ?? null,
          })
        )
        setMeta(releasesResponse.meta)
        setAnime(animeResponse.data)
      } catch (error) {
        if (error instanceof ApiError && error.status === 404) {
          notFound()
        }
        setErrorMessage('Releases konnten nicht geladen werden.')
      } finally {
        setIsLoading(false)
      }
    }

    fetchData()
  }, [animeID, groupID, pageParam, filterOp, filterEd, filterKaraoke, debouncedSearchTerm])

  useEffect(() => {
    const handleScroll = () => {
      const filterBar = document.getElementById('filterBar')
      if (filterBar) {
        const rect = filterBar.getBoundingClientRect()
        setIsSticky(rect.top <= 0)
      }
    }

    window.addEventListener('scroll', handleScroll)
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  if (!animeID || !groupID) {
    return null
  }

  if (errorMessage && !anime) {
    return (
      <main className={styles.page}>
        <p className={styles.backLink}>
          <Link href={`/anime/${animeID}`}>Zurück zum Anime</Link>
        </p>
        <div className={styles.errorBox}>{errorMessage}</div>
      </main>
    )
  }

  if (isLoading && !anime) {
    return (
      <main className={styles.page}>
        <p className={styles.backLink}>
          <Link href={`/anime/${animeID}`}>Zurück zum Anime</Link>
        </p>
        <div className={styles.loadingState}>Lädt...</div>
      </main>
    )
  }

  const breadcrumbItems = anime
    ? [
        { label: 'Anime', href: '/anime' },
        { label: anime.title, href: `/anime/${animeID}` },
        { label: 'Gruppe', href: `/anime/${animeID}/group/${groupID}` },
        { label: 'Releases' },
      ]
    : []

  return (
    <main className={styles.page}>
      {breadcrumbItems.length > 0 && <Breadcrumbs items={breadcrumbItems} />}

      <p className={styles.backLink}>
        <Link href={`/anime/${animeID}/group/${groupID}`}>Zurück zur Gruppenübersicht</Link>
      </p>

      {group && anime && (
        <>
          <section className={styles.heroShell}>
            <section className={styles.header}>
              <div className={styles.headerContent}>
                {group.fansub.logo_url ? (
                  <Image
                    src={group.fansub.logo_url}
                    alt={group.fansub.name}
                    width={60}
                    height={60}
                    className={styles.logo}
                  />
                ) : (
                  <div className={styles.logoPlaceholder}>
                    <span className={styles.logoInitial}>{group.fansub.name.charAt(0).toUpperCase()}</span>
                  </div>
                )}
                <div>
                  <h1 className={styles.title}>{group.fansub.name} Releases</h1>
                  <p className={styles.subtitle}>{anime.title}</p>
                </div>
              </div>
            </section>
            {navigationGroups.length > 1 ? (
              <GroupEdgeNavigation
                currentGroupId={groupID}
                animeId={animeID}
                animeTitle={anime.title}
                otherGroups={navigationGroups}
                mode="releases"
              />
            ) : null}
          </section>

          <section id="filterBar" className={`${styles.filterBar} ${isSticky ? styles.filterBarSticky : ''}`}>
            <div className={styles.filterChips}>
              <button
                type="button"
                className={`${styles.chip} ${!anyFilterActive ? styles.chipActive : styles.chipInactive}`}
                onClick={toggleAll}
                aria-pressed={!anyFilterActive}
              >
                Alle
              </button>
              <button
                type="button"
                className={`${styles.chip} ${filterOp ? styles.chipActive : styles.chipInactive}`}
                onClick={() => toggleFilter('op')}
                aria-pressed={filterOp}
              >
                Mit OP
              </button>
              <button
                type="button"
                className={`${styles.chip} ${filterEd ? styles.chipActive : styles.chipInactive}`}
                onClick={() => toggleFilter('ed')}
                aria-pressed={filterEd}
              >
                Mit ED
              </button>
              <button
                type="button"
                className={`${styles.chip} ${filterKaraoke ? styles.chipActive : styles.chipInactive}`}
                onClick={() => toggleFilter('karaoke')}
                aria-pressed={filterKaraoke}
              >
                Mit Karaoke
              </button>
            </div>
            <div className={styles.searchContainer}>
              <input
                type="text"
                className={styles.searchInput}
                placeholder="Suche..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                aria-label="Suche nach Releases"
              />
              {searchTerm && (
                <button
                  type="button"
                  className={styles.clearButton}
                  onClick={() => {
                    setSearchTerm('')
                    setDebouncedSearchTerm('')
                    updateURL({ q: undefined })
                  }}
                  aria-label="Suche löschen"
                >
                  <X size={16} />
                </button>
              )}
            </div>
          </section>

          <section className={styles.releasesSection}>
            {otherGroups.length > 0 ? (
              <div className={styles.otherGroupsSection}>
                <p className={styles.otherGroupsLabel}>Weitere Gruppen zu diesem Anime</p>
                <div className={styles.otherGroupsScroller} aria-label="Weitere Fansub-Gruppen">
                  {otherGroups.map((otherGroup) => (
                    <Link
                      key={otherGroup.id}
                      href={`/anime/${animeID}/group/${otherGroup.id}/releases`}
                      className={styles.otherGroupChip}
                    >
                      {otherGroup.logo_url ? (
                        <Image
                          src={otherGroup.logo_url}
                          alt={otherGroup.name}
                          width={22}
                          height={22}
                          className={styles.otherGroupLogo}
                        />
                      ) : (
                        <span className={styles.otherGroupInitial} aria-hidden="true">
                          {otherGroup.name.charAt(0).toUpperCase()}
                        </span>
                      )}
                      <span className={styles.otherGroupName}>{otherGroup.name}</span>
                    </Link>
                  ))}
                </div>
              </div>
            ) : null}

            {meta && (
              <div className={styles.releasesMeta}>
                <p className={styles.releasesCount}>
                  {meta.total} {meta.total === 1 ? 'Release' : 'Releases'}
                </p>
              </div>
            )}

            {isLoading ? (
              <div className={styles.loadingState}>Lädt...</div>
            ) : episodes.length === 0 ? (
              <div className={styles.emptyState}>
                <p className={styles.emptyStateText}>Keine Releases vorhanden.</p>
                {anyFilterActive && (
                  <button type="button" className={styles.resetButton} onClick={resetFilters}>
                    Filter zurücksetzen
                  </button>
                )}
              </div>
            ) : (
              <div className={styles.releaseGrid}>
                {episodes.map((episode) =>
                  episode.episode_id ? (
                    <Link
                      key={episode.id}
                      href={`/episodes/${episode.episode_id}?releaseId=${episode.id}&animeId=${animeID}&groupId=${groupID}`}
                      className={styles.releaseCard}
                      aria-label={`Episode ${episode.episode_number}${episode.title ? `: ${episode.title}` : ''}`}
                    >
                      <article>
                        {episode.thumbnail_url ? (
                          <div className={styles.thumbnail}>
                            <Image
                              src={episode.thumbnail_url}
                              alt={episode.title ?? `Episode ${episode.episode_number}`}
                              width={320}
                              height={180}
                              className={styles.thumbnailImage}
                            />
                            <div className={styles.playOverlay}>
                              <Play size={32} />
                            </div>
                          </div>
                        ) : (
                          <div className={styles.thumbnailPlaceholder}>
                            <Play size={32} />
                          </div>
                        )}
                        <div className={styles.releaseInfo}>
                          <h3 className={styles.episodeTitle}>
                            Episode {episode.episode_number}
                            {episode.title ? `: ${episode.title}` : ''}
                          </h3>
                          {episode.version_label ? (
                            <p className={styles.releaseDate}>{episode.version_label}</p>
                          ) : null}
                          {episode.released_at ? (
                            <p className={styles.releaseDate}>
                              {new Date(episode.released_at).toLocaleDateString('de-DE')}
                            </p>
                          ) : null}
                        </div>
                      </article>
                    </Link>
                  ) : (
                    <article key={episode.id} className={styles.releaseCard} aria-label={`Episode ${episode.episode_number}`}>
                      {episode.thumbnail_url ? (
                        <div className={styles.thumbnail}>
                          <Image
                            src={episode.thumbnail_url}
                            alt={episode.title ?? `Episode ${episode.episode_number}`}
                            width={320}
                            height={180}
                            className={styles.thumbnailImage}
                          />
                        </div>
                      ) : (
                        <div className={styles.thumbnailPlaceholder}>
                          <Play size={32} />
                        </div>
                      )}
                      <div className={styles.releaseInfo}>
                        <h3 className={styles.episodeTitle}>
                          Episode {episode.episode_number}
                          {episode.title ? `: ${episode.title}` : ''}
                        </h3>
                        {episode.version_label ? (
                          <p className={styles.releaseDate}>{episode.version_label}</p>
                        ) : null}
                        <p className={styles.releaseDate}>Episode-Route nicht verfügbar.</p>
                      </div>
                    </article>
                  )
                )}
              </div>
            )}

            {meta && meta.total_pages > 1 ? (
              <Pagination
                currentPage={meta.page}
                totalPages={meta.total_pages}
                baseUrl={`/anime/${animeID}/group/${groupID}/releases`}
              />
            ) : null}
          </section>
        </>
      )}
    </main>
  )
}

import Link from "next/link";

import { Badge, Card, SectionHeader } from "@/components/ui";
import { getGroupReleaseDetail } from "@/lib/api";
import { buildFansubReleaseHref } from "@/lib/fansubProjectRoutes";
import { CATEGORY_LABELS } from "@/types/releaseVersionMedia";

import styles from "./LatestReleaseSection.module.css";

interface LatestReleaseSectionProps {
  animeID: number;
  groupID: number;
  releaseVersionID: number;
  canonicalProjectPath?: string | null;
}

const MAX_IMAGE_PREVIEWS = 4;
const MAX_TEXT_PREVIEWS = 2;
const NOTE_EXCERPT_LENGTH = 160;

/** Entfernt HTML-Tags und kuerzt einen TipTap-body_html-Text fuer die kompakte Vorschau. */
function toNoteExcerpt(bodyHtml: string): string {
  const plain = bodyHtml.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
  return plain.length > NOTE_EXCERPT_LENGTH ? `${plain.slice(0, NOTE_EXCERPT_LENGTH)}…` : plain;
}

function formatReleaseDate(releaseDate: string | null): string | null {
  if (!releaseDate) return null;
  const parsed = new Date(releaseDate);
  if (Number.isNaN(parsed.getTime())) return releaseDate;
  return parsed.toLocaleDateString("de-DE", { year: "numeric", month: "long", day: "numeric" });
}

/**
 * AO4-11: eingebettete Vorschau des neuesten Release auf der Projektseite.
 * Laedt das aggregierte Payload selbst ueber getGroupReleaseDetail (AO4-02).
 * KEIN Infinite Scroll hier (AO4-21) — vollstaendige Galerie/Textliste liegt
 * auf der Release-Detailseite (99-12+).
 */
export async function LatestReleaseSection({ animeID, groupID, releaseVersionID, canonicalProjectPath }: LatestReleaseSectionProps) {
  let detail: Awaited<ReturnType<typeof getGroupReleaseDetail>> | null = null;
  try {
    detail = await getGroupReleaseDetail(animeID, groupID, releaseVersionID);
  } catch {
    // AO4-14: kein technischer Fehlertext im oeffentlichen UI — Sektion einfach ausblenden.
    return null;
  }

  const previewImages = detail.images.slice(0, MAX_IMAGE_PREVIEWS);
  const remainingImages = Math.max(detail.images_count - previewImages.length, 0);
  const previewNotes = detail.notes.slice(0, MAX_TEXT_PREVIEWS);
  const releaseDateLabel = formatReleaseDate(detail.release_date);
  const detailHref = buildFansubReleaseHref({ animeID, groupID, releaseVersionID, canonicalProjectPath });

  return (
    <div id="neuestes-release" className={styles.section}>
      <SectionHeader title="Neuestes Release" />
      <Card variant="section" className={styles.card}>
        <div className={styles.head}>
          <h3 className={styles.title}>{detail.title}</h3>
          {releaseDateLabel ? <span className={styles.date}>{releaseDateLabel}</span> : null}
        </div>

        <div className={styles.stats}>
          <span className={styles.statItem}>{detail.images_count} Bilder</span>
          <span className={styles.statItem}>{detail.notes_count} Texte</span>
          <span className={styles.statItem}>{detail.contributors_count} Fansubber</span>
        </div>

        {previewImages.length > 0 ? (
          <div className={styles.imageGrid}>
            {previewImages.map((image) => (
              <div key={image.id} className={styles.imageTile}>
                {image.thumbnail_url ? (
                  <img
                    src={image.thumbnail_url}
                    srcSet={
                      image.original_url
                        ? `${image.thumbnail_url} 320w, ${image.original_url} 960w`
                        : undefined
                    }
                    sizes="(max-width: 640px) 45vw, (max-width: 1024px) 22vw, 200px"
                    loading="lazy"
                    alt={image.caption ?? CATEGORY_LABELS[image.category]}
                    className={styles.imageThumb}
                  />
                ) : (
                  <div className={styles.imageSkeleton} aria-hidden="true" />
                )}
                <Badge variant="muted" className={styles.imageBadge}>
                  {CATEGORY_LABELS[image.category]}
                </Badge>
              </div>
            ))}
            {remainingImages > 0 ? (
              <div className={styles.imageMoreTile} aria-label={`${remainingImages} weitere Bilder`}>
                <span>+{remainingImages}</span>
              </div>
            ) : null}
          </div>
        ) : null}

        {previewNotes.length > 0 ? (
          <div className={styles.noteList}>
            {previewNotes.map((note) => (
              <div key={note.id} className={styles.noteItem}>
                <span className={styles.noteAuthor}>{note.member_name}</span>
                <p className={styles.noteExcerpt}>{toNoteExcerpt(note.body_html)}</p>
              </div>
            ))}
          </div>
        ) : null}

        {detail.contributors.length > 0 ? (
          <div className={styles.contributorRow}>
            {detail.contributors.map((contributor) => (
              <div
                key={contributor.member_id}
                className={styles.contributorAvatar}
                title={`${contributor.name} – ${contributor.role_label}`}
              >
                <span aria-hidden="true">{contributor.name.charAt(0).toUpperCase()}</span>
              </div>
            ))}
          </div>
        ) : null}

        <Link href={detailHref} className={styles.detailLink}>
          Vollständiges Release ansehen
        </Link>
      </Card>
    </div>
  );
}

