import { Badge, Card, EmptyState, SectionHeader } from '@/components/ui'
import type { PublicGroupTheme } from '@/types/groupContributors'

import styles from '../page.module.css'

interface ThemesSectionProps {
  themes: PublicGroupTheme[]
}

const THEME_TYPE_LABELS: Record<string, string> = {
  OP: 'Opening',
  ED: 'Ending',
  MIDDLE: 'Middle',
}

const THEME_TYPE_ORDER = ['OP', 'ED', 'MIDDLE'] as const

function groupByType(themes: PublicGroupTheme[]): Record<string, PublicGroupTheme[]> {
  const grouped: Record<string, PublicGroupTheme[]> = { OP: [], ED: [], MIDDLE: [] }
  for (const theme of themes) {
    const key = theme.type.toUpperCase()
    if (key in grouped) {
      grouped[key].push(theme)
    } else {
      grouped[key] = [theme]
    }
  }
  return grouped
}

export function ThemesSection({ themes }: ThemesSectionProps) {
  const grouped = groupByType(themes)

  return (
    <div id="themes" className={styles.themesSection}>
      <SectionHeader title="OP / ED / Middle" />
      {themes.length === 0 ? (
        <EmptyState
          variant="compact"
          title="Noch keine OP/ED/Middle"
          description="Für dieses Projekt sind noch keine Theme-Einblicke freigegeben."
        />
      ) : (
        <>
          {THEME_TYPE_ORDER.map((type) => {
            const items = grouped[type] ?? []
            if (items.length === 0) return null
            return (
              <div key={type} className={styles.themeGroup}>
                <h3 className={styles.blockTitle}>{THEME_TYPE_LABELS[type]}</h3>
                {items.map((theme) => (
                  <Card key={theme.id} variant="section" className={styles.themeCard}>
                    <div className={styles.themeHeader}>
                      <span className={styles.themeTitle}>{theme.title}</span>
                      <Badge variant="muted">{THEME_TYPE_LABELS[theme.type.toUpperCase()] ?? theme.type}</Badge>
                    </div>
                    {theme.assets.length > 0 && (
                      <div className={styles.assetGrid}>
                        {theme.assets.map((asset) =>
                          asset.thumbnail_url ? (
                            <div key={asset.id} className={styles.assetTile}>
                              <img
                                src={asset.thumbnail_url}
                                alt={`OP-Asset: ${theme.title}`}
                                className={styles.assetThumb}
                              />
                            </div>
                          ) : null,
                        )}
                      </div>
                    )}
                  </Card>
                ))}
              </div>
            )
          })}
        </>
      )}
    </div>
  )
}

import Link from 'next/link'

import { MemberSearchCard } from '@/components/archive/MemberSearchCard'
import { getFansubs, listRoleDefinitions, searchArchive } from '@/lib/api'
import { readableCodeLabel } from '@/lib/roleCatalog'
import type { RoleDefinitionOption } from '@/types/admin-capability'
import type { FansubGroup } from '@/types/fansub'

import styles from './page.module.css'

// Diese Seite ist immer live — kein SSG-Caching (force-dynamic, D-15).
export const dynamic = 'force-dynamic'

interface ArchivePageProps {
  searchParams:
    | Promise<{
        rolle?: string
        gruppe?: string
        von?: string
        bis?: string
        page?: string
      }>
    | {
        rolle?: string
        gruppe?: string
        von?: string
        bis?: string
        page?: string
      }
    | undefined
}

interface ResolvedArchiveParams {
  rolle?: string
  gruppe?: string
  von?: string
  bis?: string
  page?: string
}

export default async function ArchivPage({ searchParams }: ArchivePageProps) {
  const resolved = ((await searchParams) ?? {}) as ResolvedArchiveParams

  const currentPage = Math.max(1, Number(resolved.page ?? '1') || 1)
  const hasFilters = !!(resolved.rolle || resolved.gruppe || resolved.von || resolved.bis)

  // Archiv-Suchergebnis holen — kein revalidate (force-dynamic)
  let result: Awaited<ReturnType<typeof searchArchive>> | null = null
  let fetchError: string | null = null

  try {
    result = await searchArchive({
      rolle: resolved.rolle,
      gruppe: resolved.gruppe,
      von: resolved.von,
      bis: resolved.bis,
      page: currentPage,
    })
  } catch {
    fetchError = 'Archiv konnte nicht geladen werden'
  }

  // Fansub-Gruppen für Gruppen-Filter-Dropdown — kein revalidate (force-dynamic)
  let fansubs: FansubGroup[] = []
  try {
    const fansubResponse = await getFansubs()
    fansubs = fansubResponse.data ?? []
  } catch {
    // Gruppen-Dropdown bleibt leer — kein fataler Fehler
  }

  let roleOptions: RoleDefinitionOption[] = []
  let roleCatalogError = false
  try {
    const [contributionRoles, historyRoles] = await Promise.all([
      listRoleDefinitions('anime_contribution'),
      listRoleDefinitions('group_history'),
    ])
    roleOptions = Array.from(new Map(
      [...contributionRoles, ...historyRoles].map((role) => [role.code, role]),
    ).values()).sort((a, b) => a.sort_order - b.sort_order || a.code.localeCompare(b.code))
  } catch {
    roleCatalogError = true
  }

  if (resolved.rolle && !roleOptions.some((role) => role.code === resolved.rolle)) {
    roleOptions.push({ code: resolved.rolle, label_de: readableCodeLabel(resolved.rolle), sort_order: Number.MAX_SAFE_INTEGER })
  }

  const totalPages = result ? Math.ceil(result.total / 20) : 0

  return (
    <main className={styles.archivPage} aria-label="Archiv — Fansub-Mitwirkende entdecken">
      <header className={styles.archivHeader}>
        <h1>Archiv — Fansub-Mitwirkende entdecken</h1>
        <p>Durchsuche historische Beiträge von Fansub-Mitgliedern nach Rolle, Zeitraum und Gruppe.</p>
      </header>

      {/* Filter-Formular: URL-State via GET-Parameter (barrierefreiheitsfreundlich, kein JS nötig) */}
      <section className={styles.archivFilters}>
        <form role="search" action="/archiv" method="GET">
          <div className={styles.archivFilterRow}>
            {/* Rolle-Filter */}
            <div className={styles.filterGroup}>
              <label htmlFor="rolle">Rolle</label>
              <select id="rolle" name="rolle" defaultValue={resolved.rolle ?? ''}>
                <option value="">Alle Rollen</option>
                {roleOptions.map((option) => (
                  <option key={option.code} value={option.code}>
                    {option.label_de}
                  </option>
                ))}
              </select>
              {roleCatalogError ? <span role="status">Rollenfilter konnten nicht geladen werden</span> : null}
            </div>

            {/* Gruppe-Filter (befüllt aus GET /api/v1/fansubs, D-14) */}
            <div className={styles.filterGroup}>
              <label htmlFor="gruppe">Gruppe</label>
              <select id="gruppe" name="gruppe" defaultValue={resolved.gruppe ?? ''}>
                <option value="">Alle Gruppen</option>
                {fansubs.map((fg) => (
                  <option key={fg.id} value={String(fg.id)}>
                    {fg.name}
                  </option>
                ))}
              </select>
            </div>

            {/* Zeitraum von */}
            <div className={styles.filterGroup}>
              <label htmlFor="von">Von</label>
              <input
                type="number"
                id="von"
                name="von"
                min="1990"
                max="2099"
                placeholder="Jahr (z. B. 2010)"
                defaultValue={resolved.von ?? ''}
              />
            </div>

            {/* Zeitraum bis */}
            <div className={styles.filterGroup}>
              <label htmlFor="bis">Bis</label>
              <input
                type="number"
                id="bis"
                name="bis"
                min="1990"
                max="2099"
                placeholder="Jahr (z. B. 2010)"
                defaultValue={resolved.bis ?? ''}
              />
            </div>

            {/* Aktionen */}
            <div className={styles.filterActions}>
              <button type="submit" className={styles.filterSubmitBtn}>
                Archiv durchsuchen
              </button>
              <Link href="/archiv" className={styles.filterResetLink}>
                Filter zurücksetzen
              </Link>
            </div>
          </div>
        </form>
      </section>

      {/* Ergebnis-Bereich */}
      <section aria-label="Suchergebnisse">
        {fetchError ? (
          <div className={styles.archivErrorState} role="alert">
            <h2>Archiv konnte nicht geladen werden</h2>
            <p>Bitte Seite neu laden oder später erneut versuchen.</p>
          </div>
        ) : result && result.data.length === 0 ? (
          <div className={styles.archivEmptyState}>
            {hasFilters ? (
              <>
                <h2>Keine Mitglieder gefunden</h2>
                <p>
                  Für die gewählten Filter wurden keine öffentlichen Beiträge gefunden.
                  Passe die Filter an oder setze sie zurück.
                </p>
                <Link href="/archiv" className={styles.filterResetLink}>
                  Filter zurücksetzen
                </Link>
              </>
            ) : (
              <>
                <h2>Noch keine Einträge</h2>
                <p>Noch keine öffentlichen Beiträge im Archiv.</p>
              </>
            )}
          </div>
        ) : result && result.data.length > 0 ? (
          <>
            <div className={styles.archivGrid}>
              {result.data.map((member) => (
                <MemberSearchCard
                  key={member.id}
                  id={member.id}
                  nickname={member.nickname}
                  displayName={member.display_name}
                  slug={member.slug}
                  avatarPath={member.avatar_path}
                  isVerified={member.is_verified}
                  topRoles={member.top_roles}
                  groups={member.groups}
                />
              ))}
            </div>

            {/* Pagination: nur anzeigen wenn mehr als 1 Seite (D-16) */}
            {totalPages > 1 && (
              <nav className={styles.archivPagination} aria-label="Seitennavigation">
                {currentPage > 1 && (
                  <Link
                    href={buildArchivUrl(resolved, currentPage - 1)}
                    className={styles.paginationLink}
                  >
                    Zurück
                  </Link>
                )}
                <span className={styles.paginationInfo}>
                  Seite {currentPage} von {totalPages}
                </span>
                {currentPage < totalPages && (
                  <Link
                    href={buildArchivUrl(resolved, currentPage + 1)}
                    className={styles.paginationLink}
                  >
                    Weiter
                  </Link>
                )}
              </nav>
            )}
          </>
        ) : null}
      </section>
    </main>
  )
}

/** Baut die Archiv-URL mit allen aktiven Filtern und einer neuen Seite. */
function buildArchivUrl(params: ResolvedArchiveParams, page: number): string {
  const q = new URLSearchParams()
  if (params.rolle) q.set('rolle', params.rolle)
  if (params.gruppe) q.set('gruppe', params.gruppe)
  if (params.von) q.set('von', params.von)
  if (params.bis) q.set('bis', params.bis)
  if (page > 1) q.set('page', String(page))
  const qs = q.toString()
  return `/archiv${qs ? `?${qs}` : ''}`
}

'use client'

import { useEffect, useState } from 'react'
import { Play, Film } from 'lucide-react'

import { ApiError, getReleaseAssets } from '@/lib/api'
import { MediaAsset, MediaAssetsByType, ReleaseMediaAssetType } from '@/types/mediaAsset'
import VideoPlayerModal from '../VideoPlayerModal'

import styles from './MediaAssetsSection.module.css'

interface MediaAssetsSectionProps {
  releaseId?: number
  assets?: MediaAsset[]
  errorMessage?: string | null
}

const TYPE_LABELS: Record<ReleaseMediaAssetType, string> = {
  video: 'Video',
  poster: 'Poster',
  banner: 'Banner',
  logo: 'Logo',
  image: 'Bilder',
  other: 'Extras',
}

const TYPE_BADGES: Record<ReleaseMediaAssetType, string> = {
  video: 'VI',
  poster: 'PO',
  banner: 'BA',
  logo: 'LO',
  image: 'IMG',
  other: 'EX',
}

const INITIAL_VISIBLE_COUNT = 2

function formatDuration(seconds: number): string {
  const minutes = Math.floor(seconds / 60)
  const remainingSeconds = seconds % 60
  return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`
}

function groupAssetsByType(assets: MediaAsset[]): MediaAssetsByType {
  const grouped: MediaAssetsByType = {
    video: [],
    poster: [],
    banner: [],
    logo: [],
    image: [],
    other: [],
  }

  for (const asset of assets) {
    if (isReleaseMediaAssetType(asset.type)) {
      grouped[asset.type].push(asset)
    }
  }

  // Sort by order within each type
  for (const type of Object.keys(grouped) as ReleaseMediaAssetType[]) {
    grouped[type].sort((a, b) => a.order - b.order)
  }

  return grouped
}

function isReleaseMediaAssetType(type: MediaAsset['type']): type is ReleaseMediaAssetType {
  return type === 'video' || type === 'poster' || type === 'banner' || type === 'logo' || type === 'image' || type === 'other'
}

interface AssetTileProps {
  asset: MediaAsset
  onPlay: (asset: MediaAsset) => void
}

function AssetTile({ asset, onPlay }: AssetTileProps) {
  return (
    <div
      className={styles.assetTile}
      onClick={() => onPlay(asset)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          onPlay(asset)
        }
      }}
      role="button"
      tabIndex={0}
      aria-label={`${asset.title} abspielen`}
    >
      <div className={styles.thumbnailContainer}>
        {asset.thumbnail_url ? (
          <img src={asset.thumbnail_url} alt={asset.title} className={styles.thumbnail} />
        ) : (
          <div className={styles.thumbnailPlaceholder}>
            <Film size={32} />
          </div>
        )}
        <div className={styles.playButtonOverlay}>
          <Play size={24} fill="currentColor" />
        </div>
      </div>
      <div className={styles.assetInfo}>
        <div className={styles.assetTitle} title={asset.title}>
          {asset.title}
        </div>
        <div className={styles.assetDuration}>
          {typeof asset.duration_seconds === 'number' ? formatDuration(asset.duration_seconds) : 'Dauer unbekannt'}
        </div>
      </div>
    </div>
  )
}

interface TypeGroupProps {
  type: ReleaseMediaAssetType
  assets: MediaAsset[]
  onPlayAsset: (asset: MediaAsset) => void
}

function TypeGroup({ type, assets, onPlayAsset }: TypeGroupProps) {
  const [isExpanded, setIsExpanded] = useState(false)

  if (assets.length === 0) {
    return null
  }

  const visibleAssets = isExpanded ? assets : assets.slice(0, INITIAL_VISIBLE_COUNT)
  const remainingCount = assets.length - INITIAL_VISIBLE_COUNT
  const showExpandButton = remainingCount > 0

  const expandButtonId = `expand-${type}`
  const gridId = `grid-${type}`

  return (
    <div className={styles.typeGroup}>
      <div className={styles.typeHeader}>
        <div className={`${styles.typeIcon} ${styles.typeIconInsert}`}>{TYPE_BADGES[type]}</div>
        <h3 className={styles.typeTitle}>{TYPE_LABELS[type]}</h3>
        <span className={styles.typeCount}>{assets.length}</span>
      </div>
      <div className={styles.assetGrid} id={gridId}>
        {visibleAssets.map((asset) => (
          <AssetTile key={asset.id} asset={asset} onPlay={onPlayAsset} />
        ))}
      </div>
      {showExpandButton && (
        <button
          id={expandButtonId}
          className={styles.expandButton}
          onClick={() => setIsExpanded(!isExpanded)}
          aria-expanded={isExpanded}
          aria-controls={gridId}
          aria-label={isExpanded ? `${TYPE_LABELS[type]} zuklappen` : `${remainingCount} weitere ${TYPE_LABELS[type]} anzeigen`}
        >
          {isExpanded ? `${TYPE_LABELS[type]} zuklappen` : `+${remainingCount} weitere ${TYPE_LABELS[type]}`}
        </button>
      )}
    </div>
  )
}

export default function MediaAssetsSection({
  releaseId,
  assets: initialAssets,
  errorMessage = null,
}: MediaAssetsSectionProps) {
  const [assets, setAssets] = useState<MediaAsset[]>(initialAssets ?? [])
  const [loading, setLoading] = useState(false)
  const [runtimeError, setRuntimeError] = useState<string | null>(errorMessage)
  const [playingAsset, setPlayingAsset] = useState<MediaAsset | null>(null)
  const [isModalOpen, setIsModalOpen] = useState(false)

  useEffect(() => {
    const timeout = window.setTimeout(() => setAssets(initialAssets ?? []), 0)
    return () => window.clearTimeout(timeout)
  }, [initialAssets])

  useEffect(() => {
    if (typeof errorMessage === 'string' && errorMessage.trim()) {
      const timeout = window.setTimeout(() => setRuntimeError(errorMessage), 0)
      return () => window.clearTimeout(timeout)
    }

    if (!releaseId || initialAssets) {
      const timeout = window.setTimeout(() => setRuntimeError(null), 0)
      return () => window.clearTimeout(timeout)
    }

    let cancelled = false
    const resetTimeout = window.setTimeout(() => {
      if (!cancelled) {
        setLoading(true)
        setRuntimeError(null)
      }
    }, 0)

    void getReleaseAssets(releaseId)
      .then((response) => {
        if (cancelled) {
          return
        }
        setAssets(response.data.assets)
      })
      .catch((error: unknown) => {
        if (cancelled) {
          return
        }
        if (error instanceof ApiError) {
          setRuntimeError(error.message)
          return
        }
        setRuntimeError('Media Assets konnten nicht geladen werden.')
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false)
        }
      })

    return () => {
      cancelled = true
      window.clearTimeout(resetTimeout)
    }
  }, [errorMessage, initialAssets, releaseId])

  const handlePlayAsset = (asset: MediaAsset) => {
    setPlayingAsset(asset)
    setIsModalOpen(true)
  }

  const handleCloseModal = () => {
    setIsModalOpen(false)
    setPlayingAsset(null)
  }

  if (runtimeError) {
    return (
      <section className={styles.mediaAssetsSection} aria-labelledby="media-assets-title">
        <h2 id="media-assets-title" className={styles.sectionTitle}>
          Media Assets
        </h2>
        <div className={styles.errorState} role="status">
          {runtimeError}
        </div>
      </section>
    )
  }

  if (loading) {
    return (
      <section className={styles.mediaAssetsSection} aria-labelledby="media-assets-title" aria-busy="true">
        <h2 id="media-assets-title" className={styles.sectionTitle}>
          Media Assets
        </h2>
        <div className={styles.loadingState}>Media Assets werden geladen...</div>
      </section>
    )
  }

  if (assets.length === 0) {
    return null // Empty state: section completely hidden when no assets
  }

  const groupedAssets = groupAssetsByType(assets)
  const typeOrder: ReleaseMediaAssetType[] = ['video', 'poster', 'banner', 'logo', 'image', 'other']

  return (
    <>
      <section className={styles.mediaAssetsSection} aria-labelledby="media-assets-title">
        <h2 id="media-assets-title" className={styles.sectionTitle}>
          Media Assets
        </h2>
        {typeOrder.map((type) => (
          <TypeGroup key={type} type={type} assets={groupedAssets[type]} onPlayAsset={handlePlayAsset} />
        ))}
      </section>

      <VideoPlayerModal
        key={playingAsset?.id ?? 'closed'}
        isOpen={isModalOpen}
        asset={playingAsset}
        onClose={handleCloseModal}
      />
    </>
  )
}

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { ChevronLeft, ChevronRight, X } from 'lucide-react'

import { ScreenshotImage, ScreenshotImagesResponse } from '@/types/screenshotImage'
import { resolvePublicApiUrl } from '@/lib/publicApiUrl'

import styles from './ScreenshotGallery.module.css'

interface ScreenshotGalleryProps {
  releaseId: number
}

export default function ScreenshotGallery({ releaseId }: ScreenshotGalleryProps) {
  const [images, setImages] = useState<ScreenshotImage[]>([])
  const [cursor, setCursor] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [lightboxOpen, setLightboxOpen] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)
  const [hasMore, setHasMore] = useState(true)

  const observerRef = useRef<IntersectionObserver | null>(null)
  const loadTriggerRef = useRef<HTMLDivElement | null>(null)

  // Fetch images from API
  const fetchImages = useCallback(
    async (nextCursor: string | null = null) => {
      try {
        setLoading(true)
        setError(null)

        const params = new URLSearchParams()
        params.append('limit', '12')
        if (nextCursor) {
          params.append('cursor', nextCursor)
        }

        const response = await fetch(resolvePublicApiUrl(`/api/v1/releases/${releaseId}/images?${params.toString()}`))

        if (!response.ok) {
          throw new Error('Screenshots konnten nicht geladen werden.')
        }

        const data: { data: ScreenshotImagesResponse } = await response.json()

        setImages((prev) => (nextCursor ? [...prev, ...data.data.images] : data.data.images))
        setCursor(data.data.cursor)
        setHasMore(data.data.cursor !== null)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Ein Fehler ist aufgetreten.')
      } finally {
        setLoading(false)
      }
    },
    [releaseId]
  )

  // Initial load
  useEffect(() => {
    fetchImages()
  }, [fetchImages])

  // Intersection Observer for infinite loading
  useEffect(() => {
    if (!hasMore || loading) return

    const callback: IntersectionObserverCallback = (entries) => {
      const [entry] = entries
      if (entry.isIntersecting && cursor) {
        fetchImages(cursor)
      }
    }

    observerRef.current = new IntersectionObserver(callback, {
      rootMargin: '200px',
    })

    if (loadTriggerRef.current) {
      observerRef.current.observe(loadTriggerRef.current)
    }

    return () => {
      if (observerRef.current) {
        observerRef.current.disconnect()
      }
    }
  }, [cursor, hasMore, loading, fetchImages])

  // Keyboard navigation for lightbox
  useEffect(() => {
    if (!lightboxOpen) return

    const handleKeyDown = (e: KeyboardEvent) => {
      switch (e.key) {
        case 'Escape':
          setLightboxOpen(false)
          break
        case 'ArrowLeft':
          e.preventDefault()
          navigatePrevious()
          break
        case 'ArrowRight':
          e.preventDefault()
          navigateNext()
          break
        case 'Home':
          e.preventDefault()
          setActiveIndex(0)
          break
        case 'End':
          e.preventDefault()
          setActiveIndex(images.length - 1)
          break
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [lightboxOpen, activeIndex, images.length])

  const openLightbox = (index: number) => {
    setActiveIndex(index)
    setLightboxOpen(true)
  }

  const closeLightbox = () => {
    setLightboxOpen(false)
  }

  const navigatePrevious = () => {
    setActiveIndex((prev) => (prev > 0 ? prev - 1 : prev))
  }

  const navigateNext = () => {
    setActiveIndex((prev) => (prev < images.length - 1 ? prev + 1 : prev))
  }

  const handleRetry = () => {
    setImages([])
    setCursor(null)
    setHasMore(true)
    fetchImages()
  }

  // Empty state: Hide section completely
  if (!loading && images.length === 0 && !error) {
    return null
  }

  return (
    <section className={styles.screenshotGallerySection}>
      <h2 className={styles.screenshotGalleryHeading}>Screenshots</h2>

      {error && (
        <div className={styles.screenshotError}>
          <p className={styles.screenshotErrorText}>{error}</p>
          <button type="button" className={styles.screenshotRetryButton} onClick={handleRetry}>
            Erneut versuchen
          </button>
        </div>
      )}

      <div className={styles.screenshotGrid}>
        {images.map((image, index) => (
          <button
            key={image.id}
            type="button"
            className={styles.screenshotThumbnail}
            onClick={() => openLightbox(index)}
            aria-label={`Screenshot ${index + 1} anzeigen${image.caption ? `: ${image.caption}` : ''}`}
          >
            <img src={image.thumbnail_url} alt={image.caption || `Screenshot ${index + 1}`} className={styles.screenshotThumbnailImage} />
          </button>
        ))}

        {loading &&
          Array.from({ length: 6 }).map((_, i) => (
            <div key={`skeleton-${i}`} className={styles.screenshotSkeleton} aria-hidden="true" />
          ))}
      </div>

      {hasMore && !loading && <div ref={loadTriggerRef} className={styles.screenshotLoadTrigger} aria-hidden="true" />}

      {lightboxOpen && images[activeIndex] && (
        <div
          className={styles.screenshotLightbox}
          onClick={closeLightbox}
          role="dialog"
          aria-modal="true"
          aria-label="Screenshot Lightbox"
        >
          <div className={styles.screenshotLightboxContent} onClick={(e) => e.stopPropagation()}>
            <img
              src={images[activeIndex].url}
              alt={images[activeIndex].caption || `Screenshot ${activeIndex + 1}`}
              className={styles.screenshotLightboxImage}
            />

            <button
              type="button"
              className={`${styles.screenshotLightboxNav} ${styles.screenshotLightboxNavPrev}`}
              onClick={navigatePrevious}
              disabled={activeIndex === 0}
