'use client'

import Image from 'next/image'
import type { DragEvent, KeyboardEvent, MutableRefObject } from 'react'
import { ImagePlus, Loader2, Pencil, RefreshCw, Trash2 } from 'lucide-react'

import { Button } from '@/components/ui'

import type { EditableMediaValue } from './MediaUpload'
import styles from './MediaUpload.module.css'

export interface MediaUploadCoreProps {
  /** 'logo' oder 'banner' */
  type: 'logo' | 'banner'
  /** Aktuell gespeichertes Medium (für Preview) */
  value: EditableMediaValue | null
  /** Dateiname für Anzeige */
  /** Vorschau-URL (bereits mit Cache-Buster) */
  previewURL: string
  /** Formatierte Dateigröße */
  /** Logo-Fallback (Initialen + Farbe) */
  fallback: { initials: string; background: string; color: '#FFFFFF' | '#111111' }
  /** Läuft gerade eine Aktion? */
  busy: boolean
  /** Wird gerade bearbeitet (Cropper vorbereiten)? */
  preparingEdit: boolean
  /** Aktuelle Busy-Aktion */
  busyAction: 'upload' | 'delete' | null
  /** Upload-Fortschritt in Prozent */
  progress: number
  /** Fehlermeldung */
  error: string | null
  /** Warnmeldung */
  warning: string | null
  /** Dropzone im Drag-Zustand */
  dragging: boolean
  /** Ist disabled? */
  disabled?: boolean
  /** Ref auf das versteckte File-Input-Element */
  inputRef: MutableRefObject<HTMLInputElement | null>
  /** Accept-Mime-Types für das File-Input */
  acceptedMime: string
  /** Aria-Label für die Dropzone */
  dropzoneAriaLabel: string
  /** Wird aufgerufen, wenn der User eine Datei auswählt */
  onFileInputChange: (event: React.ChangeEvent<HTMLInputElement>) => void
  /** Wird aufgerufen, wenn ein Drag über der Dropzone beginnt */
  onDragOver: (event: DragEvent<HTMLDivElement>) => void
  /** Wird aufgerufen, wenn ein Drag-Enter über der Dropzone stattfindet */
  onDragEnter: (event: DragEvent<HTMLDivElement>) => void
  /** Wird aufgerufen, wenn ein Drag die Dropzone verlässt */
  onDragLeave: (event: DragEvent<HTMLDivElement>) => void
  /** Wird aufgerufen, wenn eine Datei in die Dropzone fallen gelassen wird */
  onDrop: (event: DragEvent<HTMLDivElement>) => void
  /** Wird aufgerufen, wenn die Dropzone per Tastatur aktiviert wird */
  onDropzoneKeyDown: (event: KeyboardEvent<HTMLDivElement>) => void
  /** Wird aufgerufen, wenn der User auf „Edit" klickt */
  onEditClick: () => void
  /** Wird aufgerufen, wenn der User löschen möchte */
  onRemoveClick: () => void
}

/**
 * Reiner Render-Kern von MediaUpload.
 * Enthält Dropzone, Preview, Fortschrittsbalken, Aktions-Buttons und Meldungen.
 * Alle Zustands- und Upload-Logik verbleibt im Koordinator MediaUpload.tsx.
 */
export function MediaUploadCore({
  type,
  value,
  previewURL,
  fallback,
  busy,
  preparingEdit,
  busyAction,
  progress,
  error,
  warning,
  dragging,
  disabled,
  inputRef,
  acceptedMime,
  dropzoneAriaLabel,
  onFileInputChange,
  onDragOver,
  onDragEnter,
  onDragLeave,
  onDrop,
  onDropzoneKeyDown,
  onEditClick,
  onRemoveClick,
}: MediaUploadCoreProps) {
  const isLogo = type === 'logo'
  const hasValue = Boolean(value?.publicURL?.trim())
  const title = isLogo ? 'Logo' : 'Banner'
  const uploadActionLabel = hasValue ? 'Ersetzen' : 'Hochladen'
  const dropzoneClassName = [
    styles.dropzone,
    isLogo ? styles.dropzoneLogo : styles.dropzoneBanner,
    hasValue ? styles.dropzoneWithPreview : '',
    dragging ? styles.dropzoneDrag : '',
    error ? styles.dropzoneError : '',
    disabled ? styles.dropzoneDisabled : '',
  ].filter(Boolean).join(' ')

  return (
    <>
      <div className={styles.headerRow}>
        <h3>{title}</h3>
        {busy ? (
          <span className={styles.statusPill} aria-live="polite">
            <Loader2 size={14} className={styles.spinner} />
            {preparingEdit ? 'Bearbeiten...' : busyAction === 'upload' ? 'Upload...' : 'Löschen...'}
          </span>
        ) : null}
      </div>

      <div
        className={dropzoneClassName}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-label={dropzoneAriaLabel}
        aria-busy={busy}
        onClick={() => (!disabled && !busy ? inputRef.current?.click() : undefined)}
        onKeyDown={onDropzoneKeyDown}
        onDragOver={onDragOver}
        onDragEnter={onDragEnter}
        onDragLeave={onDragLeave}
        onDrop={onDrop}
        aria-disabled={disabled || busy}
      >
        {hasValue ? (
          <>
            {isLogo ? (
              <div className={styles.previewRound}>
                <Image
                  src={previewURL}
                  alt="Logo Vorschau"
                  className={styles.previewImageRound}
                  width={116}
                  height={116}
                  unoptimized
                />
              </div>
            ) : (
              <div className={styles.previewWide}>
                <Image
                  src={previewURL}
                  alt="Banner Vorschau"
                  className={styles.previewImageWide}
                  width={520}
                  height={130}
                  unoptimized
                />
              </div>
            )}
          </>
        ) : isLogo ? (
          <div className={styles.previewRoundFallback} style={{ backgroundColor: fallback.background, color: fallback.color }}>
            {fallback.initials}
          </div>
        ) : (
          <div className={styles.previewWideEmpty}>Kein Banner vorhanden</div>
        )}

        {!hasValue ? (
          <div className={styles.emptyState}>
            <ImagePlus size={20} />
            <span>Bild hierher ziehen oder klicken zum Hochladen</span>
          </div>
        ) : null}
      </div>

      {busyAction === 'upload' ? (
        <div className={styles.progressWrap}>
          <div className={styles.progressTrack}>
            <div className={styles.progressBar} style={{ width: `${progress}%` }} />
          </div>
          <span className={styles.progressLabel}>{progress}%</span>
        </div>
      ) : null}

      <div className={styles.actions}>
        {hasValue ? (
          <Button
            type="button"
            variant="secondary"
            size="sm"
            onClick={onEditClick}
            disabled={disabled || busy}
            aria-label={`${title} bearbeiten`}
            leftIcon={<Pencil size={14} />}
          >
            Bearbeiten
          </Button>
        ) : null}
        <Button
          type="button"
          variant="secondary"
          size="sm"
          onClick={() => inputRef.current?.click()}
          disabled={disabled || busy}
          aria-label={`${title} ${hasValue ? 'ersetzen' : 'hochladen'}`}
          leftIcon={hasValue ? <RefreshCw size={14} /> : <ImagePlus size={14} />}
        >
          {uploadActionLabel}
        </Button>
        <Button
          type="button"
          variant="danger"
          size="sm"
          onClick={onRemoveClick}
          disabled={disabled || busy || !hasValue}
          aria-label={`${title} löschen`}
          leftIcon={<Trash2 size={14} />}
        >
          Löschen
        </Button>
      </div>

      {warning ? <p className={styles.warning} aria-live="polite">{warning}</p> : null}
      {error ? <p className={styles.error} role="alert">{error}</p> : null}

      <input
        ref={inputRef}
        className={styles.fileInput}
        type="file"
        accept={acceptedMime}
        aria-label={`${title} Datei auswählen`}
        onChange={onFileInputChange}
      />
    </>
  )
}

'use client'

import Link from 'next/link'
import Image from 'next/image'
import { useEffect, useRef, useState } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { getCoverUrl, shouldUseUnoptimizedImage } from '@/lib/utils'
import styles from './AnimeRelations.module.css'

interface AnimeRelation {
  anime_id: number
  title: string
  relation_type: string
  cover_image: string | null
  year: number | null
  type: string
}

interface AnimeRelationsProps {
  relations: AnimeRelation[]
  variant?: 'default' | 'compact'
}

const relationTypeLabels: Record<string, string> = {
  related: 'Related',
  sequel: 'Sequel',
  prequel: 'Prequel',
  alternative: 'Alternative',
  side_story: 'Side Story',
  spin_off: 'Spin-Off',
  summary: 'Summary',
  parent: 'Parent',
  other: 'Other',
}

const animeTypeLabels: Record<string, string> = {
  tv: 'TV',
  movie: 'Movie',
  ova: 'OVA',
  ona: 'ONA',
  special: 'Special',
  music: 'Music',
}

export function AnimeRelations({ relations, variant = 'default' }: AnimeRelationsProps) {
  const sliderRef = useRef<HTMLDivElement | null>(null)
  const animationFrameRef = useRef<number | null>(null)
  const [canScrollLeft, setCanScrollLeft] = useState(false)
  const [canScrollRight, setCanScrollRight] = useState(relations.length > 3)
  const [hasOverflow, setHasOverflow] = useState(relations.length > 3)
  const isCompact = variant === 'compact'

  const updateScrollState = () => {
    const slider = sliderRef.current
    if (!slider) return

    const maxScrollLeft = slider.scrollWidth - slider.clientWidth
    const overflow = maxScrollLeft > 8
    setHasOverflow(overflow)
    setCanScrollLeft(overflow && slider.scrollLeft > 8)
    setCanScrollRight(overflow && maxScrollLeft - slider.scrollLeft > 8)
  }

  const scrollByCards = (direction: 'left' | 'right') => {
    const slider = sliderRef.current
    if (!slider) return

    const amount = Math.max(176, Math.floor(slider.clientWidth * 0.85))
    slider.scrollBy({
      left: direction === 'right' ? amount : -amount,
      behavior: 'smooth',
    })
  }

  useEffect(() => {
    const slider = sliderRef.current
    if (!slider || relations.length === 0) return

    const scheduleUpdate = () => {
      if (animationFrameRef.current !== null) {
        cancelAnimationFrame(animationFrameRef.current)
      }
      animationFrameRef.current = requestAnimationFrame(() => {
        animationFrameRef.current = null
        updateScrollState()
      })
    }

    scheduleUpdate()

    const handleScroll = () => scheduleUpdate()
    const handleResize = () => scheduleUpdate()
    const resizeObserver = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(() => scheduleUpdate()) : null

    slider.addEventListener('scroll', handleScroll, { passive: true })
    window.addEventListener('resize', handleResize)
    resizeObserver?.observe(slider)

    return () => {
      if (animationFrameRef.current !== null) {
        cancelAnimationFrame(animationFrameRef.current)
        animationFrameRef.current = null
      }
      slider.removeEventListener('scroll', handleScroll)
      window.removeEventListener('resize', handleResize)
      resizeObserver?.disconnect()
    }
  }, [relations.length])

  if (!relations || relations.length === 0) {
    return null
  }

  return (
    <section className={`${styles.relationsSection} ${isCompact ? styles.compact : ''}`}>
      <div className={styles.header}>
        <h2 className={styles.title}>Related</h2>
        {relations.length > 3 && (
          <div className={styles.sliderControls}>
            <button
              type="button"
              className={styles.navButton}
              onClick={() => scrollByCards('left')}
              disabled={!canScrollLeft}
              aria-label="Related nach links scrollen"
            >
              <ChevronLeft size={18} />
            </button>
            <button
              type="button"
              className={styles.navButton}
              onClick={() => scrollByCards('right')}
              disabled={!canScrollRight}
              aria-label="Related nach rechts scrollen"
            >
              <ChevronRight size={18} />
            </button>
          </div>
        )}
      </div>
      <div className={styles.sliderShell}>
        <div ref={sliderRef} className={styles.slider}>
          {relations.map((rel) => (
            <Link
              key={rel.anime_id}
              href={`/anime/${rel.anime_id}`}
              className={styles.card}
              prefetch={false}
            >
              <div className={styles.cardInner}>
                <div className={styles.cardMedia}>
                  {rel.cover_image ? (
                    <Image
                      src={getCoverUrl(rel.cover_image)}
                      alt={rel.title}
                      fill
                      sizes="160px"
                      className={styles.cardImage}
                      unoptimized={shouldUseUnoptimizedImage(getCoverUrl(rel.cover_image))}
                    />
                  ) : (
                    <div className={styles.cardPlaceholder} />
                  )}
                  <div className={styles.cardGradient} />
                  <span className={styles.cardBadge}>
                    {relationTypeLabels[rel.relation_type] || rel.relation_type}
                  </span>
                </div>
                <div className={styles.cardContent}>
                  <span className={styles.cardTitle}>{rel.title}</span>
                  <div className={styles.cardMeta}>
                    {rel.year && <span className={styles.cardYear}>{rel.year}</span>}
                    <span className={styles.cardType}>
                      {animeTypeLabels[rel.type?.toLowerCase()] || rel.type}
                    </span>
                  </div>
                </div>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </section>
  )
}

'use client'

import { FormEvent, useEffect, useRef, useState } from 'react'
import { useRouter } from 'next/navigation'

import { ApiError, createAnimeComment } from '@/lib/api'
import { useAuthSession } from '@/lib/useAuthSession'
import { CommentListItem } from '@/types/comment'

import styles from './CommentForm.module.css'

interface CommentFormProps {
  animeID: number
  onCommentCreated?: (comment: CommentListItem) => void
}

const MAX_CONTENT_LENGTH = 4000

export function CommentForm(props: CommentFormProps) {
  const { hasAccessToken, hasRefreshToken, displayName, accountIdentity, accountGeneration, isCurrentSession } = useAuthSession()
  const hasAuthSession = hasAccessToken || hasRefreshToken
  const owner = JSON.stringify([props.animeID, accountIdentity, accountGeneration, hasAuthSession])
  return <SessionCommentForm key={owner} {...props} hasAuthSession={hasAuthSession} displayName={displayName} isCurrentSession={isCurrentSession} />
}

function SessionCommentForm({
  animeID, onCommentCreated, hasAuthSession, displayName, isCurrentSession,
}: CommentFormProps & { hasAuthSession: boolean; displayName: string; isCurrentSession: () => boolean }) {
  const router = useRouter()

  const [content, setContent] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const [successMessage, setSuccessMessage] = useState<string | null>(null)

  const requestGeneration = useRef(0)
  useEffect(() => () => { requestGeneration.current += 1 }, [])

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()

    if (isSubmitting) return

    const trimmedContent = content.trim()

    if (!hasAuthSession || !isCurrentSession()) {
      setErrorMessage('Anmeldung erforderlich. Bitte melde dich zuerst an.')
      setSuccessMessage(null)
      return
    }

    if (!trimmedContent) {
      setErrorMessage('content ist erforderlich')
      setSuccessMessage(null)
      return
    }
    if (trimmedContent.length > MAX_CONTENT_LENGTH) {
      setErrorMessage('content ist zu lang (max 4000 zeichen)')
      setSuccessMessage(null)
      return
    }

    const generation = ++requestGeneration.current
    try {
      setIsSubmitting(true)
      setErrorMessage(null)
      setSuccessMessage(null)

      const response = await createAnimeComment(animeID, {
        content: trimmedContent,
      })

      if (generation !== requestGeneration.current || !isCurrentSession()) return
      setContent('')
      setSuccessMessage('Kommentar gespeichert.')
      onCommentCreated?.(response.data)
      router.refresh()
    } catch (error) {
      if (generation !== requestGeneration.current || !isCurrentSession()) return
      if (error instanceof ApiError) {
        if (error.status === 429 && error.retryAfterSeconds && error.retryAfterSeconds > 0) {
          setErrorMessage(`Zu viele Anfragen. Bitte in ${error.retryAfterSeconds} Sekunden erneut versuchen.`)
        } else {
          setErrorMessage(error.message)
        }
      } else {
        setErrorMessage('Kommentar konnte nicht gespeichert werden.')
      }
      setSuccessMessage(null)
    } finally {
      if (generation === requestGeneration.current && isCurrentSession()) setIsSubmitting(false)
    }
  }

  return (
    <section className={styles.wrapper} aria-label="Kommentar schreiben">
      <h3>Kommentar schreiben</h3>
      <form className={styles.form} onSubmit={handleSubmit}>
        <p className={styles.authInfo}>
          Angemeldet als: {hasAuthSession ? displayName || 'bekannter Benutzer' : 'nicht angemeldet'}
        </p>

        <label className={styles.fieldLabel} htmlFor="content">
          Kommentar
        </label>
        <textarea
          id="content"
          name="content"
          className={styles.textarea}
          maxLength={MAX_CONTENT_LENGTH}
          rows={4}
          value={content}
          onChange={(event) => setContent(event.target.value)}
          disabled={isSubmitting}
          required
        />

        <button className={styles.submitButton} type="submit" disabled={isSubmitting || !hasAuthSession}>
          {isSubmitting ? 'Speichern...' : hasAuthSession ? 'Kommentar absenden' : 'Anmeldung erforderlich'}
        </button>
      </form>

      {errorMessage ? <div className={styles.errorBox} role="alert">{errorMessage}</div> : null}
      {successMessage ? <div className={styles.successBox} role="status">{successMessage}</div> : null}
    </section>
  )
}

