                    <h4 className={styles.blockTitle}>Weitere Assets</h4>
                    <span className={styles.blockCount}>{episode.media_assets.length}</span>
                  </div>
                  <div className={styles.mediaGrid}>
                    {episode.media_assets.map((asset) => (
